module.exports = {
  env: {
    browser: true,
    es2021: true,
    node: true,
  },
  extends: [
    'eslint:recommended',
    '@typescript-eslint/recommended',
  ],
  parser: '@typescript-eslint/parser',
  parserOptions: {
    ecmaVersion: 'latest',
    sourceType: 'module',
  },
  plugins: [
    '@typescript-eslint',
  ],
  rules: {
    // TypeScript specific rules
    '@typescript-eslint/no-unused-vars': 'warn',
    '@typescript-eslint/no-explicit-any': 'warn',
    '@typescript-eslint/explicit-function-return-type': 'off',
    '@typescript-eslint/explicit-module-boundary-types': 'off',
    '@typescript-eslint/no-inferrable-types': 'off',

    // General rules
    'no-console': 'warn',
    'no-debugger': 'warn',
    'no-unused-vars': 'off', // Handled by TypeScript
    'prefer-const': 'error',
    'no-var': 'error',
  },
  ignorePatterns: [
    'node_modules/',
    'dist/',
    'build/',
    'coverage/',
    '*.config.js',
  ],
};

import { VercelRequest, VercelResponse } from '@vercel/node';
import { GoogleGenAI, Type } from '@google/genai';

const ai = process.env.GOOGLE_API_KEY
  ? new GoogleGenAI({ apiKey: process.env.GOOGLE_API_KEY })
  : null;

export default async function handler(req: VercelRequest, res: VercelResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }
  if (!ai) {
    return res.status(503).json({ error: 'AI service not available' });
  }
  const { concept } = req.body;
  if (!concept) {
    return res.status(400).json({ error: 'Concept is required' });
  }
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `You are Maya, an AI brand strategist for luxury brands. A user wants to create a short video reel based on the following concept: "${concept}". Your task is to break this concept down into a 3-scene storyboard. For each scene, write a concise, cinematic prompt that an AI video generator can use. Respond in JSON format.`,
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            scenes: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  scene: { type: Type.INTEGER },
                  prompt: { type: Type.STRING },
                },
              },
            },
          },
        },
      },
    });
    const json = JSON.parse(response.text?.trim() || '{}');
    res.json(json);
  } catch (error) {
    res.status(500).json({ error: 'Failed to draft storyboard' });
  }
}

import React, { ComponentType, useEffect } from 'react';
import { Route, useLocation, Redirect } from "wouter";
import { queryClient } from "./lib/queryClient";
import { QueryClientProvider } from "@tanstack/react-query";
import { ProtectedRoute } from './components/ProtectedRoute';
import { Toaster } from "./components/ui/toaster";
import { TooltipProvider } from "./components/ui/tooltip";
import { StackProvider, StackTheme, StackHandler } from "@stackframe/react";
import { stackClientApp } from "./stack";
import { useAuth } from "./hooks/use-auth";
import { useQuery } from "@tanstack/react-query";
import { redirectToHttps, detectBrowserIssues, showDomainHelp } from "./utils/browserCompat";
import { optimizeImageLoading, enableServiceWorkerCaching } from "./utils/performanceOptimizations";
import { optimizeRuntime } from "./utils/webVitals";

// Core pages (loaded immediately) - BRAND STUDIO IS PRIMARY
import BrandStudioPage from "./pages/BrandStudioPage";
import AppLayout from "./pages/AppLayout";

// Import all pages directly to ensure they're included in the main bundle
import BusinessLanding from "./pages/business-landing";
import SimpleTraining from "./pages/simple-training";
import SimpleCheckout from "./pages/simple-checkout";
import PaymentSuccess from "./pages/payment-success";
import ThankYou from "./pages/thank-you";

// Components
import { PageLoader } from "./components/PageLoader";

// Smart Home component - Routes authenticated users to Brand Studio
function SmartHome() {
  const [, setLocation] = useLocation();
  const { isAuthenticated, isLoading } = useAuth();

  // Fetch user model status to determine training completion
  const { data: userModel, isLoading: isModelLoading } = useQuery({
    queryKey: ['/api/user-model'],
    enabled: isAuthenticated,
    retry: false,
    staleTime: 30 * 1000
  });

  useEffect(() => {
    if (!isLoading && !isModelLoading && isAuthenticated) {
      // Check training status and route accordingly
      if (!userModel || (userModel as any).trainingStatus !== 'completed') {
        console.log('🎯 User authenticated but needs training, redirecting to simple-training');
        setLocation('/simple-training');
      } else {
        console.log('✅ User authenticated with completed training, redirecting to Brand Studio');
  setLocation('/app');
      }
    } else if (!isLoading && !isAuthenticated) {
      console.log('🔍 User not authenticated, staying on landing page');
    }
  }, [isAuthenticated, isLoading, isModelLoading, userModel, setLocation]);

  // Show loading while determining auth state and training status
  if (isLoading || (isAuthenticated && isModelLoading)) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin w-8 h-8 border-4 border-black border-t-transparent rounded-full" />
      </div>
    );
  }

  // For unauthenticated users, show landing page content
  if (!isAuthenticated) {
    return null; // Let the route system handle showing BusinessLanding
  }

  // For authenticated users, redirect will happen in useEffect
  return null;
}

// Protected wrapper component that handles Stack Auth authentication

function Router() {
  return (
    <div>
      {/* STACK AUTH HANDLER - Must be first to catch authentication routes */}
      <Route path="/handler/:path*" component={HandlerRoutes} />

      {/* HOME ROUTE - Smart routing based on authentication and training status */}
      <Route path="/" component={() => {
        const { isAuthenticated, isLoading } = useAuth();

        if (isLoading) {
          return <PageLoader />;
        }

        if (isAuthenticated) {
          return <SmartHome />;
        }

        return <BusinessLanding />;
      }} />

      {/* PUBLIC ROUTES */}
      <Route path="/business" component={BusinessLanding} />

      {/* PAYMENT FLOW */}
      <Route path="/simple-checkout" component={SimpleCheckout} />
      <Route path="/thank-you" component={ThankYou} />
      <Route path="/payment-success" component={PaymentSuccess} />

      {/* PROTECTED ROUTES */}

      {/* AI TRAINING WORKFLOW */}
      <Route path="/simple-training" component={(props) => (
        <ProtectedRoute component={SimpleTraining} {...props} />
      )} />

      {/* NEW TABBED UI ROUTE */}
      <Route
        path="/app"
        component={(props) => (
          <ProtectedRoute component={AppLayout} {...props} />
        )}
      />



    </div>
  );
}

// Stack Auth Handler component for authentication routes
function HandlerRoutes({ params }: { params: { [key: string]: string } }) {
  const handlerPath = (params["path*"] || params["0"] || '').replace(/[)}]+$/, '');
  return <StackHandler app={stackClientApp} location={handlerPath} fullPage />;
}

function AppWithProvider() {
  return (
    <QueryClientProvider client={queryClient}>
      <StackProvider app={stackClientApp}>
        <StackTheme>
          <TooltipProvider>
            <App />
            <Toaster />
          </TooltipProvider>
        </StackTheme>
      </StackProvider>
    </QueryClientProvider>
  );
}

function App() {
  // Enhanced domain access handling
  useEffect(() => {
    try {
      console.log('SSELFIE Studio: App initializing...');

      // Only apply redirects for production domain, not localhost
      if (window.location.hostname !== 'localhost' && !window.location.hostname.includes('replit')) {
        // Force HTTPS redirect if needed
        if (window.location.protocol === 'http:' && window.location.hostname === 'sselfie.ai') {
          window.location.href = window.location.href.replace('http:', 'https:');
          return;
        }

        // Handle www subdomain redirect
        if (window.location.hostname === 'www.sselfie.ai') {
          window.location.href = window.location.href.replace('www.sselfie.ai', 'sselfie.ai');
          return;
        }
      }

      // Check for domain access issues
      const issues = detectBrowserIssues();
      if (issues.length > 0) {
        console.warn('Browser compatibility issues detected:', issues);
        showDomainHelp();
      }

      console.log('SSELFIE Studio: Domain access validated, app ready');

      // Phase 4: Runtime performance optimizations
      optimizeImageLoading();
      enableServiceWorkerCaching();
      optimizeRuntime();
    } catch (error) {
      console.error('Error in App initialization:', error);
    }
  }, []);

  console.log('SSELFIE Studio: App rendering...');

  return (
    <>
      <Router />
    </>
  );
}

export default AppWithProvider;

import React, { useState, useEffect } from 'react';
import { useLocation } from 'wouter';
import { useAuth } from '@/hooks/use-auth';

interface AdminNavigationProps {
  transparent?: boolean;
}

export function AdminNavigation({ transparent = true }: AdminNavigationProps) {
  const [location, setLocation] = useLocation();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { user } = useAuth();
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      const isScrolled = window.scrollY > 50;
      setScrolled(isScrolled);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Ensure page starts at top
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const isActive = (path: string) => {
    if (path === '/admin-dashboard' && location === '/admin-dashboard') return true;
    if (path !== '/admin-dashboard' && location.startsWith(path)) return true;
    return false;
  };

  // Use actual authenticated user without fallback to prevent auth conflicts
  const currentAccount = user?.email;

  // Admin navigation items
  const navItems = [
    { path: '/workspace', label: 'Workspace' },
    { path: '/visual-editor', label: 'Visual Editor' },
    { path: '/analytics', label: 'Analytics' },
  ];

  // Removed account switching to prevent auth conflicts

  const handleLogout = () => {
    window.location.href = '/api/logout';
  };

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
      scrolled || !transparent ? 'bg-black/80 backdrop-blur-md' : 'bg-transparent'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-6">
        <div className="flex items-center justify-between">
          <button 
            onClick={(e) => {
              e.preventDefault();
              if (location === '/admin-dashboard') {
                window.scrollTo({ top: 0, behavior: 'smooth' });
              } else {
                setLocation("/admin-dashboard");
              }
            }}
            className="font-serif text-xl font-light tracking-wide text-white hover:opacity-70 transition-opacity duration-300"
          >
            SSELFIE ADMIN
          </button>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-6 lg:space-x-10">
            {navItems.map((item) => (
              <button
                key={item.path}
                onClick={() => setLocation(item.path)}
                className={`text-xs uppercase tracking-[0.4em] transition-all duration-300 ${
                  isActive(item.path)
                    ? 'text-white'
                    : 'text-white/80 hover:text-white'
                }`}
              >
                {item.label}
              </button>
            ))}

            {/* User Display */}
            <div className="flex items-center space-x-2">
              <div className="w-px h-4 bg-white/20"></div>
              <div className="text-xs text-white/60">
                {currentAccount ? currentAccount.split('@')[0] : 'Admin'}
              </div>
              <div className="w-px h-4 bg-white/20"></div>
            </div>

            <button
              onClick={handleLogout}
              className="text-xs uppercase tracking-[0.4em] text-white/80 hover:text-white transition-all duration-300"
            >
              Logout
            </button>
          </div>

          {/* Mobile Menu Button - Minimalistic MENU text */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden text-xs uppercase tracking-[0.4em] text-white/80 hover:text-white transition-all duration-300"
          >
            Menu
          </button>
        </div>

        {/* Mobile Menu */}
        {mobileMenuOpen && (
          <div className="md:hidden absolute top-full left-0 right-0 bg-black/95 backdrop-blur-md border-t border-white/10">
            <div className="px-4 py-6 space-y-4">
              {navItems.map((item) => (
                <button
                  key={item.path}
                  onClick={() => {
                    setLocation(item.path);
                    setMobileMenuOpen(false);
                  }}
                  className={`block w-full text-left text-xs uppercase tracking-[0.4em] transition-all duration-300 ${
                    isActive(item.path)
                      ? 'text-white'
                      : 'text-white/80 hover:text-white'
                  }`}
                >
                  {item.label}
                </button>
              ))}

              {/* Mobile User Display */}
              <div className="pt-4 border-t border-white/10">
                <div className="text-xs text-white/60">
                  {currentAccount ? currentAccount.split('@')[0] : 'Admin'}
                </div>
              </div>

              <button
                onClick={() => {
                  handleLogout();
                  setMobileMenuOpen(false);
                }}
                className="block w-full text-left text-xs uppercase tracking-[0.4em] text-white/80 hover:text-white transition-all duration-300 pt-4 border-t border-white/10"
              >
                Logout
              </button>
            </div>
          </div>
        )}
      </div>
    </nav>
  );
}

import React from 'react';

interface ErrorBoundaryProps {
  children: React.ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('Error caught by boundary:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen flex items-center justify-center bg-white p-8">
          <div className="text-center max-w-md">
            <h2 className="text-2xl font-light mb-4">Something went wrong</h2>
            <p className="text-gray-600 mb-6">We encountered an issue loading this page.</p>
            <button 
              onClick={() => window.location.reload()}
              className="px-6 py-2 bg-black text-white hover:bg-gray-800"
            >
              Refresh Page
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default ErrorBoundary;

import React, { useState } from 'react';

interface GeneratedImagePreviewProps {
  imageUrls: string[];
  isLoading: boolean;
  concept?: any;
  onSave?: (imageUrls: string[]) => void;
}

const skeletons = Array.from({ length: 2 });

const GeneratedImagePreview: React.FC<GeneratedImagePreviewProps> = ({ 
  imageUrls, 
  isLoading, 
  concept,
  onSave 
}) => {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [savedImages, setSavedImages] = useState<Set<string>>(new Set());

  const downloadImage = (imageUrl: string, filename: string) => {
    try {
      const link = document.createElement('a');
      link.href = imageUrl;
      link.download = filename;
      link.target = '_blank';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error('Error downloading image:', error);
    }
  };

  const handleSaveImage = async (imageUrl: string) => {
    try {
      console.log('🔄 Attempting to save image:', imageUrl);
      console.log('🔄 Concept data:', concept);

      const response = await fetch('/api/save-image', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          imageUrl,
          source: 'maya_generation',
          prompt: concept?.fluxPrompt || concept?.title || 'Maya AI Generation'
        }),
        credentials: 'include'
      });

      console.log('📊 Save response status:', response.status);

      if (response.ok) {
        const result = await response.json();
        console.log('✅ Save response:', result);
        setSavedImages(prev => new Set([...prev, imageUrl]));
        console.log('✅ Image saved to gallery successfully');

        // Show success feedback
        alert('Image saved to gallery!');
      } else {
        const errorData = await response.json().catch(() => ({ error: 'Unknown error' }));
        console.error('❌ Failed to save image:', response.status, errorData);
        alert(`Failed to save image: ${errorData.error || 'Unknown error'}`);
      }
    } catch (error) {
      console.error('❌ Error saving image:', error);
      alert(`Error saving image: ${error.message}`);
    }
  };

  const handleSaveAll = async () => {
    console.log('🔄 Attempting to save all images:', imageUrls);

    try {
      // Save each image individually 
      for (const imageUrl of imageUrls) {
        await handleSaveImage(imageUrl);
      }

      // Also call the onSave callback if provided
      if (onSave && imageUrls.length > 0) {
        onSave(imageUrls);
      }

      console.log('✅ All images saved successfully');
    } catch (error) {
      console.error('❌ Error saving all images:', error);
      alert(`Error saving images: ${error.message}`);
    }
  };

  return (
    <>
      <div style={{ marginTop: '16px' }}>
        {isLoading ? (
          <div>
            <p style={{ fontSize: '12px', color: '#666', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.2em' }}>
              Generating images...
            </p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '8px' }}>
              {skeletons.map((_, i) => (
                <div 
                  key={i} 
                  style={{ 
                    background: '#f0f0f0', 
                    borderRadius: '8px', 
                    aspectRatio: '4/5',
                    animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite'
                  }} 
                />
              ))}
            </div>
          </div>
        ) : imageUrls.length > 0 ? (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
              <p style={{ fontSize: '12px', color: '#666', margin: 0, textTransform: 'uppercase', letterSpacing: '0.2em' }}>
                Generated Images
              </p>
              <button
                onClick={handleSaveAll}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#666',
                  cursor: 'pointer',
                  fontSize: '11px',
                  textTransform: 'uppercase',
                  letterSpacing: '0.2em',
                  textDecoration: 'underline'
                }}
              >
                Save All to Gallery
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '8px' }}>
              {imageUrls.map((url, index) => (
                <div key={index} style={{ position: 'relative', cursor: 'pointer' }}>
                  <img
                    src={url}
                    alt={`Generated ${index + 1}`}
                    style={{ 
                      width: '100%', 
                      aspectRatio: '4/5',
                      objectFit: 'cover', 
                      borderRadius: '8px',
                      background: '#f0f0f0'
                    }}
                    onClick={() => setSelectedImage(url)}
                  />

                  {/* Overlay with actions */}
                  <div style={{
                    position: 'absolute',
                    top: '8px',
                    right: '8px',
                    display: 'flex',
                    gap: '4px'
                  }}>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleSaveImage(url);
                      }}
                      style={{
                        background: savedImages.has(url) ? '#ff4444' : 'rgba(255,255,255,0.9)',
                        border: 'none',
                        borderRadius: '50%',
                        width: '28px',
                        height: '28px',
                        cursor: 'pointer',
                        fontSize: '14px',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                      }}
                      title={savedImages.has(url) ? 'Saved to gallery' : 'Save to gallery'}
                    >
                      {savedImages.has(url) ? '♥' : '♡'}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : null}
      </div>

      {/* Full-screen preview modal */}
      {selectedImage && (
        <div style={{
          position: 'fixed',
          inset: 0,
          background: 'rgba(0,0,0,0.95)',
          zIndex: 1000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexDirection: 'column',
          padding: '20px'
        }}>
          <div style={{
            width: '100%',
            maxWidth: '500px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
          }}>
            <img
              src={selectedImage}
              alt="Full preview"
              style={{
                width: '100%',
                height: 'auto',
                objectFit: 'contain',
                borderRadius: '12px',
                marginBottom: '24px',
                maxHeight: '70vh'
              }}
            />

            <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
              <button
                onClick={() => handleSaveImage(selectedImage)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: savedImages.has(selectedImage) ? '#ff4444' : '#fff',
                  cursor: 'pointer',
                  fontSize: '14px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px'
                }}
              >
                {savedImages.has(selectedImage) ? '♥' : '♡'} 
                {savedImages.has(selectedImage) ? 'Saved' : 'Save to Gallery'}
              </button>

              <button
                onClick={() => downloadImage(selectedImage, `maya-generation-${Date.now()}.png`)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#fff',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}
              >
                ⬇ Download
              </button>

              <button
                onClick={() => setSelectedImage(null)}
                style={{
                  background: 'none',
                  border: 'none',
                  color: '#888',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}
              >
                ✕ Close
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default GeneratedImagePreview;

import React, { FC, MouseEvent, ReactNode } from 'react';
interface HeroFullBleedProps {
  backgroundImage: string;
  tagline?: string;
  title: string | ReactNode;
  subtitle?: string;
  ctaText?: string;
  ctaLink?: string;
  onCta?: () => void;
  overlay?: number;
  alignment?: 'left' | 'center';
  fullHeight?: boolean;
}

export const HeroFullBleed: FC<HeroFullBleedProps> = ({
  backgroundImage,
  tagline,
  title,
  subtitle,
  ctaText,
  ctaLink,
  onCta,
  overlay = 0.4,
  alignment = 'center',
  fullHeight = true
}) => {
  const handleCTAClick = (e: MouseEvent) => {
    if (onCta) {
      e.preventDefault();
      onCta();
      return;
    }

    if (ctaLink?.startsWith('#')) {
      e.preventDefault();
      const element = document.querySelector(ctaLink);
      element?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section 
      className={`relative w-full ${fullHeight ? 'h-screen' : 'min-h-[600px]'} flex items-center overflow-hidden bg-luxury-black`}
    >
      {/* Background Image */}
      <div className="absolute inset-0 z-0">
        <img 
          src={backgroundImage} 
          alt=""
          className="w-full h-full object-cover editorial-hover"
        />
        <div 
          className="absolute inset-0 bg-black"
          style={{ opacity: overlay }}
        />
      </div>

      {/* Content Container */}
      <div className="relative z-10 w-full h-full flex items-center justify-center">
        <div className={`max-w-6xl mx-auto px-8 ${alignment === 'center' ? 'text-center' : ''}`}>

          {/* Top Tagline */}
          {tagline && (
            <p className="text-xs tracking-ultra-wide uppercase text-white/60 mb-8 system-font font-light">
              {tagline}
            </p>
          )}

          {/* Main Title - Ultra-Stretched */}
