export class LuxuryErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Maya Error Boundary caught an error:', error, errorInfo);

    // In production, you might want to send this to an error reporting service
    if (process.env.NODE_ENV === 'production') {
      // Example: errorReportingService.captureException(error, { extra: errorInfo });
    }
  }

  public render() {
    if (this.state.hasError) {
      return this.props.fallback || <LuxuryErrorState error={this.state.error} />;
    }

    return this.props.children;
  }
}

export default LuxuryErrorBoundary;

import React, { useState, useRef, useEffect } from 'react';
import { useMemoryCleanup } from '../hooks/useMemoryCleanup';

interface OptimizedImageProps {
  src: string;
  alt: string;
  className?: string;
  placeholder?: string;
  width?: number;
  height?: number;
  priority?: boolean;
  onLoad?: () => void;
  onError?: () => void;
}

/**
 * Phase 4: Optimized Image Component with advanced loading strategies
 * Features: Progressive loading, WebP support, intersection observer, memory cleanup
 */
export const OptimizedImage: React.FC<OptimizedImageProps> = ({
  src,
  alt,
  className = "",
  placeholder,
  width,
  height,
  priority = false,
  onLoad,
  onError
}) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isInView, setIsInView] = useState(priority);
  const [currentSrc, setCurrentSrc] = useState<string | null>(priority ? src : null);
  const [hasError, setHasError] = useState(false);
  const imgRef = useRef<HTMLImageElement>(null);
  const { addCleanup } = useMemoryCleanup();

  // Generate WebP version if possible
  const getOptimizedSrc = (originalSrc: string): string => {
    // Check if browser supports WebP
    if (typeof window !== 'undefined') {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      if (ctx && canvas.toDataURL('image/webp').indexOf('data:image/webp') === 0) {
        // If it's an S3 URL, try to get WebP version
        if (originalSrc.includes('amazonaws.com') || originalSrc.includes('s3.')) {
          const webpSrc = originalSrc.replace(/\.(jpg|jpeg|png)$/i, '.webp');
          return webpSrc;
        }
      }
    }
    return originalSrc;
  };

  // Intersection Observer for lazy loading
  useEffect(() => {
    if (priority || !imgRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsInView(true);
            setCurrentSrc(getOptimizedSrc(src));
            observer.unobserve(entry.target);
          }
        });
      },
      {
        rootMargin: '50px', // Start loading 50px before image comes into view
        threshold: 0.1
      }
    );

    observer.observe(imgRef.current);

    addCleanup(() => {
      if (imgRef.current) {
        observer.unobserve(imgRef.current);
      }
      observer.disconnect();
    });

    return () => observer.disconnect();
  }, [src, priority, addCleanup]);

  // Handle image load
  const handleLoad = () => {
    setIsLoaded(true);
    onLoad?.();
  };

  // Handle image error (fallback to original format)
  const handleError = () => {
    if (currentSrc !== src && !hasError) {
      // Try original format if WebP fails
      setCurrentSrc(src);
      setHasError(true);
    } else {
      setHasError(true);
      onError?.();
    }
  };

  // Progressive loading effect
  const imageStyle: React.CSSProperties = {
    opacity: isLoaded ? 1 : 0,
    transition: 'opacity 0.3s ease-in-out',
    width: width ? `${width}px` : '100%',
    height: height ? `${height}px` : 'auto',
  };

  return (
    <div 
      ref={imgRef}
      className={`relative overflow-hidden ${className}`}
      style={{ width: width ? `${width}px` : '100%', height: height ? `${height}px` : 'auto' }}
    >
      {/* Placeholder/Loading state */}
      {!isLoaded && (
        <div 
          className="absolute inset-0 bg-gray-100 animate-pulse flex items-center justify-center"
          style={{ width: '100%', height: height ? `${height}px` : '200px' }}
        >
          {placeholder ? (
            <img src={placeholder} alt="" className="w-full h-full object-cover opacity-50" />
          ) : (
            <div className="text-gray-400 text-sm">Loading...</div>
          )}
        </div>
      )}

      {/* Main image */}
      {(isInView && currentSrc) && (
        <img
          src={currentSrc}
          alt={alt}
          style={imageStyle}
          className="absolute inset-0 w-full h-full object-cover"
          loading={priority ? "eager" : "lazy"}
          decoding="async"
          onLoad={handleLoad}
          onError={handleError}
          // Performance optimizations
          fetchPriority={priority ? "high" : "low"}
        />
      )}

      {/* Error state */}
      {hasError && !isLoaded && (
        <div className="absolute inset-0 bg-gray-200 flex items-center justify-center">
          <div className="text-gray-500 text-sm">Failed to load image</div>
        </div>
      )}
    </div>
  );
};

export default OptimizedImage;

import React, { ComponentType, useEffect } from 'react';
import { useLocation } from 'wouter';
import { useAuth } from '../hooks/use-auth';
import { PageLoader } from './PageLoader'; // Ensure PageLoader is imported

// This is now the single source of truth for protecting routes.
export function ProtectedRoute({ component: Component, ...props }: { component: ComponentType<any>, [key: string]: any }) {
  const { isAuthenticated, isLoading } = useAuth();
  const [, setLocation] = useLocation();

  useEffect(() => {
    if (!isLoading && !isAuthenticated) {
      // Redirect to the Stack Auth sign-in page if not authenticated.
      setLocation('/handler/sign-in');
    }
  }, [isLoading, isAuthenticated, setLocation]);

  // Show a loading spinner while authentication is in progress.
  if (isLoading || !isAuthenticated) {
    return <PageLoader />;
  }

  // If authenticated, render the requested component.
  return <Component {...props} />;
}

import React, { useState } from 'react';
import { Button } from './ui/button';
import { apiRequest } from '../lib/queryClient';
import { useToast } from '../hooks/use-toast';

interface RollbackButtonProps {
  filePath: string;
  className?: string;
}

export function RollbackButton({ filePath, className }: RollbackButtonProps) {
  const [isRollingBack, setIsRollingBack] = useState(false);
  const { toast } = useToast();

  const handleRollback = async () => {
    if (!confirm(`Are you sure you want to rollback ${filePath}? This will restore the previous version.`)) {
      return;
    }

    setIsRollingBack(true);
    try {
      const response = await apiRequest('POST', '/api/admin/rollback-file', {
        filePath,
        adminToken: 'sandra-admin-2025'
      });

      if (response.ok) {
        toast({
          title: "File Rolled Back",
          description: `${filePath} has been restored to its previous version.`,
        });

        // Trigger page reload to show changes
        setTimeout(() => {
          window.location.reload();
        }, 1000);
      } else {
        throw new Error('Rollback failed');
      }
    } catch (error) {
      toast({
        title: "Rollback Failed",
        description: "Could not rollback the file. Please try again.",
      });
    } finally {
      setIsRollingBack(false);
    }
  };

  return (
    <Button
      onClick={handleRollback}
      disabled={isRollingBack}
      variant="outline"
      size="sm"
      className={`border-red-200 text-red-600 hover:bg-red-50 ${className}`}
    >
      {isRollingBack ? 'Rolling back...' : 'Rollback'}
    </Button>
  );
}

import React, { useState, useEffect } from 'react';
import { apiRequest } from '../lib/queryClient';
import VideoPreview from './VideoPreview';

interface StoryStudioModalProps {
  imageId: string;
  imageUrl: string;
  imageSource?: string; // 'generated' or 'legacy'
  onClose: () => void;
  onSuccess: () => void;
}

const StoryStudioModal: React.FC<StoryStudioModalProps> = ({ imageId, imageUrl, imageSource, onClose, onSuccess }) => {
  const [motionPrompt, setMotionPrompt] = useState('');
  const [mayaVideoPrompt, setMayaVideoPrompt] = useState<string>('');
  const [isLoadingPrompt, setIsLoadingPrompt] = useState(true);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [videoJobId, setVideoJobId] = useState<string | null>(null);
  const [videoStatus, setVideoStatus] = useState<'idle' | 'generating' | 'completed' | 'failed'>('idle');
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);

  // Get Maya's video direction when component mounts
  useEffect(() => {
    const getMayaDirection = async () => {
      try {
        setIsLoadingPrompt(true);
        setError(null);

        console.log('🎬 Requesting Maya\'s video direction for image:', imageUrl);

        const response = await apiRequest('/api/maya/get-video-prompt', 'POST', {
          imageUrl: imageUrl
        });

        console.log('✅ Maya video direction received:', response);

        if (response.videoPrompt) {
          setMayaVideoPrompt(response.videoPrompt);
          setMotionPrompt(response.videoPrompt); // Pre-fill the input
        } else {
          throw new Error('No video prompt received from Maya');
        }

      } catch (error: any) {
        console.error('❌ Error getting Maya\'s video direction:', error);

        // Provide specific error feedback
        let errorMessage = 'Failed to get Maya\'s direction. You can still create your own prompt.';

        if (error.message?.includes('401')) {
          errorMessage = 'Authentication required. Please log in and try again.';
        } else if (error.message?.includes('400')) {
          errorMessage = 'Invalid image URL. Please try a different image.';
        } else if (error.message?.includes('500')) {
          errorMessage = 'Maya service is temporarily unavailable. You can create your own prompt.';
        }

        setError(errorMessage);
        setMotionPrompt('Slow zoom in with subtle movement and gentle lighting'); // Better fallback prompt
      } finally {
        setIsLoadingPrompt(false);
      }
    };

    getMayaDirection();
  }, [imageUrl]);

  // Poll video status
  useEffect(() => {
    if (!videoJobId || videoStatus !== 'generating') return;

    const pollStatus = async () => {
      try {
        const res = await fetch(`/api/video/status/${videoJobId}`, {
          credentials: 'include'
        });

        if (res.ok) {
          const data = await res.json();

          if (data.status === 'completed' && data.videoUrl) {
            setVideoStatus('completed');
            setVideoUrl(data.videoUrl);
            setProgress(100);
            setLoading(false);
            console.log('✅ Video generation completed!');
          } else if (data.status === 'failed') {
            setVideoStatus('failed');
            setError(data.error || 'Video generation failed');
            setLoading(false);
            console.error('❌ Video generation failed:', data.error);
          } else if (data.status === 'processing') {
            setProgress(data.progress || 50);
            console.log(`🎬 Video generation progress: ${data.progress || 50}%`);
          }
        }
      } catch (error) {
        console.error('❌ Error checking video status:', error);
      }
    };

    const interval = setInterval(pollStatus, 3000); // Poll every 3 seconds
    return () => clearInterval(interval);
  }, [videoJobId, videoStatus]);

  const handleGenerate = async () => {
    if (!motionPrompt.trim()) return;

    setLoading(true);
    setError(null);

    try {
      console.log('🎬 Starting video generation for image:', imageId, 'with prompt:', motionPrompt);

      const res = await fetch('/api/video/generate-from-image', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          imageId: parseInt(imageId), // Ensure it's a number
          motionPrompt: motionPrompt.trim(),
          imageSource: imageSource || 'generated' // default to 'generated' if not provided
        }),
        credentials: 'include'
      });

      if (!res.ok) {
        const errorData = await res.json().catch(() => ({ error: 'Unknown error' }));
        const mergedMessage = [errorData.error, errorData.details].filter(Boolean).join(' – ');
        throw new Error(mergedMessage || 'Failed to generate video');
      }

      const result = await res.json();
      console.log('✅ Video generation started:', result);

      // Set video generation state
      setVideoJobId(result.jobId);
      setVideoStatus('generating');
      setProgress(10);

      // Don't close modal immediately - let user see progress
      // The VideoPreview component will handle the completion state

    } catch (err: any) {
      console.error('❌ Video generation error:', err);
      setError(err.message || 'Unknown error');
      setVideoStatus('failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <style>
        {`
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
