import React from 'react';
import { Button } from "@/components/ui/button";
import { useAuth } from "@/hooks/use-auth";
import { useStackApp } from "@stackframe/stack";
import { STACK_PROJECT_ID, STACK_PUBLISHABLE_CLIENT_KEY } from "@/env";

interface UnifiedLoginButtonProps {
  text: string;
  showBrand: boolean;
}

export default function UnifiedLoginButton({ text, showBrand }: UnifiedLoginButtonProps) {
  const { user, isAuthenticated, isLoading } = useAuth();
  let app;

  try {
    app = useStackApp();
  } catch (error) {
    console.warn('⚠️ Stack Auth not available:', error);
    app = null;
  }

  const handleLogin = async () => {
    console.log('🔍 UnifiedLoginButton: Login button clicked');
    console.log('🔍 UnifiedLoginButton: Stack Auth app available:', !!app);
    console.log('🔍 UnifiedLoginButton: Environment vars:', { STACK_PROJECT_ID, STACK_PUBLISHABLE_CLIENT_KEY });

    if (!app) {
      console.warn('⚠️ Stack Auth not available, using fallback');
      // Fallback to direct OAuth URL if Stack Auth fails
      const projectId = STACK_PROJECT_ID;
      const publishableKey = STACK_PUBLISHABLE_CLIENT_KEY;

      if (publishableKey) {
        console.log('🚀 UnifiedLoginButton: Redirecting to Stack Auth handler');
        window.location.href = `/handler/sign-in`;
      } else {
        console.error('❌ No Stack Auth configuration available');
      }
      return;
    }

    try {
      console.log('🚀 UnifiedLoginButton: Using Stack Auth SDK method');
      // ✅ Use proper Stack Auth SDK method
      await app.signInWithOAuth('google');
    } catch (error) {
      console.error('❌ Stack Auth: OAuth login failed:', error);
    }
  };

  const handleLogout = async () => {
    if (!app) {
      // Fallback logout
      window.location.href = '/';
      return;
    }

    try {
      // ✅ Use proper Stack Auth SDK method  
      await app.signOut();
      // Stack Auth handles redirect automatically
    } catch (error) {
      console.error('❌ Stack Auth: Logout error:', error);
      // Fallback to simple redirect
      window.location.href = '/';
    }
  };

  // If user is already logged in, show logout button  
  if (isAuthenticated && user) {
    return (
      <div className="text-center max-w-md mx-auto">
        {showBrand && (
          <h1 className="text-3xl font-bold mb-4">SSELFIE Studio</h1>
        )}

        <div className="bg-white p-6 rounded-lg shadow-lg">
          <div className="text-center space-y-4">
            <p className="text-lg">Welcome back!</p>
            <p className="text-sm text-gray-600">{user.email}</p>
            <Button 
              onClick={handleLogout}
              variant="outline"
              className="w-full"
            >
              Sign Out
            </Button>
          </div>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="text-center max-w-md mx-auto">
        {showBrand && (
          <h1 className="text-3xl font-bold mb-4">SSELFIE Studio</h1>
        )}

        <div className="bg-white p-6 rounded-lg shadow-lg">
          <div className="text-center space-y-4">
            <div className="animate-spin w-8 h-8 border-4 border-primary border-t-transparent rounded-full mx-auto"></div>
            <p className="text-sm text-gray-600">Loading...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="text-center max-w-md mx-auto">
      {showBrand && (
        <h1 className="text-3xl font-bold mb-4">SSELFIE Studio</h1>
      )}

      <div className="bg-white p-6 rounded-lg shadow-lg">
        <h2 className="text-xl font-semibold mb-4">Sign In to Continue</h2>

        <div className="space-y-4">
          <p className="text-sm text-gray-600 mb-4">
            Access your AI personal branding studio with secure OAuth login
          </p>

          <Button 
            onClick={handleLogin}
            className="w-full"
          >
            {text}
          </Button>
        </div>

        <div className="mt-4 text-xs text-gray-500 text-center">
          Secure login powered by Stack Auth
        </div>
      </div>
    </div>
  );
}

import { useQuery } from "@tanstack/react-query";
import { useState, useEffect } from "react";

interface UsageStatus {
  canGenerate: boolean;
  remainingGenerations: number;
  totalUsed: number;
  totalAllowed: number;
  monthlyUsed?: number;
  monthlyAllowed?: number;
  resetDate?: string;
  reason?: string;
}

interface UsageStats {
  plan: string;
  planLimits: {
    totalGenerations: number | null;
    monthlyGenerations: number | null;
    cost: number;
    description: string;
    resetMonthly: boolean;
  };
  usage: UsageStatus;
  totalCostIncurred: number;
  lastGenerationAt: string | null;
}

export default function UsageTracker() {
  const [isExpanded, setIsExpanded] = useState(false);

  const { data: usageStatus } = useQuery<UsageStatus>({
    queryKey: ["/api/usage/status"],
    refetchInterval: 30000, // Refresh every 30 seconds
  });

  const { data: usageStats } = useQuery<UsageStats>({
    queryKey: ["/api/usage/stats"],
    refetchInterval: 60000, // Refresh every minute
  });

  if (!usageStatus) {
    return null;
  }

  const getStatusColor = () => {
    // Admin users always show green
    if (usageStatus.remainingGenerations >= 999999) return "text-emerald-600";
    if (!usageStatus.canGenerate) return "text-red-500";
    if (usageStatus.remainingGenerations <= 10) return "text-yellow-600";
    return "text-emerald-600";
  };

  const getProgressPercentage = () => {
    if (usageStatus.monthlyAllowed) {
      // Monthly subscription
      return Math.min((usageStatus.monthlyUsed || 0) / usageStatus.monthlyAllowed * 100, 100);
    } else {
      // One-time AI Pack
      return Math.min(usageStatus.totalUsed / usageStatus.totalAllowed * 100, 100);
    }
  };

  const formatResetDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffDays = Math.ceil((date.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

    if (diffDays <= 0) return "Resets today";
    if (diffDays === 1) return "Resets tomorrow";
    return `Resets in ${diffDays} days`;
  };

  return (
    <div className="bg-white border border-gray-200 rounded-none">
      {/* Compact Header */}
      <div 
        className="p-4 cursor-pointer hover:bg-gray-50 transition-colors"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="text-sm font-medium text-gray-900">
              Usage
            </div>
            <div className={`text-sm font-bold ${getStatusColor()}`}>
              {usageStatus.remainingGenerations >= 999999 ? 'Unlimited' : `${usageStatus.remainingGenerations} remaining`}
            </div>
          </div>

          <div className="flex items-center gap-3">
            {!usageStatus.canGenerate && (
              <div className="text-xs text-red-500 font-medium">
                LIMIT REACHED
              </div>
            )}
            <div className="text-xs text-gray-400">
              {isExpanded ? "−" : "+"}
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        <div className="mt-2 w-full bg-gray-200 rounded-none h-1">
          <div 
            className={`h-1 rounded-none transition-all duration-300 ${
              usageStatus.canGenerate ? 'bg-emerald-500' : 'bg-red-500'
            }`}
            style={{ width: `${getProgressPercentage()}%` }}
          />
        </div>
      </div>

      {/* Expanded Details */}
      {isExpanded && usageStats && (
        <div className="border-t border-gray-200 p-4 space-y-4">
          {/* Plan Information */}
          <div>
            <div className="text-xs text-gray-500 uppercase tracking-wide font-medium mb-2">
              Current Plan
            </div>
            <div className="text-sm font-medium text-gray-900 mb-1">
              {usageStats.plan === 'ai-pack' ? 'SSELFIE AI Pack' : 
               usageStats.plan === 'studio-founding' ? 'Studio Founding' : 
               'Studio Standard'}
            </div>
            <div className="text-xs text-gray-600">
              {usageStats.planLimits.description}
            </div>
          </div>

          {/* Usage Details */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <div className="text-xs text-gray-500 mb-1">Used</div>
              <div className="text-sm font-medium text-gray-900">
                {usageStats.planLimits.resetMonthly 
                  ? `${usageStatus.monthlyUsed || 0} this month`
                  : `${usageStatus.totalUsed} total`
                }
              </div>
            </div>

            <div>
              <div className="text-xs text-gray-500 mb-1">Allowed</div>
              <div className="text-sm font-medium text-gray-900">
                {usageStats.planLimits.resetMonthly 
                  ? `${usageStatus.monthlyAllowed || 0}/month`
                  : `${usageStatus.totalAllowed} total`
                }
              </div>
            </div>
          </div>

          {/* Reset Information for Monthly Plans */}
          {usageStats.planLimits.resetMonthly && usageStatus.resetDate && (
            <div>
              <div className="text-xs text-gray-500 mb-1">Next Reset</div>
              <div className="text-sm font-medium text-gray-900">
                {formatResetDate(usageStatus.resetDate)}
              </div>
            </div>
          )}

          {/* Limit Reached Message */}
          {!usageStatus.canGenerate && usageStatus.reason && (
            <div className="bg-red-50 border border-red-200 p-3 rounded-none">
              <div className="text-sm text-red-800">
                {usageStatus.reason}
              </div>
              {usageStats.plan === 'ai-pack' && (
                <div className="mt-2">
                  <a 
                    href="/pricing" 
                    className="text-sm text-red-600 hover:text-red-700 underline"
                  >
                    Upgrade to Studio for monthly generations
                  </a>
                </div>
              )}
            </div>
          )}

          {/* Cost Information (for transparency) */}
          <div className="pt-2 border-t border-gray-100">
            <div className="text-xs text-gray-500 mb-1">Total Cost Incurred</div>
            <div className="text-sm text-gray-600">
              ${usageStats.totalCostIncurred.toFixed(4)} USD
            </div>
            <div className="text-xs text-gray-400 mt-1">
              Each generation costs ~$0.038 (4 images)
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, KeyboardEvent } from 'react';
import { Send, Mic, MicOff, Sparkles } from 'lucide-react';

interface Message {
  id: string;
  content: string;
  sender: 'user' | 'victoria';
  timestamp: Date;
  typing?: boolean;
}

export default function VictoriaChat() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  // Initialize with Sandra's authentic welcome
  useEffect(() => {
    const welcomeMessage: Message = {
      id: 'welcome',
      content: "Hey gorgeous! I'm Victoria, Sandra's AI voice twin. I literally sound EXACTLY like her - same energy, same realness, same 'your mess is your message' vibe. What are you working on today? Let's build something that actually works. 💫",
      sender: 'victoria',
      timestamp: new Date()
    };
    setMessages([welcomeMessage]);
  }, []);

  const sendMessage = async () => {
    if (!inputMessage.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      content: inputMessage,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputMessage('');
    setIsTyping(true);

    // Simulate typing delay for authenticity
    setTimeout(async () => {
      const response = await getVictoriaResponse(inputMessage);
      const victoriaMessage: Message = {
        id: (Date.now() + 1).toString(),
        content: response,
        sender: 'victoria',
        timestamp: new Date()
      };

      setMessages(prev => [...prev, victoriaMessage]);
      setIsTyping(false);
    }, 1500);
  };

  const getVictoriaResponse = async (input: string): Promise<string> => {
    // Sandra's authentic response patterns
    const responses = getSandraResponses(input);
    return responses[Math.floor(Math.random() * responses.length)];
  };

  const handleKeyPress = (e: KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  return (
    <div className="flex flex-col h-screen bg-white">
      {/* Header */}
      <div className="border-b border-gray-200 p-4 bg-white">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-gradient-to-r from-black to-gray-800 flex items-center justify-center">
            <Sparkles className="w-5 h-5 text-white" />
          </div>
          <div>
            <h2 className="text-xl font-serif text-black">Victoria</h2>
            <p className="text-sm text-gray-600">Sandra's AI Voice Twin • Always Online</p>
          </div>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message) => (
          <div
            key={message.id}
            className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                message.sender === 'user'
                  ? 'bg-black text-white'
                  : 'bg-gray-100 text-black'
              }`}
            >
              <p className="text-sm leading-relaxed">{message.content}</p>
              <p className="text-xs mt-1 opacity-70">
                {message.timestamp.toLocaleTimeString()}
              </p>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-gray-100 px-4 py-2 rounded-lg">
              <div className="flex space-x-1">
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
              </div>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="border-t border-gray-200 p-4 bg-white">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setIsListening(!isListening)}
            className={`p-2 rounded-full ${
              isListening ? 'bg-red-500 text-white' : 'bg-gray-100 text-gray-600'
            }`}
          >
            {isListening ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
          </button>

          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Ask Victoria anything..."
            className="flex-1 border border-gray-300 rounded-full px-4 py-2 focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent"
          />

          <button
            onClick={sendMessage}
            disabled={!inputMessage.trim()}
            className="bg-black text-white p-2 rounded-full hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
}

// Sandra's Authentic Response System
function getSandraResponses(input: string): string[] {
  const lowerInput = input.toLowerCase();

  // Brand & Photos
  if (lowerInput.includes('photo') || lowerInput.includes('brand') || lowerInput.includes('image')) {
    return [
      "Listen babe, you don't need a fancy photographer. Your phone + my strategy = magic. I went from basic selfies to 120K followers using literally just my phone. Here's exactly how to make your photos look expensive: Natural light is your best friend. Window light, golden hour, even cloudy days work better than harsh indoor lighting.",
      "Stop waiting for 'perfect' photos! I built my entire brand on authentic, real photos taken with my phone. Your audience wants to see the REAL you, not some overly polished version. That's actually what makes you magnetic - your authenticity, not perfection.",
      "Your brand photos should tell YOUR story. When I was starting, I didn't have professional shots either. But I had confidence and authenticity. Those two things will always beat expensive equipment. Show up as YOU, that's your superpower."
    ];
  }

  // Content & Posting
  if (lowerInput.includes('content') || lowerInput.includes('post') || lowerInput.includes('caption')) {
    return [
      "Content that converts? It's actually simple. Share your real story, not the highlight reel. My biggest breakthrough posts were about my struggles, not my wins. Your mess IS your message - stop hiding it and start owning it.",
      "Here's what works: Problem + Story + Solution. Start with what your audience is struggling with, share how you've been there too, then give them ONE actionable thing they can do today. Simple but powerful.",
      "Stop overthinking captions! Write like you're texting your best friend. That's it. My most viral posts feel like conversations because they ARE conversations. Just be real, be helpful, be you."
    ];
  }

  // Business & Money
  if (lowerInput.includes('business') || lowerInput.includes('money') || lowerInput.includes('income')) {
    return [
      "Building a real business? It's not about having it all figured out. I started with literally nothing but a phone and a story. 90 days later: 120K followers. Today: A business that actually works. Your story + my strategy = your empire.",
      "Money follows value, always. Stop thinking about what YOU want to sell and start thinking about what THEY need to buy. When you solve real problems with real solutions, the money comes naturally.",
      "Your transformation IS your business model. Whatever you've overcome, whatever you've figured out - there are people who need exactly that guidance. Package it, price it, sell it."
    ];
  }

  // Confidence & Mindset
  if (lowerInput.includes('confident') || lowerInput.includes('scared') || lowerInput.includes('afraid')) {
    return [
