                  </div>

                  {/* Creation Time */}
                  <div className="mt-2 text-xs text-zinc-400">
                    Created {new Date(workflow.createdAt).toLocaleString()}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { 
  CheckCircle, 
  AlertCircle, 
  PlayCircle, 
  Clock,
  User,
  Zap
} from 'lucide-react';

interface TaskStep {
  id: string;
  title: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  progress?: number;
  description?: string;
}

interface LuxuryProgressDisplayProps {
  taskId: string;
  agentName: string;
  steps: TaskStep[];
  overallProgress: number;
  status: 'pending' | 'planning' | 'executing' | 'validating' | 'completed' | 'failed';
  className?: string;
}

export default function LuxuryProgressDisplay({ 
  taskId, 
  agentName, 
  steps, 
  overallProgress, 
  status,
  className = ""
}: LuxuryProgressDisplayProps) {
  const getStatusIcon = (stepStatus: TaskStep['status']) => {
    switch (stepStatus) {
      case 'completed':
        return <CheckCircle className="h-4 w-4 text-emerald-500" />;
      case 'in_progress':
        return <PlayCircle className="h-4 w-4 text-blue-500 animate-pulse" />;
      case 'failed':
        return <AlertCircle className="h-4 w-4 text-red-500" />;
      default:
        return <Clock className="h-4 w-4 text-zinc-400" />;
    }
  };

  const getStatusColor = (stepStatus: TaskStep['status']) => {
    switch (stepStatus) {
      case 'completed':
        return 'bg-emerald-500';
      case 'in_progress':
        return 'bg-blue-500';
      case 'failed':
        return 'bg-red-500';
      default:
        return 'bg-zinc-300';
    }
  };

  const getOverallStatusBadge = () => {
    switch (status) {
      case 'planning':
        return <Badge variant="secondary">Planning</Badge>;
      case 'executing':
        return <Badge variant="default" className="bg-blue-500">Executing</Badge>;
      case 'validating':
        return <Badge variant="default" className="bg-amber-500">Validating</Badge>;
      case 'completed':
        return <Badge variant="default" className="bg-emerald-500">Completed</Badge>;
      case 'failed':
        return <Badge variant="destructive">Failed</Badge>;
      default:
        return <Badge variant="outline">Unknown</Badge>;
    }
  };

  return (
    <Card className={`border-zinc-200 bg-white ${className}`}>
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="font-serif text-lg font-light tracking-wide text-black">
              Task Execution
            </CardTitle>
            <div className="flex items-center space-x-2 mt-1">
              <User className="h-3 w-3 text-zinc-500" />
              <span className="text-sm text-zinc-600 tracking-wide">
                {agentName}
              </span>
              <span className="text-xs text-zinc-400">
                • ID: {taskId.slice(-8)}
              </span>
            </div>
          </div>
          {getOverallStatusBadge()}
        </div>

        <div className="mt-4">
          <div className="flex items-center justify-between mb-2">
            <span className="text-xs tracking-widest uppercase text-zinc-500 font-light">
              Overall Progress
            </span>
            <span className="text-sm text-zinc-600 font-serif">
              {Math.round(overallProgress)}%
            </span>
          </div>
          <Progress 
            value={overallProgress} 
            className="h-2 bg-zinc-100"
          />
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {steps.length === 0 ? (
          <div className="text-center py-6">
            <Clock className="h-8 w-8 text-zinc-300 mx-auto mb-2" />
            <p className="text-sm text-zinc-500 tracking-wide">
              Waiting for execution steps...
            </p>
          </div>
        ) : (
          <>
            <h4 className="font-serif text-sm font-medium text-black tracking-wide uppercase border-b border-zinc-100 pb-2">
              Execution Steps
            </h4>

            {steps.map((step, index) => (
              <div key={step.id} className="flex items-start space-x-3">
                <div className="flex-shrink-0 mt-0.5">
                  {getStatusIcon(step.status)}
                </div>

                <div className="flex-1 min-w-0">
                  <div className="flex items-center space-x-2">
                    <h4 className="text-sm font-medium text-zinc-900">
                      {step.title}
                    </h4>
                    {step.status === 'in_progress' && step.progress !== undefined && (
                      <span className="text-xs text-zinc-500 font-serif">
                        {step.progress}%
                      </span>
                    )}
                  </div>

                  {step.description && (
                    <p className="text-xs text-zinc-600 mt-1 tracking-wide">
                      {step.description}
                    </p>
                  )}

                  {step.status === 'in_progress' && step.progress !== undefined && (
                    <Progress 
                      value={step.progress} 
                      className="h-1 mt-2 bg-zinc-100"
                    />
                  )}
                </div>
              </div>
            ))}
          </>
        )}

        {/* Luxury Status Indicator */}
        <div className="mt-6 pt-4 border-t border-zinc-100">
          <div className="flex items-center justify-center space-x-2">
            <Zap className="h-3 w-3 text-amber-500" />
            <span className="text-xs tracking-widest uppercase text-zinc-500 font-light">
              Bridge System Active
            </span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { ChangeEvent, useState, useRef } from 'react';
import { Button } from '../ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { Alert, AlertDescription } from '../ui/alert';
import { Upload, FileText, AlertCircle, CheckCircle } from 'lucide-react';
import { useToast } from '../../hooks/use-toast';

interface ManyChatPSIDUploaderProps {
  onPSIDListReady: (psids: string[]) => void;
}

export function ManyChatPSIDUploader({ onPSIDListReady }: ManyChatPSIDUploaderProps) {
  const [psidList, setPsidList] = useState<string[]>([]);
  const [uploadMethod, setUploadMethod] = useState<'file' | 'paste'>('file');
  const [textInput, setTextInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  const handleFileUpload = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    try {
      const text = await file.text();
      const psids = parsePSIDText(text);
      setPsidList(psids);

      toast({
        title: "File processed successfully",
        description: `Found ${psids.length} subscriber IDs`,
      });
    } catch (error) {
      toast({
        title: "Error processing file",
        description: "Please check your file format and try again",

      });
    } finally {
      setIsProcessing(false);
    }
  };

  const handleTextInput = () => {
    setIsProcessing(true);
    try {
      const psids = parsePSIDText(textInput);
      setPsidList(psids);

      toast({
        title: "Text processed successfully",
        description: `Found ${psids.length} subscriber IDs`,
      });
    } catch (error) {
      toast({
        title: "Error processing text",
        description: "Please check your PSID format and try again",

      });
    } finally {
      setIsProcessing(false);
    }
  };

  const parsePSIDText = (text: string): string[] => {
    // Parse various formats: CSV, line-separated, or space-separated
    const cleaned = text
      .replace(/[^\w\s,\n-]/g, '') // Remove special chars except word chars, spaces, commas, newlines, hyphens
      .replace(/\s+/g, ' ') // Normalize whitespace
      .trim();

    let psids: string[] = [];

    // Try comma-separated first
    if (cleaned.includes(',')) {
      psids = cleaned.split(',').map(p => p.trim()).filter(p => p.length > 0);
    }
    // Try newline-separated
    else if (cleaned.includes('\n')) {
      psids = cleaned.split('\n').map(p => p.trim()).filter(p => p.length > 0);
    }
    // Try space-separated
    else {
      psids = cleaned.split(' ').map(p => p.trim()).filter(p => p.length > 0);
    }

    // Filter out invalid PSIDs (should be numeric or alphanumeric)
    const validPsids = psids.filter(psid => /^[a-zA-Z0-9-]+$/.test(psid) && psid.length >= 5);

    if (validPsids.length === 0) {
      throw new Error('No valid PSIDs found');
    }

    return validPsids;
  };

  const handleProceedWithImport = () => {
    if (psidList.length === 0) return;
    onPSIDListReady(psidList);
  };

  return (
    <div className="space-y-6">
      {/* Step 1: Export Instructions */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5" />
            Step 1: Export PSIDs from ManyChat
          </CardTitle>
          <CardDescription>
            ManyChat requires manual export before import
          </CardDescription>
        </CardHeader>
        <CardContent>
          <Alert>
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <strong>Updated Export Instructions (ManyChat 2025):</strong>
              <ol className="mt-2 ml-4 list-decimal space-y-1">
                <li>Log into your ManyChat dashboard</li>
                <li>Navigate to <strong>Contacts</strong> page (as shown in your screenshot)</li>
                <li>Select all contacts (click checkbox in header to select all 4608)</li>
                <li>Click <strong>Bulk Actions</strong> button</li>
                <li>Select <strong>Export Custom to System Field</strong></li>
                <li>Choose to export the <strong>Facebook PSID</strong> or <strong>Contact ID</strong> field</li>
                <li>Download the generated CSV file</li>
              </ol>
              <p className="mt-2 text-sm text-amber-600">
                <strong>Note:</strong> ManyChat changed their interface. If export isn't available, we can use the ManyChat API directly instead.
              </p>
            </AlertDescription>
          </Alert>
        </CardContent>
      </Card>

      {/* Step 2: Upload PSIDs */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Upload className="h-5 w-5" />
            Step 2: Upload Subscriber IDs
          </CardTitle>
          <CardDescription>
            Upload your exported contact file or paste the IDs directly. If manual export doesn't work, we'll use ManyChat API instead.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Upload Method Selection */}
          <div className="flex gap-2">
            <Button
              variant={uploadMethod === 'file' ? 'default' : 'outline'}
              onClick={() => setUploadMethod('file')}
              size="sm"
            >
              Upload File
            </Button>
            <Button
              variant={uploadMethod === 'paste' ? 'default' : 'outline'}
              onClick={() => setUploadMethod('paste')}
              size="sm"
            >
              Paste Text
            </Button>
          </div>

          {uploadMethod === 'file' ? (
            <div>
              <Input
                type="file"
                accept=".txt,.csv,.json"
                onChange={handleFileUpload}
                ref={fileInputRef}
                disabled={isProcessing}
              />
              <p className="text-sm text-muted-foreground mt-2">
                Supports .txt, .csv, or .json files with PSIDs
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              <Textarea
                placeholder="Paste your PSIDs here (comma-separated, line-separated, or space-separated)&#10;&#10;Example:&#10;1234567890&#10;0987654321&#10;&#10;Or: 1234567890, 0987654321, 1122334455"
                value={textInput}
                onChange={(e) => setTextInput(e.target.value)}
                rows={8}
                disabled={isProcessing}
              />
              <Button 
                onClick={handleTextInput} 
                disabled={!textInput.trim() || isProcessing}
                size="sm"
              >
                Process PSIDs
              </Button>
            </div>
          )}

          {/* Results Display */}
          {psidList.length > 0 && (
            <Alert>
              <CheckCircle className="h-4 w-4" />
              <AlertDescription>
                <strong>Ready for Import:</strong> Found {psidList.length} valid subscriber IDs
                <div className="mt-2">
                  <p className="text-sm">Sample PSIDs: {psidList.slice(0, 3).join(', ')}
                    {psidList.length > 3 && ` ... and ${psidList.length - 3} more`}
                  </p>
                </div>
              </AlertDescription>
            </Alert>
          )}
        </CardContent>
      </Card>

      {/* Step 3: Proceed with Import */}
      {psidList.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Step 3: Import Subscribers</CardTitle>
            <CardDescription>
              Start the import process with {psidList.length} subscriber IDs
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Button 
              onClick={handleProceedWithImport} 
              className="w-full bg-black text-white hover:bg-gray-800"
              disabled={psidList.length === 0}
            >
              Import {psidList.length} ManyChat Subscribers
            </Button>
            <p className="text-sm text-muted-foreground mt-2 text-center">
              This will make individual API calls for each subscriber (rate limited to 2 per second)
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

