                <div className="flex items-center gap-2 mb-2">
                  {card.emoji && (
                    <span className="text-lg" title="Maya's styling approach">
                      {card.emoji}
                    </span>
                  )}
                  {card.creativeLook && (
                    <span 
                      className="text-xs tracking-wider uppercase text-gray-500 px-2 py-1 border border-gray-200 rounded"
