              )}

              <h4 
                className="text-base tracking-wider uppercase text-black cursor-pointer"
                style={{ 
                  fontFamily: 'Times New Roman, serif', 
                  fontWeight: 200, 
                  letterSpacing: '0.2em' 
                }}
              >
                {cleanDisplayTitle(card.title)}
