          </div>

          <p 
            className="text-gray-600 mb-6 leading-relaxed"
            style={{ fontFamily: 'Helvetica Neue', fontWeight: 300, lineHeight: 1.7 }}
          >
            {isExpanded || card.description.length <= 150 
              ? card.description
              : `${card.description.substring(0, 150)}...`
