              {messages.map((msg, index) => (
                <div key={index} className="mb-6">
                  <div className="text-xs text-gray-400 tracking-wider uppercase mb-2">
                    {msg.type === 'user' ? 'You' : 'Maya'}
                  </div>
                  <div className={`p-4 rounded ${
