                  </div>
                </div>
              ))}

              {isTyping && (
                <div className="mb-6">
                  <div className="text-xs text-gray-400 tracking-wider uppercase mb-2">Maya</div>
                  <div className="bg-gray-50 p-4 rounded mr-8 flex items-center">
