        <div className="text-center p-8 border-b border-gray-100">
          <div className="mb-6">
            <div className="w-16 h-16 mx-auto bg-black rounded-full flex items-center justify-center mb-4">
              <span className="text-white text-2xl">✓</span>
            </div>
          </div>
