    description: string;
    code?: string;
    preview?: string;
    changes?: string[];
    files?: { path: string; content: string; type: 'modified' | 'created' | 'deleted' }[];
    fileContent?: string;  // Victoria's component code
    filePath?: string;     // The file path for the component
  };
  onApprove: () => void;
  onReject: (feedback?: string) => void;
}

export function DevPreviewModal({ 
  isOpen, 
  onClose, 
  agentName, 
  previewData, 
  onApprove, 
  onReject 
}: DevPreviewModalProps) {
  const [feedback, setFeedback] = useState('');
  const [activeTab, setActiveTab] = useState<'preview' | 'code' | 'changes'>('preview');

  // Preview modal for agent development work

  if (!isOpen) return null;

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4">
      <div className="bg-white max-w-6xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="p-4 border-b border-gray-200 flex items-center justify-between bg-gray-50">
          <div>
            <h3 className="font-serif text-xl">{agentName} Development Preview</h3>
            <p className="text-sm text-gray-600 mt-1">{previewData.title}</p>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-200 rounded"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Tab Navigation */}
        <div className="flex border-b border-gray-200 bg-gray-50">
          <button
            onClick={() => setActiveTab('preview')}
            className={`px-4 py-2 text-sm font-medium ${
              activeTab === 'preview' 
                ? 'border-b-2 border-black text-black' 
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            Live Preview
          </button>
          <button
            onClick={() => setActiveTab('code')}
            className={`px-4 py-2 text-sm font-medium ${
              activeTab === 'code' 
                ? 'border-b-2 border-black text-black' 
                : 'text-gray-500 hover:text-gray-700'
            }`}
          >
            Code Changes
          </button>
          <button
            onClick={() => setActiveTab('changes')}
