import { FC, FormEvent, useState } from 'react';
import { SandraImages } from '../lib/sandra-images';
import { useToast } from '../hooks/use-toast';

interface EmailCaptureModalProps {
  isOpen: boolean;
  onClose: () => void;
  onEmailCaptured?: (email: string) => void;
  plan: string;
}

export const EmailCaptureModal: FC<EmailCaptureModalProps> = ({
  isOpen,
  onClose,
  onEmailCaptured,
  plan
}) => {
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { toast } = useToast();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();

    if (!email || !email.includes('@')) {
      toast({
        title: "Email Required",
        description: "Please enter a valid email address",

      });
      return;
    }

    setIsSubmitting(true);

    try {
      // Send email to your list via Resend
      const response = await fetch('/api/email-capture', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email,
          plan,
          source: 'landing_page'
        }),
      });

      if (!response.ok) throw new Error('Failed to capture email');

      // Store email captured flag
      localStorage.setItem('emailCaptured', 'true');
      localStorage.setItem('capturedEmail', email);

      // Success! Now redirect to authentication
      toast({
        title: "Email Captured!",
        description: "Redirecting to authentication...",
      });

      if (onEmailCaptured) {
        onEmailCaptured(email);
      }

      onClose();

      // Redirect to authentication after brief delay for user feedback
      setTimeout(() => {
        window.location.href = '/login';
      }, 1000);

    } catch (error) {
      toast({
        title: "Something went wrong",
        description: "Please try again or contact support",

      });
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  const isFreePlan = plan === 'free';

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white max-w-4xl w-full max-h-[90vh] overflow-y-auto relative">
        {/* Close button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-black hover:text-gray-600 text-2xl font-light z-10"
        >
          ×
        </button>

        <div className="flex flex-col lg:flex-row min-h-[500px]">
          {/* Image Side */}
          <div className="lg:w-1/2 relative min-h-[300px] lg:min-h-[500px]">
            <img
              src={SandraImages.emailCapture}
              alt="SSELFIE Studio"
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-black bg-opacity-30"></div>
          </div>

          {/* Form Side */}
          <div className="lg:w-1/2 p-6 sm:p-8 lg:p-12 flex flex-col justify-center min-h-[400px]">
            <div className="max-w-md mx-auto w-full">
              <div className="text-xs uppercase tracking-[0.4em] text-gray-500 mb-6">
                {plan === 'basic' ? 'Start Basic' : 'Join Full Access'}
              </div>

              <h2 className="font-serif text-3xl lg:text-4xl font-light text-black mb-4 leading-tight">
                Ready to build<br />your brand?
              </h2>

              <p className="text-gray-600 mb-8 leading-relaxed">
                {plan === 'basic' ? (
                  "Get your personal AI model trained on your selfies. Start creating professional photos with Maya's help for €29/month."
                ) : (
                  "Join thousands of women building their personal brands with AI. Get your trained model, 100 monthly photos, Maya & Victoria, and everything you need to launch for €67/month."
                )}
              </p>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <input
                    type="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="Enter your email address"
                    className="w-full px-4 py-4 border border-gray-200 focus:border-black focus:outline-none text-sm"
                    required
                  />
                </div>

                <button
                  type="submit"
                  disabled={isSubmitting}
                  className="w-full py-4 bg-black text-white text-xs uppercase tracking-[0.3em] hover:bg-gray-800 transition-all duration-300 disabled:opacity-50"
                >
                  {isSubmitting ? 'Getting Started...' : (plan === 'basic' ? 'Start Basic €29/mo' : 'Start Full Access €67/mo')}
                </button>
              </form>

              <p className="text-xs text-gray-500 mt-4 text-center">
                Both plans include your personal AI model training. Cancel anytime.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import { Component, ErrorInfo, ReactNode } from 'react';
import { PreLoginNavigationUnified } from '@/components/pre-login-navigation-unified';
import { HeroFullBleed } from '@/components/hero-full-bleed';
import { SandraImages } from '@/lib/sandra-images';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
}

export class EnhancedErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null };
  }

  static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Error caught by boundary:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="min-h-screen bg-white">
          <PreLoginNavigationUnified />

          <HeroFullBleed
            backgroundImage={SandraImages.editorial.laptop1}
            tagline="Something went wrong"
            title="ERROR"
            ctaText="Try Again"
            onCtaClick={() => window.location.reload()}
            fullHeight={false}
          />

          <main className="max-w-4xl mx-auto px-8 py-16">
            <div className="text-center mb-16">
              <h2 className="text-3xl font-light mb-6" style={{ fontFamily: 'Times New Roman, serif' }}>
                We're fixing this right now
              </h2>
              <p className="text-lg text-[#666666] max-w-2xl mx-auto font-light leading-relaxed">
                Something unexpected happened. Don't worry - this doesn't affect your account 
                or any work you've saved. Try refreshing the page.
              </p>
            </div>

            <div className="bg-[#f5f5f5] p-12 text-center">
              <div className="space-y-6">
                <div>
                  <h3 className="text-xl font-light mb-4" style={{ fontFamily: 'Times New Roman, serif' }}>
                    Quick Solutions
                  </h3>
                  <div className="space-y-4 max-w-md mx-auto">
                    <button
                      onClick={() => window.location.reload()}
                      className="w-full bg-[#0a0a0a] text-white px-6 py-3 text-xs uppercase tracking-wider hover:bg-[#333] transition-colors"
                    >
                      Refresh Page
                    </button>
                    <button
                      onClick={() => window.location.href = '/workspace'}
                      className="w-full border border-[#0a0a0a] text-[#0a0a0a] px-6 py-3 text-xs uppercase tracking-wider hover:bg-[#0a0a0a] hover:text-white transition-colors"
                    >
                      Back to STUDIO
                    </button>
                  </div>
                </div>

                <div className="text-xs text-[#666666] pt-4 border-t border-[#e5e5e5]">
                  If this keeps happening, contact us at hello@sselfie.com
                </div>
              </div>
            </div>
          </main>
        </div>
      );
    }

    return this.props.children;
