              style={{
                background: 'rgba(255, 255, 255, 0.2)',
                border: '1px solid rgba(255, 255, 255, 0.3)',
                color: '#ffffff',
                padding: '6px 10px',
                fontSize: '9px',
                letterSpacing: '0.2em',
                textTransform: 'uppercase',
                cursor: downloadingImages.has(image.imageUrl) ? 'wait' : 'pointer',
                transition: 'all 300ms ease',
                minWidth: '60px',
                minHeight: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '4px'
              }}
              onMouseEnter={(e) => {
                if (!downloadingImages.has(image.imageUrl)) {
                  (e.target as HTMLButtonElement).style.background = '#ffffff';
                  (e.target as HTMLButtonElement).style.color = '#0a0a0a';
                }
              }}
              onMouseLeave={(e) => {
                if (!downloadingImages.has(image.imageUrl)) {
                  (e.target as HTMLButtonElement).style.background = 'rgba(255, 255, 255, 0.2)';
                  (e.target as HTMLButtonElement).style.color = '#ffffff';
                }
              }}
            >
              {downloadingImages.has(image.imageUrl) ? 'DOWNLOADING...' : 'DOWNLOAD'}
            </button>

            {/* Delete Button */}
            <button
              onClick={(e) => {
                e.stopPropagation();
                if (window.confirm('Are you sure you want to delete this image?')) {
                  onDeleteImage(image.id);
                }
              }}
              disabled={isDeleting}
              className="touch-manipulation"
              style={{
                background: 'rgba(220, 38, 38, 0.8)',
                border: '1px solid rgba(220, 38, 38, 0.5)',
                color: '#ffffff',
                padding: '6px 10px',
                fontSize: '9px',
                letterSpacing: '0.2em',
                textTransform: 'uppercase',
                cursor: isDeleting ? 'wait' : 'pointer',
                transition: 'all 300ms ease',
                minWidth: '55px',
                minHeight: '32px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center'
              }}
              onMouseEnter={(e) => {
                if (!isDeleting) {
                  (e.target as HTMLButtonElement).style.background = 'rgba(220, 38, 38, 1)';
                }
              }}
              onMouseLeave={(e) => {
                if (!isDeleting) {
                  (e.target as HTMLButtonElement).style.background = 'rgba(220, 38, 38, 0.8)';
                }
              }}
            >
              {isDeleting ? 'DELETING...' : 'DELETE'}
            </button>
          </div>
        </div>
      </div>
    </div>
  </div>
);

export function MayaCategorizedGallery() {
  const { user, isAuthenticated } = useAuth();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [selectedImage, setSelectedImage] = useState<ImageData | null>(null);
  const [downloadingImages, setDownloadingImages] = useState(new Set<string>());
  const [visibleCount, setVisibleCount] = useState<Record<string, number>>({
    Business: 6,
    Fashion: 6,
    Lifestyle: 6,
    Travel: 6,
    all: 6
  });
  const queryClient = useQueryClient();

  // Fetch Maya-generated images
  const { data: mayaImages = [], isLoading } = useQuery<ImageData[]>({
    queryKey: ['/api/maya/generated-images'],
    enabled: isAuthenticated && !!user,
    staleTime: 30000, // 30 seconds
  });

  // Fetch user's favorites
  const { data: favoritesData } = useQuery<{ favorites: number[] }>({
    queryKey: ['/api/images/favorites'],
    enabled: isAuthenticated && !!user,
    staleTime: 30000,
  });

  const favorites: number[] = favoritesData?.favorites || [];

  // Toggle favorite mutation
  const toggleFavoriteMutation = useMutation({
    mutationFn: async (imageId: number) => {
      const response = await apiRequest(`/api/images/${imageId}/favorite`, 'POST');
      return response;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/images/favorites'] });
    },
    onError: (error) => {
      console.error('Favorite toggle error:', error);
    }
  });

  // Delete image mutation
  const deleteImageMutation = useMutation({
    mutationFn: async (imageId: number) => {
      return await apiRequest(`/api/ai-images/${imageId}`, 'DELETE');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/maya/generated-images'] });
      queryClient.invalidateQueries({ queryKey: ['/api/images/favorites'] });
    }
  });

  // Download image function
  const downloadImage = async (imageUrl: string, filename: string) => {
    try {
      setDownloadingImages(prev => new Set([...prev, imageUrl]));

      if (!imageUrl || !imageUrl.startsWith('http')) {
        console.log('Skipping invalid URL:', imageUrl);
        return;
      }

      const link = document.createElement('a');
      link.href = imageUrl;
      link.download = filename;
      link.setAttribute('crossorigin', 'anonymous');
      link.target = '_blank';
      link.rel = 'noopener noreferrer';

      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      console.log(`Download initiated for: ${filename}`);

    } catch (error) {
      console.error('Error downloading image:', error);
      alert('Download failed. Please right-click the image and select "Save image as..." to download manually.');
    } finally {
      setTimeout(() => {
        setDownloadingImages(prev => {
          const newSet = new Set(prev);
          newSet.delete(imageUrl);
          return newSet;
        });
      }, 1000);
    }
  };

  // Categorize images
  const categories = ['Business', 'Fashion', 'Lifestyle', 'Travel'];

  const categorizedImages = categories.reduce((acc, category) => {
    acc[category] = mayaImages.filter(img => 
      img.category?.toLowerCase() === category.toLowerCase() ||
      img.prompt?.toLowerCase().includes(category.toLowerCase())
    );
    return acc;
  }, {} as Record<string, ImageData[]>);

  // Get recent image for each category (for card backgrounds)
  const getRecentImageForCategory = (category: string) => {
    const categoryImages = categorizedImages[category];
    return categoryImages.length > 0 ? categoryImages[0].imageUrl : undefined;
  };

  // Load more images function
  const loadMoreImages = () => {
    setVisibleCount(prev => ({
      ...prev,
      [selectedCategory]: prev[selectedCategory] + 6
    }));
  };

  // Get all images for selected category
  const allCategoryImages = selectedCategory === 'all' 
    ? mayaImages 
    : categorizedImages[selectedCategory] || [];

  // Get images to display (with pagination)
  const imagesToDisplay = allCategoryImages.slice(0, visibleCount[selectedCategory]);
  const hasMoreImages = allCategoryImages.length > visibleCount[selectedCategory];

  const handleImageClick = (image: ImageData) => {
    setSelectedImage(image);
  };

  const closeModal = () => {
    setSelectedImage(null);
  };

  const toggleFavorite = (imageId: number) => {
    toggleFavoriteMutation.mutate(imageId);
  };

  const deleteImage = (imageId: number) => {
    deleteImageMutation.mutate(imageId);
  };

  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="bg-gray-50 border-t border-gray-200">
      <div className="max-w-7xl mx-auto px-8 py-12">
        {/* Section Header */}
        <div className="text-center mb-12">
          <div className="eyebrow text-gray-500 mb-4">
            Maya • Generated Portfolio
          </div>
          <h2 
            className="text-3xl font-light uppercase tracking-[0.2em] text-black mb-6"
            style={{ fontFamily: 'Times New Roman, serif' }}
          >
            Your Personal Brand Gallery
          </h2>
          <div className="w-32 h-px bg-black mx-auto"></div>
        </div>

        {/* Category Navigation Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mb-12">
          {categories.map((category) => (
            <CategoryCard
              key={category}
              category={category}
              imageCount={categorizedImages[category]?.length || 0}
              recentImage={getRecentImageForCategory(category)}
              onClick={() => setSelectedCategory(category)}
              isActive={selectedCategory === category}
            />
          ))}
        </div>

        {/* View All Button */}
        <div className="text-center mb-8">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-8 py-3 border transition-all duration-300 ${
              selectedCategory === 'all' 
                ? 'bg-black text-white border-black' 
                : 'bg-white text-black border-gray-300 hover:border-black'
            }`}
          >
            <div className="text-xs font-normal uppercase tracking-[0.3em]">
              View All ({mayaImages.length})
            </div>
          </button>
        </div>

        {/* Loading State */}
        {isLoading && (
          <div className="flex justify-center items-center h-64">
            <div className="flex space-x-2">
              <div className="w-3 h-3 bg-black rounded-full animate-bounce"></div>
              <div className="w-3 h-3 bg-black rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
              <div className="w-3 h-3 bg-black rounded-full animate-bounce" style={{animationDelay: '0.4s'}}></div>
            </div>
          </div>
        )}

        {/* Images Grid */}
        {!isLoading && imagesToDisplay.length > 0 && (
          <>
            {selectedCategory !== 'all' && (
              <div className="mb-6">
                <h3 
                  className="text-xl font-light uppercase tracking-[0.2em] text-black"
                  style={{ fontFamily: 'Times New Roman, serif' }}
                >
                  {selectedCategory} • {imagesToDisplay.length} {imagesToDisplay.length === 1 ? 'Image' : 'Images'}
                </h3>
              </div>
            )}

            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(clamp(250px, 40vw, 300px), 1fr))',
              gap: 'clamp(16px, 4vw, 30px)',
              padding: '0 20px'
            }}>
              {imagesToDisplay.map((image, index) => (
                <ImageCard
                  key={image.id}
                  image={image}
                  onImageClick={handleImageClick}
                  favorites={favorites}
                  downloadingImages={downloadingImages}
                  onToggleFavorite={toggleFavorite}
                  onDownloadImage={downloadImage}
                  onDeleteImage={deleteImage}
                  index={index}
                  isToggling={toggleFavoriteMutation.isPending}
                  isDeleting={deleteImageMutation.isPending}
                />
              ))}
            </div>

            {/* View More Button */}
            {hasMoreImages && (
              <div className="text-center mt-12">
                <button
                  onClick={loadMoreImages}
                  className="bg-white text-black border border-gray-300 hover:border-black px-8 py-3 transition-all duration-300"
                >
                  <div className="text-xs font-normal uppercase tracking-[0.3em]">
                    View {Math.min(6, allCategoryImages.length - visibleCount[selectedCategory])} More
                  </div>
                </button>
              </div>
            )}
          </>
        )}

        {/* Empty State */}
        {!isLoading && imagesToDisplay.length === 0 && (
          <div className="text-center py-16">
            <div className="text-gray-400 mb-4">
              {selectedCategory === 'all' 
                ? 'No images generated yet' 
                : `No ${selectedCategory.toLowerCase()} images yet`}
            </div>
            <div className="text-sm text-gray-500">
              Start a conversation with Maya to create your first personalized images
            </div>
          </div>
        )}
      </div>

      {/* Image Modal */}
      {selectedImage && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-90 flex items-center justify-center z-50 p-8"
          onClick={closeModal}
        >
          <div className="relative max-w-4xl max-h-full">
            <img 
              src={selectedImage.imageUrl} 
              alt={`Generated image ${selectedImage.id}`}
              className="max-w-full max-h-full object-contain"
              onClick={(e) => e.stopPropagation()}
            />
            <button 
              onClick={closeModal}
              className="absolute top-4 right-4 text-white text-2xl w-8 h-8 flex items-center justify-center hover:bg-white/20 rounded-full transition-colors"
            >
              ×
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useRef, ChangeEvent } from 'react';
import { Camera, Upload, X, CheckCircle, AlertCircle } from 'lucide-react';
import { useMutation } from '@tanstack/react-query';
import { useToast } from '../../hooks/use-toast';
import { apiRequest } from '../../lib/queryClient';

interface MayaUploadComponentProps {
  onUploadComplete?: (success: boolean) => void;
  onTrainingStart?: () => void;
  className?: string;
}

export function MayaUploadComponent({ 
  onUploadComplete, 
  onTrainingStart,
  className = "" 
}: MayaUploadComponentProps) {
  const [selfieImages, setSelfieImages] = useState<File[]>([]);
  const [isUploadingImages, setIsUploadingImages] = useState(false);
  const [uploadErrors, setUploadErrors] = useState<string[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  // Compress image for AI training - extracted from simple-training
  const compressImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      const img = new Image();

      img.onload = () => {
        try {
          // Optimal dimensions for AI training (1024x1024 max)
          const maxWidth = 1024;
          const maxHeight = 1024;

          let { width, height } = img;

          // Calculate new dimensions maintaining aspect ratio
          if (width > maxWidth || height > maxHeight) {
            const ratio = Math.min(maxWidth / width, maxHeight / height);
            width *= ratio;
            height *= ratio;
          }

          canvas.width = width;
          canvas.height = height;

          // Draw and compress with high quality for AI training
          ctx?.drawImage(img, 0, 0, width, height);
          const compressedBase64 = canvas.toDataURL('image/jpeg', 0.85); // 85% quality for AI training
          resolve(compressedBase64);
        } catch (error) {
          reject(error);
        }
      };

      img.onerror = () => reject(new Error('Failed to load image'));
      img.src = URL.createObjectURL(file);
    });
  };

  // Start training mutation - extracted from simple-training
  const startTraining = useMutation({
    mutationFn: async (images: string[]) => {
      setIsUploadingImages(true);
      const response = await apiRequest('/api/start-model-training', 'POST', {
        selfieImages: images
      });
      return response;
    },
    onSuccess: (data: any) => {
      setIsUploadingImages(false);
      if (data.success) {
        onTrainingStart?.();
        onUploadComplete?.(true);
        toast({
          title: "Training Started",
          description: "Your AI model is now training. Maya will guide you while we wait!",
        });
      } else {
        // Handle validation errors
        setUploadErrors(data.errors || []);
        toast({
          title: "Training Validation Failed",
          description: `Please fix these issues: ${data.errors?.join(', ')}`,
        });
        onUploadComplete?.(false);
      }
    },
    onError: (error: any) => {
      setIsUploadingImages(false);
      console.error('Maya training initiation failed:', error);

      toast({
        title: "Training Failed", 
        description: error.message || "Training system error. Please try again.",
      });
      onUploadComplete?.(false);
    }
  });

  // Handle file selection - extracted from simple-training
  const handleFileSelect = (e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);

    // Bulletproof validation: Strict requirements
    const validFiles = files.filter(file => {
      const isImage = file.type.startsWith('image/');
      const isUnder10MB = file.size <= 10 * 1024 * 1024;
      const isMinSize = file.size >= 10240; // At least 10KB for quality
      return isImage && isUnder10MB && isMinSize;
    });

    if (validFiles.length !== files.length) {
      toast({
        title: "Invalid files",
        description: "Please upload only high-quality image files (10KB-10MB).",
      });
    }

    setSelfieImages(prev => [...prev, ...validFiles]);
  };

  // Remove image from selection
  const removeImage = (index: number) => {
    setSelfieImages(prev => prev.filter((_, i) => i !== index));
  };

  // Start training handler - extracted from simple-training
  const handleStartTraining = async () => {
    // Critical frontend validation: Never allow less than 10 images
    if (selfieImages.length < 10) {
      toast({
        title: "Need More Photos",
        description: `Only ${selfieImages.length} photos uploaded. Minimum 10 selfies required.`,
      });
      return;
    }

    if (selfieImages.length < 15) {
      toast({
        title: "Recommendation",
        description: `${selfieImages.length} photos uploaded. 15-20 recommended for best results.`,
      });
    }

    setUploadErrors([]);

    try {
      // Compress images to prevent 413 errors while maintaining AI training quality
      const compressedBase64Images = await Promise.all(
        selfieImages.map(async (file) => {
          try {
            return await compressImage(file);
          } catch (error) {
            console.error('Failed to compress image:', error);
            throw new Error(`Failed to process image: ${file.name}`);
          }
        })
      );

      console.log(`✅ Maya: Compressed ${compressedBase64Images.length} images successfully`);
      startTraining.mutate(compressedBase64Images);
    } catch (error) {
      toast({
        title: "Upload Failed",
        description: "Failed to process images. Please try again with different photos.",
      });
      console.error('Maya image processing failed:', error);
    }
  };

  return (
    <div className={`maya-upload-component ${className}`}>
      {/* Hidden file input */}
      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileSelect}
        multiple
        accept="image/*"
        className="hidden"
      />

      {/* Upload Area */}
      <div className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center hover:border-black transition-colors cursor-pointer group"
           onClick={() => fileInputRef.current?.click()}>
        <Camera className="w-12 h-12 mx-auto mb-4 text-gray-400 group-hover:text-black transition-colors" />

        <h3 className="font-serif text-xl font-light tracking-wide mb-4">
          Upload Your Selfies
        </h3>

        <p className="text-gray-600 text-sm mb-4">
          Choose 10-15 photos from your camera roll. Include the "real" ones - that's where your authentic brand lives.
        </p>

        <div className="text-xs tracking-[0.2em] uppercase text-gray-500">
          Click to select photos
        </div>
      </div>

      {/* Error Messages */}
      {uploadErrors.length > 0 && (
        <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded">
          <div className="flex items-center gap-2 mb-2">
            <AlertCircle className="w-4 h-4 text-red-600" />
            <span className="text-sm font-medium text-red-800">Upload Issues:</span>
          </div>
          <ul className="text-sm text-red-700 space-y-1">
            {uploadErrors.map((error, index) => (
              <li key={index}>• {error}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Image Preview Grid */}
      {selfieImages.length > 0 && (
        <div className="mt-6">
          <div className="flex items-center justify-between mb-4">
            <span className="text-sm font-medium">
              {selfieImages.length} photos selected
            </span>
            <div className="flex items-center gap-2">
              {selfieImages.length >= 10 ? (
                <CheckCircle className="w-4 h-4 text-green-600" />
              ) : (
                <AlertCircle className="w-4 h-4 text-amber-600" />
              )}
              <span className="text-xs text-gray-500">
                {selfieImages.length >= 10 ? 'Ready for training' : `Need ${10 - selfieImages.length} more`}
              </span>
            </div>
          </div>

          {/* Image Grid */}
          <div className="grid grid-cols-4 gap-2 mb-6">
            {selfieImages.map((file, index) => (
              <div key={index} className="relative aspect-square">
                <img 
                  src={URL.createObjectURL(file)}
                  alt={`Selfie ${index + 1}`}
                  className="w-full h-full object-cover rounded border"
                />
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    removeImage(index);
                  }}
                  className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white rounded-full flex items-center justify-center hover:bg-red-600 transition-colors"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            ))}
          </div>

          {/* Start Training Button */}
          <button
            onClick={handleStartTraining}
            disabled={selfieImages.length < 10 || isUploadingImages || startTraining.isPending}
            className={`w-full py-3 px-6 text-sm tracking-[0.2em] uppercase font-light transition-all duration-300 ${
              selfieImages.length >= 10 && !isUploadingImages && !startTraining.isPending
                ? 'bg-black text-white hover:bg-gray-800'
                : 'bg-gray-100 text-gray-400 cursor-not-allowed'
            }`}
          >
            {isUploadingImages || startTraining.isPending ? (
              'Starting Training...'
            ) : selfieImages.length < 10 ? (
              `Need ${10 - selfieImages.length} More Photos`
            ) : (
              'Start AI Model Training'
            )}
          </button>
        </div>
      )}
    </div>
  );
}

