      </div>

      {/* Quick Presets */}
      <div className="bg-gray-50 border border-gray-200 p-6">
        <h4 className="font-medium mb-4">Quick Presets</h4>
        <div className="flex gap-2 flex-wrap">
          <Button 
            variant="outline" 
