export const BrandCustomizer: FC<BrandCustomizationProps> = ({
  onCustomizationChange
}) => {
  const [customization, setCustomization] = useState<BrandCustomization>({
    colors: {
      primary: '#0a0a0a',
      secondary: '#ffffff',
      accent: '#f5f5f5',
