        {/* Quick Preview of Selected Images */}
        {totalSelected > 0 && (
          <div className="mt-6">
            <h5 className="eyebrow-text mb-3">Selected Images Preview</h5>
            <div className="grid grid-cols-6 md:grid-cols-8 gap-2">
              {selectedAIPhotos.map((photo, index) => (
