    e.preventDefault();
    setIsLoading(true);

    try {
      const response = await fetch('/api/signup-gift', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({
          email: email,
          source: 'homepage-gift'
        }),
