  userId ? `maya_conversation_${userId}` : 'maya_conversation_temp';
const MAX_MESSAGES = 30; // 🧠 MEMORY ENHANCED: Keep 30 messages for better context continuity
const CONVERSATION_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days

export const useMayaPersistence = (userId?: string) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  // 🔗 ENHANCED SESSION CONTINUITY: Use userId-based session for persistence across browser sessions
  const [sessionId] = useState(() => userId ? `maya_session_${userId}` : `temp_session_${Date.now()}`);
  const [isLoading, setIsLoading] = useState(true);
  const [lastSyncTime, setLastSyncTime] = useState<number>(0);

  // 🧠 ENHANCED MEMORY LOADING: Multi-layered fallback system
  useEffect(() => {
    if (!userId) {
      setIsLoading(false);
      return;
    }

    const loadConversationWithFallback = async () => {
      try {
        const conversationKey = getMayaConversationKey(userId);
        let loadedMessages: ChatMessage[] = [];
        let dataSource = 'none';

        // LAYER 1: Try localStorage first
        try {
          const stored = localStorage.getItem(conversationKey);
          if (stored) {
            const persistedData: PersistedConversation = JSON.parse(stored);

            // Check if conversation is still valid (within TTL and same user)
            const isValid = persistedData.userId === userId && 
                            (Date.now() - persistedData.lastUpdated) < CONVERSATION_TTL;

            if (isValid && persistedData.messages.length > 0) {
              loadedMessages = persistedData.messages.slice(-MAX_MESSAGES);
              setLastSyncTime(persistedData.lastUpdated);
              dataSource = 'localStorage';
              console.log(`💾 MEMORY: Loaded ${loadedMessages.length} messages from localStorage`);
              console.log(`📊 CONTEXT: ${persistedData.conversationContext.conceptCardsGenerated} concept cards, ${persistedData.conversationContext.imagesGenerated} images`);
            } else {
              console.log('🔄 MEMORY: localStorage expired or invalid, trying database fallback...');
              localStorage.removeItem(conversationKey);
            }
          }
        } catch (localStorageError) {
          console.warn('⚠️ MEMORY: localStorage corrupted, trying database fallback...', localStorageError);
          const conversationKey = getMayaConversationKey(userId);
          localStorage.removeItem(conversationKey);
        }

        // LAYER 2: Database fallback if localStorage failed/expired
        if (loadedMessages.length === 0) {
          try {
            console.log('🔍 MEMORY: Attempting database fallback for conversation history...');
            const response = await fetch('/api/maya/chat-history', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              credentials: 'include',
              body: JSON.stringify({ userId, limit: MAX_MESSAGES })
            });

            if (response.ok) {
              const chatHistory = await response.json();
              if (chatHistory.success && chatHistory.messages?.length > 0) {
                // Transform database messages to frontend format
                loadedMessages = chatHistory.messages.map((msg: any) => ({
                  id: msg.id || `db_${Date.now()}_${Math.random()}`,
                  role: msg.role === 'assistant' ? 'maya' : msg.role,
                  content: msg.content,
                  timestamp: new Date(msg.createdAt).toISOString(),
                  conceptCards: msg.conceptCards || [],
                  canGenerate: msg.canGenerate || false
                }));
                dataSource = 'database';
                console.log(`🗄️ MEMORY RECOVERY: Loaded ${loadedMessages.length} messages from database`);

                // Restore to localStorage for future sessions
                const recoveryData: PersistedConversation = {
                  messages: loadedMessages,
                  lastUpdated: Date.now(),
                  userId,
                  sessionId: `maya_session_${userId}`,
                  conversationContext: {
                    totalMessages: loadedMessages.length,
                    lastActivity: Date.now(),
                    conceptCardsGenerated: loadedMessages.reduce((total, msg) => 
                      total + (msg.conceptCards?.length || 0), 0),
                    imagesGenerated: 0
                  }
                };
                localStorage.setItem(conversationKey, JSON.stringify(recoveryData));
                console.log('💾 MEMORY RECOVERY: Restored conversation to localStorage');
              }
            }
          } catch (databaseError) {
            console.warn('⚠️ MEMORY: Database fallback failed, starting fresh conversation', databaseError);
          }
        }

        // Set loaded messages and log final state
        if (loadedMessages.length > 0) {
          setMessages(loadedMessages);
          console.log(`✅ MEMORY: Successfully loaded ${loadedMessages.length} messages from ${dataSource}`);
        } else {
          console.log('🆕 MEMORY: No existing conversation found, starting fresh');
        }

      } catch (error) {
        console.error('❌ MEMORY: Critical error in conversation loading:', error);
        // Clean slate on critical error
        const conversationKey = getMayaConversationKey(userId);
        localStorage.removeItem(conversationKey);
      }

      setIsLoading(false);
    };

    loadConversationWithFallback();
  }, [userId]);

  // PHASE 2.1: Save conversation to localStorage
  const saveConversation = useCallback((updatedMessages: ChatMessage[]) => {
    if (!userId || updatedMessages.length === 0) return;

    try {
      // Calculate conversation statistics
      const conceptCardsGenerated = updatedMessages.reduce((total, msg) => 
        total + (msg.conceptCards?.length || 0), 0);

      const imagesGenerated = updatedMessages.reduce((total, msg) => 
        total + (msg.conceptCards?.reduce((cardTotal, card) => 
          cardTotal + (card.generatedImages?.length || 0), 0) || 0), 0);

      const persistedData: PersistedConversation = {
        messages: updatedMessages.slice(-MAX_MESSAGES), // Keep last 30 messages for extended context
        lastUpdated: Date.now(),
        userId,
        sessionId,
        conversationContext: {
          totalMessages: updatedMessages.length,
          lastActivity: Date.now(),
          conceptCardsGenerated,
          imagesGenerated
        }
      };

      const conversationKey = getMayaConversationKey(userId);
      localStorage.setItem(conversationKey, JSON.stringify(persistedData));
      setLastSyncTime(Date.now());

      console.log(`💾 MEMORY: Saved ${updatedMessages.length} messages for user ${userId}`);
      console.log(`📊 CONTINUITY: ${conceptCardsGenerated} concept cards, ${imagesGenerated} images across sessions`);
    } catch (error) {
      console.error('❌ MEMORY: Failed to save conversation:', error);
    }
  }, [userId, sessionId]);

  // PHASE 2.1: Enhanced setMessages with automatic persistence
  const updateMessages = useCallback((updater: (prev: ChatMessage[]) => ChatMessage[]) => {
    setMessages(prev => {
      const updated = typeof updater === 'function' ? updater(prev) : updater;

      // Automatically save to localStorage
      saveConversation(updated);

      return updated;
    });
  }, [saveConversation]);

  // PHASE 2.1: Add new message with persistence
  const addMessage = useCallback((message: Omit<ChatMessage, 'id'>) => {
    const newMessage: ChatMessage = {
      ...message,
      id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
    };

    updateMessages(prev => [...prev, newMessage]);
  }, [updateMessages]);

  // PHASE 2.1: Update specific message (for streaming, concept cards, etc.)
  const updateMessage = useCallback((messageId: string, updates: Partial<ChatMessage>) => {
    updateMessages(prev => 
      prev.map(msg => 
        msg.id === messageId ? { ...msg, ...updates } : msg
      )
    );
  }, [updateMessages]);

  // PHASE 2.1: Update concept card within a message
  const updateConceptCard = useCallback((messageId: string, conceptCardId: string, updates: Partial<ConceptCard>) => {
    updateMessages(prev => 
      prev.map(msg => {
        if (msg.id === messageId && msg.conceptCards) {
          return {
            ...msg,
            conceptCards: msg.conceptCards.map(card =>
              card.id === conceptCardId ? { ...card, ...updates } : card
            )
          };
        }
        return msg;
      })
    );
  }, [updateMessages]);

  // PHASE 2.1: Clear conversation (for new session)
  const clearConversation = useCallback(() => {
    setMessages([]);
    const conversationKey = getMayaConversationKey(userId);
    localStorage.removeItem(conversationKey);
    console.log('🧹 PHASE 2.1: Conversation cleared');
  }, [userId]);

  // PHASE 2.1: Get conversation statistics
  const getConversationStats = useCallback(() => {
    const conceptCards = messages.reduce((total, msg) => total + (msg.conceptCards?.length || 0), 0);
    const images = messages.reduce((total, msg) => 
      total + (msg.conceptCards?.reduce((cardTotal, card) => 
        cardTotal + (card.generatedImages?.length || 0), 0) || 0), 0);

    return {
      totalMessages: messages.length,
      conceptCards,
      images,
      lastActivity: lastSyncTime,
      sessionId
    };
  }, [messages, lastSyncTime, sessionId]);

  // PHASE 2.1: Force sync with database (for Phase 2.2)
  const syncWithDatabase = useCallback(async () => {
    // Placeholder for Phase 2.2: Database sync implementation
    console.log('🔄 PHASE 2.2: Database sync - to be implemented');
  }, []);

  return {
    // State
    messages,
    isLoading,
    sessionId,
    lastSyncTime,

    // Actions
    setMessages: updateMessages,
    addMessage,
    updateMessage,
    updateConceptCard,
    clearConversation,

    // Utilities
    getConversationStats,
    syncWithDatabase,

    // Direct access for compatibility
    rawMessages: messages,
    rawSetMessages: setMessages
  };
};

import { useEffect, useRef } from 'react';

interface CleanupFunction {
  (): void;
}

/**
 * Custom hook for managing component cleanup and preventing memory leaks
 */
export const useMemoryCleanup = () => {
  const cleanupFunctions = useRef<CleanupFunction[]>([]);
  const timeouts = useRef<Set<ReturnType<typeof setTimeout>>>(new Set());
  const intervals = useRef<Set<ReturnType<typeof setInterval>>>(new Set());

  const addCleanup = (fn: CleanupFunction) => {
    cleanupFunctions.current.push(fn);
  };

  const createTimeout = (fn: () => void, delay: number): ReturnType<typeof setTimeout> => {
    const timeout = setTimeout(() => {
      timeouts.current.delete(timeout);
      fn();
    }, delay);
    timeouts.current.add(timeout);
    return timeout;
  };

  const createInterval = (fn: () => void, delay: number): ReturnType<typeof setInterval> => {
    const interval = setInterval(fn, delay);
    intervals.current.add(interval);
    return interval;
  };

  const clearTimeoutSafe = (timeout: ReturnType<typeof setTimeout>) => {
    clearTimeout(timeout);
    timeouts.current.delete(timeout);
  };

  const clearIntervalSafe = (interval: ReturnType<typeof setInterval>) => {
    clearInterval(interval);
    intervals.current.delete(interval);
  };

  useEffect(() => {
    return () => {
      // Clear all timeouts
      timeouts.current.forEach(timeout => clearTimeout(timeout));
      timeouts.current.clear();

      // Clear all intervals
      intervals.current.forEach(interval => clearInterval(interval));
      intervals.current.clear();

      // Run all cleanup functions
      cleanupFunctions.current.forEach(fn => {
        try {
          fn();
        } catch (error) {
          console.warn('Cleanup function error:', error);
        }
      });
      cleanupFunctions.current = [];
    };
  }, []);

  return {
    addCleanup,
    createTimeout,
    createInterval,
    clearTimeout: clearTimeoutSafe,
    clearInterval: clearIntervalSafe,
  };
};

export default useMemoryCleanup;

import { useState, useEffect, useMemo, useCallback } from 'react';
import { useMemoryCleanup } from './useMemoryCleanup';

interface VirtualizedGridConfig {
  itemHeight: number;
  containerHeight: number;
  columnsPerRow: number;
  overscan?: number;
}

interface GridItem {
  id: number;
  [key: string]: any;
}

/**
 * Phase 4: Advanced Virtualized Grid Hook
 * High-performance virtualization for large datasets
 */
export const useVirtualizedGrid = <T extends GridItem>(
  items: T[],
  config: VirtualizedGridConfig
) => {
  const [scrollTop, setScrollTop] = useState(0);
  const [isScrolling, setIsScrolling] = useState(false);
  const { createTimeout, clearTimeout } = useMemoryCleanup();

  const {
    itemHeight,
    containerHeight,
    columnsPerRow,
    overscan = 3
  } = config;

  // Calculate visible range
  const visibleRange = useMemo(() => {
    const rowHeight = itemHeight;
    const totalRows = Math.ceil(items.length / columnsPerRow);

    const startRow = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
    const endRow = Math.min(
      totalRows,
      Math.ceil((scrollTop + containerHeight) / rowHeight) + overscan
    );

    const startIndex = startRow * columnsPerRow;
    const endIndex = Math.min(items.length, endRow * columnsPerRow);

    return {
      startIndex,
      endIndex,
      startRow,
      endRow,
      totalHeight: totalRows * rowHeight
    };
  }, [items.length, scrollTop, containerHeight, itemHeight, columnsPerRow, overscan]);

  // Get visible items
  const visibleItems = useMemo(() => {
    return items.slice(visibleRange.startIndex, visibleRange.endIndex);
  }, [items, visibleRange.startIndex, visibleRange.endIndex]);

  // Optimized scroll handler with debouncing
  const handleScroll = useCallback((event: React.UIEvent<HTMLDivElement>) => {
    const target = event.target as HTMLDivElement;
    setScrollTop(target.scrollTop);

    if (!isScrolling) {
      setIsScrolling(true);
    }

    // Clear previous timeout
    const timeoutId = createTimeout(() => {
      setIsScrolling(false);
    }, 150);

    return () => clearTimeout(timeoutId);
  }, [isScrolling, createTimeout, clearTimeout]);

  // Get item position
  const getItemPosition = useCallback((index: number) => {
    const row = Math.floor(index / columnsPerRow);
    const col = index % columnsPerRow;

    return {
      top: row * itemHeight,
      left: col * (100 / columnsPerRow),
      width: 100 / columnsPerRow
    };
  }, [itemHeight, columnsPerRow]);

  return {
    visibleItems,
    visibleRange,
    totalHeight: visibleRange.totalHeight,
    isScrolling,
    handleScroll,
    getItemPosition
  };
};

export default useVirtualizedGrid;

import { useState, useCallback } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '../lib/queryClient';

export interface WebsiteGenerationRequest {
  businessType: string;
  brandPersonality: string;
  targetAudience: string;
  keyFeatures: string[];
  colorPreferences?: string;
  contentStrategy: string;
  businessName: string;
  businessDescription: string;
}

export interface Website {
  id: string;
  preview: string;
  template: string;
  estimatedGenerationTime: number;
  status: 'draft' | 'generated' | 'deployed';
  deploymentUrl?: string;
}

export function useWebsiteBuilder() {
  const [currentStep, setCurrentStep] = useState(1);
  const [generationProgress, setGenerationProgress] = useState(0);
  const [currentWebsite, setCurrentWebsite] = useState<Website | null>(null);
  const queryClient = useQueryClient();

  const generateWebsite = useMutation({
    mutationFn: async (data: WebsiteGenerationRequest) => {
      const response = await apiRequest('/api/victoria/generate', 'POST', data);
      return response.website;
    },
    onSuccess: (website: Website) => {
      setCurrentWebsite(website);
      setGenerationProgress(100);
      queryClient.invalidateQueries({ queryKey: ['/api/victoria/websites'] });
    },
    onError: (error) => {
      console.error('Website generation failed:', error);
      setGenerationProgress(0);
    }
  });

  const customizeWebsite = useMutation({
    mutationFn: async ({ siteId, modifications }: { 
      siteId: string; 
      modifications: any 
    }) => {
      return await apiRequest('/api/victoria/customize', 'POST', {
        siteId,
        modifications
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/victoria/websites'] });
    }
  });

  const deployWebsite = useMutation({
    mutationFn: async ({ siteId, domainPreferences }: { 
      siteId: string; 
      domainPreferences?: any 
    }) => {
      return await apiRequest('/api/victoria/deploy', 'POST', {
        siteId,
        domainPreferences
      });
    },
    onSuccess: (deployment) => {
      if (currentWebsite) {
        setCurrentWebsite({
          ...currentWebsite,
          status: 'deployed',
          deploymentUrl: deployment.deployment.url
        });
      }
      queryClient.invalidateQueries({ queryKey: ['/api/victoria/websites'] });
    }
  });

  const { data: templates, isLoading: templatesLoading } = useQuery({
    queryKey: ['/api/victoria/templates'],
    retry: false
  });

  const simulateProgress = useCallback(() => {
    setGenerationProgress(0);
    const interval = setInterval(() => {
      setGenerationProgress(prev => {
        if (prev >= 90) {
          clearInterval(interval);
          return prev;
        }
        return prev + Math.random() * 15;
      });
    }, 1000);
    return interval;
  }, []);

  const resetBuilder = useCallback(() => {
    setCurrentStep(1);
    setGenerationProgress(0);
    setCurrentWebsite(null);
  }, []);

  const nextStep = useCallback(() => {
    setCurrentStep(prev => Math.min(prev + 1, 4));
  }, []);

  const prevStep = useCallback(() => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
  }, []);

  return {
    // State
    currentStep,
    generationProgress,
    currentWebsite,
    templates,
    templatesLoading,

    // Actions
    generateWebsite,
    customizeWebsite,
    deployWebsite,
    simulateProgress,
    resetBuilder,
    nextStep,
    prevStep,
    setCurrentStep,

    // Loading states
    isGenerating: generateWebsite.isPending,
    isCustomizing: customizeWebsite.isPending,
    isDeploying: deployWebsite.isPending
  };
}

// Standalone lightweight video preview modal controller
// This file is intentionally kept framework-agnostic so other scripts (including React components)
// can dispatch CustomEvents to show the preview without coupling.

interface VideoPreviewOptions {
	autoplay?: boolean;
	loop?: boolean;
	mute?: boolean;
	/** Canonical remote URL if a Blob is passed so downstream save can persist original */
	originalSrc?: string;
}

let currentObjectUrl: string | null = null;
let initialized = false;
let previousActiveElement: HTMLElement | null = null;
let scrollPosition = 0;

function qs<T extends HTMLElement = HTMLElement>(sel: string): T | null {
	return document.querySelector(sel) as T | null;
}

export function showVideoPreview(source: string | Blob, opts: VideoPreviewOptions = {}) {
	ensureInit();
	const modal = qs<HTMLDivElement>('#video-preview-modal');
	const player = qs<HTMLVideoElement>('#video-preview-player');
	if (!modal || !player) return;

	// Cleanup previous resource
	if (currentObjectUrl) {
		URL.revokeObjectURL(currentObjectUrl);
		currentObjectUrl = null;
	}

	// If a Blob provided, create an object URL
	let src: string;
	if (source instanceof Blob) {
		src = URL.createObjectURL(source);
		currentObjectUrl = src;
	} else {
		src = source;
	}

	player.src = src;
	// Persist original canonical URL (if provided) for save events
	// eslint-disable-next-line @typescript-eslint/ban-ts-comment
	// @ts-ignore
	window.__videoPreview = { ...(window as any).__videoPreview, showVideoPreview, hideVideoPreview, lastOriginalSrc: opts.originalSrc || (typeof source === 'string' ? source : undefined) };
	player.loop = !!opts.loop;
	player.muted = !!opts.mute;
	player.controls = true;

		modal.classList.add('active');
		modal.setAttribute('aria-hidden', 'false');
			modal.setAttribute('role', 'dialog');
			modal.setAttribute('aria-label', 'Video preview');
			modal.setAttribute('aria-modal', 'true');

		// Scroll lock
		scrollPosition = window.scrollY;
		document.body.style.top = `-${scrollPosition}px`;
		document.body.style.position = 'fixed';
		document.body.style.width = '100%';

		// Mark rest of body inert (simple approach)
		const root = document.getElementById('root');
		if (root) root.setAttribute('aria-hidden', 'true');

		// Focus handling
		previousActiveElement = document.activeElement as HTMLElement;
		const closeBtn = qs<HTMLButtonElement>('#video-preview-close');
		if (closeBtn) closeBtn.focus();

	// Autoplay handling (must follow a user gesture generally)
	if (opts.autoplay) {
		const playPromise = player.play();
		if (playPromise) {
			playPromise.catch(err => {
				console.warn('[VideoPreview] Autoplay blocked:', err);
			});
		}
	}
}

export function hideVideoPreview() {
	const modal = qs<HTMLDivElement>('#video-preview-modal');
	const player = qs<HTMLVideoElement>('#video-preview-player');
	if (!modal || !player) return;
	modal.classList.remove('active');
	modal.setAttribute('aria-hidden', 'true');
	player.pause();
	player.removeAttribute('src');
	player.load();
	if (currentObjectUrl) {
		URL.revokeObjectURL(currentObjectUrl);
		currentObjectUrl = null;
	}
	// Restore scroll
	document.body.style.position = '';
	document.body.style.top = '';
	document.body.style.width = '';
	window.scrollTo(0, scrollPosition);
	// Remove inert marker
	const root = document.getElementById('root');
	if (root) root.removeAttribute('aria-hidden');
	// Restore focus
	if (previousActiveElement) {
		previousActiveElement.focus();
		previousActiveElement = null;
	}
}

function onBackdropClick(e: MouseEvent) {
	const content = qs('.video-preview-content');
	if (!content) return;
	if (e.target instanceof Node && !content.contains(e.target)) {
		hideVideoPreview();
	}
}

function onKeyDown(e: KeyboardEvent) {
	if (e.key === 'Escape') {
		const modal = qs('#video-preview-modal');
		if (modal && modal.classList.contains('active')) {
			hideVideoPreview();
		}
	}
}

function trapFocus(e: KeyboardEvent) {
	if (e.key !== 'Tab') return;
	const modal = qs<HTMLDivElement>('#video-preview-modal');
	if (!modal || !modal.classList.contains('active')) return;
	const focusableSelectors = 'button, [href], video, [tabindex]:not([tabindex="-1"])';
	const focusables = Array.from(modal.querySelectorAll<HTMLElement>(focusableSelectors)).filter(el => !el.hasAttribute('disabled'));
	if (focusables.length === 0) return;
	const first = focusables[0];
	const last = focusables[focusables.length - 1];
	if (e.shiftKey && document.activeElement === first) {
		e.preventDefault();
		last.focus();
	} else if (!e.shiftKey && document.activeElement === last) {
		e.preventDefault();
		first.focus();
	}
}

function ensureInit() {
	if (initialized) return;
	initialized = true;
	const modal = qs('#video-preview-modal');
	const closeBtn = qs('#video-preview-close');

	if (modal) {
		modal.addEventListener('click', onBackdropClick);
	}
	if (closeBtn) {
		closeBtn.addEventListener('click', () => hideVideoPreview());
	}
		document.addEventListener('keydown', onKeyDown);
		document.addEventListener('keydown', trapFocus);

	// Custom event bridge for other scripts / React components
	window.addEventListener('video:preview', (e: Event) => {
		const detail = (e as CustomEvent).detail || {};
		if (detail && detail.source) {
			showVideoPreview(detail.source, detail.options || {});
		}
	});

	window.addEventListener('video:preview:hide', () => hideVideoPreview());
		// Add action buttons dynamically if not present (save/download)
		if (modal && !modal.querySelector('.video-preview-actions')) {
			const content = modal.querySelector('.video-preview-content');
			if (content) {
				const actionBar = document.createElement('div');
				actionBar.className = 'video-preview-actions';
				actionBar.style.position = 'absolute';
				actionBar.style.left = '12px';
				actionBar.style.bottom = '12px';
				actionBar.style.display = 'flex';
				actionBar.style.gap = '8px';

				const createBtn = (label: string, handler: () => void) => {
					const btn = document.createElement('button');
					btn.type = 'button';
					btn.textContent = label;
					btn.style.padding = '6px 12px';
					btn.style.fontSize = '12px';
					btn.style.letterSpacing = '0.1em';
					btn.style.textTransform = 'uppercase';
					btn.style.background = 'rgba(0,0,0,0.55)';
					btn.style.color = '#fff';
					btn.style.border = '1px solid rgba(255,255,255,0.25)';
					btn.style.borderRadius = '4px';
					btn.style.cursor = 'pointer';
					btn.style.backdropFilter = 'blur(4px)';
					btn.onmouseenter = () => (btn.style.background = 'rgba(0,0,0,0.75)');
					btn.onmouseleave = () => (btn.style.background = 'rgba(0,0,0,0.55)');
					btn.onclick = handler;
					return btn;
				};

				const saveBtn = createBtn('Save', () => {
					const player = qs<HTMLVideoElement>('#video-preview-player');
					if (!player || !player.src) return;
					const detail: Record<string, any> = { src: player.src };
					// eslint-disable-next-line @typescript-eslint/ban-ts-comment
					// @ts-ignore
					if ((window as any).__videoPreview?.lastOriginalSrc) {
						detail.originalSrc = (window as any).__videoPreview.lastOriginalSrc;
					}
					// Fire a custom save event so React layer can handle persistence
					window.dispatchEvent(new CustomEvent('video:preview:save', { detail }));
				});
				const downloadBtn = createBtn('Download', () => {
					const player = qs<HTMLVideoElement>('#video-preview-player');
					if (!player || !player.src) return;
					const a = document.createElement('a');
					a.href = player.src;
					a.download = `video-${Date.now()}.mp4`;
					document.body.appendChild(a);
					a.click();
					document.body.removeChild(a);
				});
				actionBar.appendChild(saveBtn);
				actionBar.appendChild(downloadBtn);
				content.appendChild(actionBar);
			}
		}

		console.log('[VideoPreview] Modal controller initialized with focus trap & actions');
}

// Auto init after DOM ready
if (document.readyState === 'loading') {
	document.addEventListener('DOMContentLoaded', ensureInit, { once: true });
} else {
	ensureInit();
}

// Expose helpers for manual triggering in console / other scripts
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
window.__videoPreview = { showVideoPreview, hideVideoPreview };

/**
 * Model Validation Helper for User Model Enforcement
 * Ensures every user has a completed AI model before any generation
 */

interface ModelValidationResponse {
  error?: string;
  requiresTraining?: boolean;
  trainingStatus?: string;
  redirectTo?: string;
}

interface ModelValidationError extends Error {
  requiresTraining?: boolean;
  trainingStatus?: string;
  redirectTo?: string;
}

export function isModelValidationError(error: any): error is ModelValidationError {
  return error && typeof error === 'object' && 
         (error.requiresTraining === true || 
          error.message?.includes('AI model') || 
          error.message?.includes('training'));
}

export function handleModelValidationError(error: ModelValidationError, toast: any, navigate: any) {
  // Show user-friendly error message
  toast({
    title: "AI Model Required",
    description: error.message || "Please complete your AI model training first.",
    variant: "destructive",
  });

  // Redirect to training page after short delay
  setTimeout(() => {
    navigate(error.redirectTo || '/simple-training');
  }, 1500);
}

export function parseModelValidationResponse(response: any): ModelValidationResponse | null {
  if (response.requiresTraining || response.trainingStatus) {
    return {
      error: response.error,
      requiresTraining: response.requiresTraining,
      trainingStatus: response.trainingStatus,
      redirectTo: response.redirectTo
    };
  }
  return null;
}

import { QueryClient, QueryFunction } from "@tanstack/react-query";

async function throwIfResNotOk(res: Response) {
  if (!res.ok) {
    const text = (await res.text()) || res.statusText;
    throw new Error(`${res.status}: ${text}`);
  }
}

// Use current domain's API endpoints for production
function getApiUrl(url: string): string {
  return url;
}

export async function apiRequest(
  url: string,
  method: string = 'GET',
  data?: unknown | undefined,
): Promise<any> {
  const finalUrl = getApiUrl(url);

  const res = await fetch(finalUrl, {
    method,
    headers: {
      ...(data ? { "Content-Type": "application/json" } : {}),
      'Cache-Control': 'no-cache',
    },
    body: data ? JSON.stringify(data) : undefined,
    credentials: "include",
  });

  await throwIfResNotOk(res);

  // Handle JSON responses properly
  const contentType = res.headers.get('content-type');
  if (contentType && contentType.includes('application/json')) {
    return await res.json();
  }

  return res;
}

type UnauthorizedBehavior = "returnNull" | "throw";
export const getQueryFn: <T>(options: {
  on401: UnauthorizedBehavior;
}) => QueryFunction<T> =
  ({ on401: unauthorizedBehavior }) =>
  async ({ queryKey }) => {
    const url = queryKey[0] as string;
    const finalUrl = getApiUrl(url);

    const res = await fetch(finalUrl, {
      credentials: "include",
    });

    if (unauthorizedBehavior === "returnNull" && res.status === 401) {
      return null;
    }

    await throwIfResNotOk(res);
    return await res.json();
  };

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      queryFn: getQueryFn({ on401: "throw" }),
      refetchInterval: false,
      refetchOnWindowFocus: false,
      staleTime: 5 * 60 * 1000, // 5 minutes for user data
      gcTime: 10 * 60 * 1000, // 10 minutes garbage collection
      retry: (failureCount, error: any) => {
        // Don't retry on 4xx errors except 408/429
        if (error?.message?.includes('4') && !error.message.includes('408') && !error.message.includes('429')) {
          return false;
        }
        return failureCount < 2;
      },
    },
    mutations: {
      retry: false,
    },
  },
});

