                className="w-full px-3 py-2 border border-[#e5e5e5] focus:outline-none focus:border-black"
                disabled={isCreating}
              />
            </div>

            <div>
              <label htmlFor="flux-mood-keywords" className="block text-sm font-medium mb-2">
                Mood Keywords
              </label>
