  // Chat with Rachel
  const chatMutation = useMutation({
    mutationFn: async (data: { task: string; context: string }) => {
      return apiRequest('POST', '/api/agents/ask', {
        agentId: 'rachel',
        task: data.task,
        context: data.context
      });
    },
    onSuccess: () => {
      toast({
        title: "Message Sent",
        description: "Rachel has responded to your request"
      });
    }
  });

