import React, { useState, useEffect } from 'react';
import { MemberNavigation } from '../components/member-navigation';
import { useAuth } from '../hooks/use-auth';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { apiRequest } from '../lib/queryClient';
import { useToast } from '../hooks/use-toast';

interface Subscription {
  id: string;
  status: string;
  current_period_end: number;
  cancel_at: number | null;
  canceled_at: number | null;
  plan: {
    amount: number;
    currency: string;
    interval: string;
  };
}

interface Invoice {
  id: string;
  amount_paid: number;
  currency: string;
  status: string;
  created: number;
  hosted_invoice_url: string;
  invoice_pdf: string;
}

export default function Settings() {
  const { user } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [showCancelConfirm, setShowCancelConfirm] = useState(false);

  // Fetch subscription data
  const { data: subscription, isLoading: subscriptionLoading } = useQuery({
    queryKey: ['/api/subscription'],
    enabled: !!user,
  });

  // Fetch invoices
  const { data: invoices = [], isLoading: invoicesLoading } = useQuery({
    queryKey: ['/api/invoices'],
    enabled: !!user,
  });

  // Cancel subscription mutation
  const cancelSubscription = useMutation({
    mutationFn: async () => {
      return await apiRequest('/api/subscription/cancel', 'POST');
    },
    onSuccess: () => {
      toast({
        title: "Subscription Cancelled",
        description: "Your subscription has been cancelled. You'll continue to have access until your current period ends.",
      });
      queryClient.invalidateQueries({ queryKey: ['/api/subscription'] });
      setShowCancelConfirm(false);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: "Unable to cancel subscription. Please contact support.",
      });
    },
  });

  // Reactivate subscription mutation
  const reactivateSubscription = useMutation({
    mutationFn: async () => {
      return await apiRequest('/api/subscription/reactivate', 'POST');
