// Memory management
export const throttle = <T extends (...args: any[]) => any>(
  func: T,
  limit: number
): ((...args: Parameters<T>) => void) => {
  let inThrottle: boolean;
  return function (this: any, ...args: Parameters<T>) {
    if (!inThrottle) {
      func.apply(this, args);
      inThrottle = true;
      setTimeout(() => (inThrottle = false), limit);
    }
  };
};

export const debounce = <T extends (...args: any[]) => any>(
  func: T,
  wait: number
): ((...args: Parameters<T>) => void) => {
  let timeout: NodeJS.Timeout;
  return function (this: any, ...args: Parameters<T>) {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
};

// Query optimization
export const getOptimalStaleTime = (dataType: 'user' | 'gallery' | 'generation' | 'static'): number => {
  switch (dataType) {
    case 'user':
      return 5 * 60 * 1000; // 5 minutes
    case 'gallery':
      return 2 * 60 * 1000; // 2 minutes
    case 'generation':
      return 10 * 1000; // 10 seconds
    case 'static':
      return 60 * 60 * 1000; // 1 hour
    default:
      return 30 * 1000; // 30 seconds
  }
};

// Cleanup utilities
export const createAbortController = () => {
  const controller = new AbortController();
  return {
    signal: controller.signal,
    abort: () => controller.abort(),
  };
};

// Performance monitoring
export const measurePerformance = (name: string, fn: () => void) => {
  if (process.env.NODE_ENV === 'development') {
    performance.mark(`${name}-start`);
    fn();
    performance.mark(`${name}-end`);
    performance.measure(name, `${name}-start`, `${name}-end`);
  } else {
    fn();
  }
};

export default {
  optimizeImageLoading,
  enableServiceWorkerCaching,
  throttle,
  debounce,
  getOptimalStaleTime,
  createAbortController,
  measurePerformance,
};

// PWA Installation and Management Utilities
// Handles app installation prompts and PWA features

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

class PWAManager {
  private deferredPrompt: BeforeInstallPromptEvent | null = null;
  private isInstalled = false;

  constructor() {
    this.init();
  }

  private init() {
    // Check if already installed
    this.checkInstallStatus();

    // Listen for install prompt
    window.addEventListener('beforeinstallprompt', (e: Event) => {
      e.preventDefault();
      this.deferredPrompt = e as BeforeInstallPromptEvent;
      this.showInstallBanner();
    });

    // Listen for successful installation
    window.addEventListener('appinstalled', () => {
      console.log('SSELFIE Studio: PWA installed successfully');
      this.isInstalled = true;
      this.hideInstallBanner();
      this.trackInstallation();
    });

    // Register service worker
    this.registerServiceWorker();
  }

  private async registerServiceWorker() {
    if ('serviceWorker' in navigator && process.env.NODE_ENV === 'production') {
      try {
        const registration = await navigator.serviceWorker.register('/sw.js');
        console.log('SSELFIE Studio: Service Worker registered', registration);

        // Handle updates - add error handling to prevent promise rejections
        registration.addEventListener('updatefound', () => {
          const newWorker = registration.installing;
          if (newWorker) {
            newWorker.addEventListener('statechange', () => {
              try {
                if (newWorker.state === 'installed' && navigator.serviceWorker.controller) {
                  this.showUpdateAvailable();
                }
              } catch (stateError) {
                console.warn('SSELFIE Studio: Service Worker state change error', stateError);
              }
            });
          }
        });
      } catch (error) {
        console.warn('SSELFIE Studio: Service Worker registration failed (expected in dev)', error);
        // Don't rethrow - just log and continue
      }
    }
  }

  private checkInstallStatus() {
    // Check if running as installed PWA
    if (window.matchMedia('(display-mode: standalone)').matches) {
      this.isInstalled = true;
    }

    // Check if running in TWA (Trusted Web Activity)
    if (document.referrer.includes('android-app://')) {
      this.isInstalled = true;
    }
  }

  public async showInstallPrompt(): Promise<boolean> {
    if (!this.deferredPrompt) {
      return false;
    }

    try {
      await this.deferredPrompt.prompt();
      const { outcome } = await this.deferredPrompt.userChoice;

      if (outcome === 'accepted') {
        console.log('SSELFIE Studio: User accepted install prompt');
        return true;
      } else {
        console.log('SSELFIE Studio: User dismissed install prompt');
        return false;
      }
    } catch (error) {
      console.error('SSELFIE Studio: Install prompt failed', error);
      return false;
    }
  }

  private showInstallBanner() {
    // Create elegant install banner
    const banner = document.createElement('div');
    banner.id = 'pwa-install-banner';
    banner.innerHTML = `
      <div style="
        position: fixed;
        bottom: 20px;
        left: 50%;
        transform: translateX(-50%);
        background: #0a0a0a;
        color: white;
        padding: 16px 24px;
        border-radius: 0;
        z-index: 10000;
        font-family: 'Times New Roman', serif;
        font-size: 14px;
        letter-spacing: 0.3em;
        text-transform: uppercase;
        box-shadow: 0 4px 20px rgba(0,0,0,0.3);
        max-width: 320px;
        text-align: center;
        animation: slideUp 0.3s ease-out;
      ">
        <div style="margin-bottom: 12px; font-weight: 300;">
          Install SSELFIE Studio
        </div>
        <div style="display: flex; gap: 12px; justify-content: center;">
          <button id="pwa-install-btn" style="
            background: white;
            color: #0a0a0a;
            border: none;
            padding: 8px 16px;
            font-size: 11px;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            cursor: pointer;
            font-family: inherit;
          ">Install</button>
          <button id="pwa-dismiss-btn" style="
            background: transparent;
            color: white;
            border: 1px solid white;
            padding: 8px 16px;
            font-size: 11px;
            letter-spacing: 0.2em;
            text-transform: uppercase;
            cursor: pointer;
            font-family: inherit;
          ">Later</button>
        </div>
      </div>
      <style>
        @keyframes slideUp {
          from { transform: translate(-50%, 100px); opacity: 0; }
          to { transform: translate(-50%, 0); opacity: 1; }
        }
      </style>
    `;

    document.body.appendChild(banner);

    // Handle install button
    document.getElementById('pwa-install-btn')?.addEventListener('click', () => {
      this.showInstallPrompt();
      this.hideInstallBanner();
    });

    // Handle dismiss button
    document.getElementById('pwa-dismiss-btn')?.addEventListener('click', () => {
      this.hideInstallBanner();
    });

    // Auto-hide after 10 seconds
    setTimeout(() => {
      this.hideInstallBanner();
    }, 10000);
  }

  private hideInstallBanner() {
    const banner = document.getElementById('pwa-install-banner');
    if (banner) {
      banner.style.animation = 'slideDown 0.3s ease-out forwards';
      setTimeout(() => banner.remove(), 300);
    }
  }

  private showUpdateAvailable() {
    // Simple update notification
    console.log('SSELFIE Studio: Update available');

    // Could show a toast notification here
    if (window.location.pathname === '/') {
      const updateBanner = document.createElement('div');
      updateBanner.innerHTML = `
        <div style="
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          background: #0a0a0a;
          color: white;
          padding: 12px;
          text-align: center;
          font-size: 12px;
          letter-spacing: 0.2em;
          text-transform: uppercase;
          z-index: 10001;
        ">
          New version available. Refresh to update.
        </div>
      `;
      document.body.appendChild(updateBanner);
    }
  }

  private trackInstallation() {
    // Track PWA installation for analytics
    console.log('SSELFIE Studio: PWA installation tracked');

    // Could send to analytics service here
    try {
      if (typeof (window as any).gtag !== 'undefined') {
        (window as any).gtag('event', 'pwa_install', {
          event_category: 'engagement',
          event_label: 'PWA installed'
        });
      }
    } catch (error) {
      // Analytics tracking is optional
      console.debug('Analytics tracking not available');
    }
  }

  public get canInstall(): boolean {
    return !!this.deferredPrompt && !this.isInstalled;
  }

  public get isAppInstalled(): boolean {
    return this.isInstalled;
  }
}

