/**
 * Dependency Analysis Script
 * Analyzes project dependencies and generates reports
 */

import madge from 'madge';
import fs from 'fs';
import path from 'path';

async function analyzeDependencies() {
  console.log('🔍 Analyzing project dependencies...');

  try {
    // Analyze dependencies
    const tree = await madge('.', {
      exclude: ['node_modules', '.git', '.next', 'dist', 'build', 'coverage']
    });

    // Get dependency data
    const dependencies = tree.obj();
    const dependentsMap = tree.obj();

    // Check for circular dependencies
    const circular = tree.circular();

    // Generate reports
    console.log('\n📊 Dependency Analysis Results:');
    console.log('================================');

    // Basic stats
    console.log(`\n📈 Basic Statistics:`);
    console.log(`- Total files analyzed: ${Object.keys(dependencies).length}`);
    console.log(`- Total dependencies: ${Object.values(dependencies).flat().length}`);
    console.log(`- Circular dependencies: ${circular.length}`);

    // Most connected files
    console.log(`\n🔗 Most Connected Files:`);
    const fileConnections = Object.entries(dependencies).map(([file, deps]) => ({
      file,
      incoming: dependentsMap[file]?.length || 0,
      outgoing: deps.length,
      total: (dependentsMap[file]?.length || 0) + deps.length
    })).sort((a, b) => b.total - a.total).slice(0, 10);

    fileConnections.forEach(({ file, incoming, outgoing, total }, index) => {
      console.log(`${index + 1}. ${file} (${total} connections: ${incoming} incoming, ${outgoing} outgoing)`);
    });

    // Circular dependencies
    if (circular.length > 0) {
      console.log(`\n⚠️  Circular Dependencies Found:`);
      circular.forEach((cycle, index) => {
        console.log(`${index + 1}. ${cycle.join(' → ')}`);
      });
    } else {
      console.log(`\n✅ No circular dependencies found!`);
    }

    // Service boundaries analysis
    console.log(`\n🏗️  Service Boundaries Analysis:`);
    const serviceFiles = Object.keys(dependencies).filter(file => 
      file.includes('service') || file.includes('api') || file.includes('route')
    );

    console.log(`- Service-related files: ${serviceFiles.length}`);
    serviceFiles.forEach(file => {
      const deps = dependencies[file] || [];
      const dependents = dependentsMap[file] || [];
      console.log(`  - ${file}: ${deps.length} dependencies, ${dependents.length} dependents`);
    });

    // Save detailed report
    const report = {
      timestamp: new Date().toISOString(),
      summary: {
        totalFiles: Object.keys(dependencies).length,
        totalDependencies: Object.values(dependencies).flat().length,
        circularDependencies: circular.length,
        serviceFiles: serviceFiles.length
      },
      mostConnected: fileConnections,
      circularDependencies: circular,
      serviceFiles: serviceFiles.map(file => ({
        file,
        dependencies: dependencies[file] || [],
        dependents: dependentsMap[file] || []
      }))
    };

    fs.writeFileSync('dependency-analysis-report.json', JSON.stringify(report, null, 2));
    console.log(`\n📄 Detailed report saved to: dependency-analysis-report.json`);

  } catch (error) {
    console.error('❌ Error analyzing dependencies:', error.message);
    process.exit(1);
  }
}

// Run analysis
analyzeDependencies();

