import { Request, Response, NextFunction } from 'express';
import { logger } from '../config/monitoring';

// Extend Express Request type to include user property
declare global {
  namespace Express {
    interface Request {
      user?: any;
    }
  }
}

// Custom error class
export class AppError extends Error {
  statusCode: number;
  status: string;
  isOperational: boolean;

  constructor(message: string, statusCode: number) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;

    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handling middleware
export const errorHandler = (
  err: AppError,
  req: Request,
  res: Response,
  next: NextFunction
) => {
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Log error
  logger.error({
    error: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    body: req.body,
    user: req.user,
  });

  // Log server errors for monitoring
  if (err.statusCode >= 500) {
    logger.error(`Server Error: ${err.message}`);
  }

  // Development error response
  if (process.env.NODE_ENV === 'development') {
    return res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  }

  // Production error response
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message
    });
  }

  // Programming or unknown errors: don't leak error details
  return res.status(500).json({
    status: 'error',
    message: 'Something went wrong'
  });
};

// ZARA'S PERFORMANCE OPTIMIZATION MIDDLEWARE
// Implementing server-side performance improvements

import { Request, Response, NextFunction } from 'express';
import compression from 'compression';

// Response compression middleware  
export const compressionMiddleware = compression({
  filter: (req: Request, res: Response) => {
    if (req.headers['x-no-compression']) {
      return false;
    }
    return compression.filter(req, res);
  },
  level: 6, // Good balance between compression ratio and speed
  threshold: 1024 // Only compress responses larger than 1KB
});

// Response caching middleware
export const cacheMiddleware = (duration: number = 300) => {
  return (req: Request, res: Response, next: NextFunction) => {
    // Set cache headers for static assets
    if (req.url.match(/\.(css|js|png|jpg|jpeg|gif|ico|svg)$/)) {
      res.setHeader('Cache-Control', `public, max-age=${duration}`);
    }
    next();
  };
};

// API response optimization middleware
export const apiOptimizationMiddleware = (req: Request, res: Response, next: NextFunction) => {
  const originalSend = res.send;
  const startTime = Date.now();

  res.send = function(data: any) {
    const responseTime = Date.now() - startTime;

    // Add performance headers
    res.setHeader('X-Response-Time', `${responseTime}ms`);
    res.setHeader('X-Powered-By', 'SSELFIE-Studio');

    // Log slow responses
    if (responseTime > 1000) {
      console.warn(`Slow API response: ${req.method} ${req.url} took ${responseTime}ms`);
    }

    return originalSend.call(this, data);
  };

  next();
};

// Request size limiting middleware
export const requestSizeLimiter = (limit: string = '10mb') => {
  return (req: Request, res: Response, next: NextFunction) => {
    const contentLength = parseInt(req.get('content-length') || '0', 10);
    const maxSize = parseInt(limit.replace(/[^\d]/g, '')) * (limit.includes('mb') ? 1024 * 1024 : 1024);

    if (contentLength > maxSize) {
      return res.status(413).json({
        error: 'Request entity too large',
        maxSize: limit,
        receivedSize: `${Math.round(contentLength / 1024)}KB`
      });
    }

    next();
  };
};

// Memory usage monitoring
export const memoryMonitor = (req: Request, res: Response, next: NextFunction) => {
  const memUsage = process.memoryUsage();
  const memoryMB = {
    rss: Math.round(memUsage.rss / 1024 / 1024),
    heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024),
    heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024),
    external: Math.round(memUsage.external / 1024 / 1024)
  };

  // Log high memory usage
  if (memoryMB.heapUsed > 512) { // Alert if heap usage > 512MB
    console.warn(`High memory usage detected: ${memoryMB.heapUsed}MB heap used`);
  }

  // Add memory info to response headers in development
  if (process.env.NODE_ENV === 'development') {
    res.setHeader('X-Memory-Usage', JSON.stringify(memoryMB));
  }

  next();
};

/**
 * Rate Limiting Middleware
 * Provides rate limiting for API endpoints
 */

import { Request, Response, NextFunction } from 'express';
import { Logger } from '../utils/logger';

export interface RateLimitOptions {
  windowMs: number; // Time window in milliseconds
  maxRequests: number; // Maximum requests per window
  skipSuccessfulRequests?: boolean; // Don't count successful requests
  skipFailedRequests?: boolean; // Don't count failed requests
  keyGenerator?: (req: Request) => string; // Custom key generator
  message?: string; // Custom error message
  statusCode?: number; // Custom status code
}

export interface RateLimitInfo {
  limit: number;
  remaining: number;
  reset: number;
  retryAfter?: number;
}

class RateLimiter {
  private requests = new Map<string, { count: number; resetTime: number }>();
  private logger: Logger;

  constructor() {
    this.logger = new Logger('RateLimiter');

    // Clean up expired entries every minute
    setInterval(() => {
      this.cleanup();
    }, 60000);
  }

  /**
   * Create rate limiting middleware
   */
  create(options: RateLimitOptions) {
    return (req: Request, res: Response, next: NextFunction) => {
      const key = options.keyGenerator ? options.keyGenerator(req) : this.getDefaultKey(req);
      const now = Date.now();
      const windowStart = now - options.windowMs;

      // Get or create request record
      let record = this.requests.get(key);
      if (!record || record.resetTime < now) {
        record = {
          count: 0,
          resetTime: now + options.windowMs
        };
        this.requests.set(key, record);
      }

      // Check if limit exceeded
      if (record.count >= options.maxRequests) {
        const retryAfter = Math.ceil((record.resetTime - now) / 1000);

        this.logger.warn('Rate limit exceeded', {
          key,
          limit: options.maxRequests,
          count: record.count,
          retryAfter
        });

        res.set({
          'X-RateLimit-Limit': options.maxRequests.toString(),
          'X-RateLimit-Remaining': '0',
          'X-RateLimit-Reset': new Date(record.resetTime).toISOString(),
          'Retry-After': retryAfter.toString()
        });

        return res.status(options.statusCode || 429).json({
          success: false,
          error: {
            message: options.message || 'Too many requests',
            code: 'RATE_LIMIT_EXCEEDED',
            retryAfter
          }
        });
      }

      // Increment counter
      record.count++;

      // Set rate limit headers
      const remaining = Math.max(0, options.maxRequests - record.count);
      res.set({
        'X-RateLimit-Limit': options.maxRequests.toString(),
        'X-RateLimit-Remaining': remaining.toString(),
        'X-RateLimit-Reset': new Date(record.resetTime).toISOString()
      });

      // Track successful/failed requests if needed
      if (options.skipSuccessfulRequests || options.skipFailedRequests) {
        const originalSend = res.send;
        res.send = function (body: any) {
          const isSuccess = res.statusCode >= 200 && res.statusCode < 400;

          if ((options.skipSuccessfulRequests && isSuccess) || 
              (options.skipFailedRequests && !isSuccess)) {
            record!.count = Math.max(0, record!.count - 1);
          }

          return originalSend.call(this, body);
        };
      }

      next();
    };
  }

  /**
   * Get default key for rate limiting
   */
  private getDefaultKey(req: Request): string {
    const ip = req.ip || req.connection.remoteAddress || 'unknown';
    const userAgent = req.get('User-Agent') || 'unknown';
    return `${ip}:${userAgent}`;
  }

  /**
   * Clean up expired entries
   */
  private cleanup(): void {
    const now = Date.now();
    let cleaned = 0;

    for (const [key, record] of this.requests.entries()) {
      if (record.resetTime < now) {
        this.requests.delete(key);
        cleaned++;
      }
    }

    if (cleaned > 0) {
      this.logger.debug(`Cleaned up ${cleaned} expired rate limit entries`);
    }
  }

  /**
   * Get rate limit info for a key
   */
  getInfo(key: string): RateLimitInfo | null {
    const record = this.requests.get(key);
    if (!record) return null;

    return {
      limit: 0, // Will be set by middleware
      remaining: 0, // Will be set by middleware
      reset: record.resetTime,
      retryAfter: record.resetTime > Date.now() ? 
        Math.ceil((record.resetTime - Date.now()) / 1000) : undefined
    };
  }

  /**
   * Reset rate limit for a key
   */
  reset(key: string): boolean {
    return this.requests.delete(key);
  }

  /**
   * Get all active rate limits
   */
  getAllInfo(): Array<{ key: string; info: RateLimitInfo }> {
    const results: Array<{ key: string; info: RateLimitInfo }> = [];

    for (const [key, record] of this.requests.entries()) {
      const info = this.getInfo(key);
      if (info) {
        results.push({ key, info });
      }
    }

    return results;
  }
}

