   */
  private static readonly FIXED_POLICY = {
    "Version": "2012-10-17",
    "Statement": [
      {
        "Sid": "AllowSSelfieS3UserFullAccess",
        "Effect": "Allow",
        "Principal": {
          "AWS": "arn:aws:iam::440740774281:user/sselfie-s3-user"
