        if (toolCall.input.new_str) {
          const validation = localProcessingEngine.validateCodeLocally(
            toolCall.input.new_str,
            toolCall.input.path || ''
          );

          if (!validation.valid) {
            console.warn(`⚠️ LOCAL VALIDATION WARNINGS for ${agentName}:`, validation.errors);
