  private async saveMessage(conversationId: string, role: string, content: string, toolCalls?: any, toolResults?: any) {
    // Save message with tool data
    await db.insert(claudeMessages).values({
      conversationId,
      role,
      content,
      metadata: null,
      toolCalls,
      toolResults,
      timestamp: new Date(),
      createdAt: new Date(),
    });

    // Update conversation metadata and message count
    const [conversation] = await db
      .select()
      .from(claudeConversations)
      .where(eq(claudeConversations.conversationId, conversationId))
      .limit(1);

    if (conversation) {
      await db
        .update(claudeConversations)
        .set({
          lastMessageAt: new Date(),
          messageCount: (conversation.messageCount || 0) + 1,
          updatedAt: new Date(),
        })
        .where(eq(claudeConversations.conversationId, conversationId));

      console.log(`✅ Updated conversation ${conversationId}: messageCount=${(conversation.messageCount || 0) + 1}`);
    }
  }

  // REMOVED: All token-heavy processing methods moved to local processing engine for optimization

  // ENHANCED LEARNING RETRIEVAL METHODS
  async getAgentLearningInsights(agentName: string, userId: string): Promise<any> {
    try {
      const normalizedAgentName = agentName.toLowerCase();

      // Get learning patterns grouped by category
      const learningData = await db
        .select()
        .from(agentLearning)
        .where(and(
          eq(agentLearning.agentName, normalizedAgentName),
          eq(agentLearning.userId, userId)
        ))
        .orderBy(desc(agentLearning.lastSeen))
        .limit(100);

      // Analyze patterns by category
      const insights = {
        totalPatterns: learningData.length,
        categories: {} as Record<string, any>,
        recentActivity: learningData.slice(0, 10),
        confidenceAverage: 0,
        topPatterns: []
      };

      // Group by category and calculate insights
      for (const pattern of learningData) {
        const category = pattern.category || 'general';
        if (!insights.categories[category]) {
          insights.categories[category] = {
            count: 0,
            avgConfidence: 0,
            patterns: []
          };
        }

        insights.categories[category].count++;
        insights.categories[category].patterns.push(pattern);
        insights.categories[category].avgConfidence = 
          insights.categories[category].patterns.reduce((sum: number, p: any) => 
            sum + parseFloat(p.confidence?.toString() || '0'), 0) / insights.categories[category].patterns.length;
      }

      // Calculate overall confidence average
      insights.confidenceAverage = learningData.reduce((sum, p) => 
        sum + parseFloat(p.confidence?.toString() || '0'), 0) / learningData.length;

      return insights;
    } catch (error) {
      console.error('Failed to get agent learning insights:', error);
      return null;
    }
  }

  /**
   * VISION ANALYSIS METHOD - For analyzing images with Claude Vision
   * Used specifically for Maya's video direction service
   */
  async sendMessageWithImage(
    message: string,
    imageUrl: string,
    conversationId: string,
    agentName: string,
    systemPrompt?: string
  ): Promise<string> {
    console.log(`🎨 VISION ANALYSIS: ${agentName} analyzing image from URL: ${imageUrl.substring(0, 50)}...`);

    try {
      // Load agent configuration
      const { PersonalityManager, PURE_PERSONALITIES } = await import('../agents/personalities/personality-config.js');
      const agentConfig = PURE_PERSONALITIES[agentName as keyof typeof PURE_PERSONALITIES];

      if (!agentConfig) {
        throw new Error(`Agent ${agentName} not found`);
      }

      // Fetch the image and convert to base64
      console.log(`🖼️ VISION: Fetching image from URL: ${imageUrl}`);

      const imageResponse = await fetch(imageUrl);
      if (!imageResponse.ok) {
        throw new Error(`Failed to fetch image: ${imageResponse.status} ${imageResponse.statusText}`);
      }

      const imageBuffer = await imageResponse.arrayBuffer();
      const base64Image = Buffer.from(imageBuffer).toString('base64');

      // Detect image type from URL or default to PNG
      let mediaType = 'image/png';
      if (imageUrl.toLowerCase().includes('.jpg') || imageUrl.toLowerCase().includes('.jpeg')) {
        mediaType = 'image/jpeg';
      } else if (imageUrl.toLowerCase().includes('.webp')) {
        mediaType = 'image/webp';
      }

      console.log(`🖼️ VISION: Image converted to base64 (${mediaType}, ${Math.round(base64Image.length / 1024)}KB)`);

      // Use Claude Vision API with proper image format
      const response = await anthropic.messages.create({
        model: DEFAULT_MODEL_STR,
        max_tokens: 1000,
        system: systemPrompt || agentConfig.systemPrompt,
        messages: [
          {
            role: 'user',
            content: [
              {
                type: 'image',
                source: {
                  type: 'base64',
                  media_type: mediaType,
                  data: base64Image
                }
              },
              {
                type: 'text',
                text: message
              }
            ]
          }
        ]
      });

      const content = response.content[0];
      if (content.type === 'text') {
        console.log(`✅ VISION ANALYSIS COMPLETE: ${agentName} analyzed image successfully`);
        console.log(`🎬 Generated prompt preview: "${content.text.substring(0, 100)}..."`);
        return content.text;
      } else {
        throw new Error('Unexpected response format from Claude Vision');
      }

    } catch (error: any) {
      console.error(`❌ VISION ANALYSIS ERROR (${agentName}):`, error);

      // Provide a professional fallback response if image analysis fails
      const fallbackPrompt = "Slow zoom in on the subject with subtle depth-of-field transitions, highlighting natural expression and professional lighting while maintaining elegant composition.";

      console.log(`🔄 VISION FALLBACK: Using professional default prompt`);
      return fallbackPrompt;
    }
  }
