/**
 * Progress Tracking Service
 * Real-time progress monitoring and analytics for multi-agent workflows
 * SSELFIE Studio Enhancement Project - Maya Implementation
 */

import { taskDependencyMapping } from './task-dependency-mapping';
// REMOVED: Old checkpoint-automation - replaced with advanced workflow orchestration

interface ProgressMetrics {
  timestamp: Date;
  workflowId: string;
  agentId?: string;
  taskId?: string;
  metric: string;
  value: number;
  unit: string;
  metadata: Record<string, any>;
}

interface ProgressSnapshot {
  id: string;
  timestamp: Date;
  workflowProgress: Record<string, any>;
  agentStatus: Record<string, any>;
  systemMetrics: Record<string, any>;
  milestones: Array<{
    name: string;
    completedAt: Date;
    duration: number;
  }>;
}

interface RealTimeUpdate {
  type: 'task_update' | 'agent_status' | 'milestone' | 'error' | 'warning';
  timestamp: Date;
  source: string;
  message: string;
  data: Record<string, any>;
  priority: 'low' | 'medium' | 'high' | 'critical';
}

export class ProgressTrackingService {
  private metrics: ProgressMetrics[] = [];
  private snapshots: ProgressSnapshot[] = [];
  private realTimeUpdates: RealTimeUpdate[] = [];
  private subscribers: Map<string, (update: RealTimeUpdate) => void> = new Map();
  private trackingInterval: NodeJS.Timeout | null = null;
  private isTracking = false;

  constructor() {
    this.startTracking();
  }

  /**
   * Start real-time progress tracking
   */
  startTracking(): void {
    if (this.isTracking) return;

    this.isTracking = true;
    // console.log('📊 PROGRESS TRACKING: Real-time monitoring started');

    // Create snapshot every 5 minutes
    this.trackingInterval = setInterval(() => {
      this.createProgressSnapshot();
      this.cleanupOldData();
    }, 5 * 60 * 1000);

    // Record initial snapshot
    this.createProgressSnapshot();
  }

  /**
   * Stop progress tracking
   */
  stopTracking(): void {
    if (!this.isTracking) return;

    this.isTracking = false;
    if (this.trackingInterval) {
      clearInterval(this.trackingInterval);
      this.trackingInterval = null;
    }

    console.log('⏹️ PROGRESS TRACKING: Monitoring stopped');
  }

  /**
   * Record a progress metric
   */
  recordMetric(
    workflowId: string,
    metric: string,
    value: number,
    unit: string = '',
    agentId?: string,
    taskId?: string,
    metadata: Record<string, any> = {}
  ): void {
    const progressMetric: ProgressMetrics = {
      timestamp: new Date(),
      workflowId,
      agentId,
      taskId,
      metric,
      value,
      unit,
      metadata
    };

    this.metrics.push(progressMetric);

    // Broadcast real-time update
    this.broadcastUpdate({
      type: 'task_update',
      timestamp: new Date(),
      source: agentId || 'system',
      message: `${metric}: ${value} ${unit}`,
      data: progressMetric,
      priority: 'medium'
    });

    console.log(`📈 METRIC RECORDED: ${metric} = ${value} ${unit} (${workflowId})`);
  }

  /**
   * Create progress snapshot
   */
  private createProgressSnapshot(): void {
    const snapshot: ProgressSnapshot = {
      id: `snapshot_${Date.now()}`,
      timestamp: new Date(),
      workflowProgress: this.captureWorkflowProgress(),
      agentStatus: this.captureAgentStatus(),
      systemMetrics: this.captureSystemMetrics(),
      milestones: this.captureMilestones()
    };

    this.snapshots.push(snapshot);

    // Keep only last 100 snapshots
    if (this.snapshots.length > 100) {
      this.snapshots = this.snapshots.slice(-100);
    }

    // console.log(`📸 SNAPSHOT CREATED: ${snapshot.id}`);
  }

  /**
   * Get real-time dashboard data
   */
  getDashboardData(): {
    currentProgress: Record<string, any>;
    recentUpdates: RealTimeUpdate[];
    performanceMetrics: Record<string, any>;
    agentActivity: Record<string, any>;
    trends: Record<string, any>;
  } {
    const latestSnapshot = this.snapshots[this.snapshots.length - 1];

    return {
      currentProgress: latestSnapshot ? latestSnapshot.workflowProgress : {},
      recentUpdates: this.realTimeUpdates.slice(-20).reverse(),
      performanceMetrics: this.calculatePerformanceMetrics(),
      agentActivity: this.calculateAgentActivity(),
      trends: this.calculateTrends()
    };
  }

  /**
   * Get progress history for specific workflow
   */
  getWorkflowHistory(workflowId: string, timeRange: number = 24): {
    snapshots: ProgressSnapshot[];
    metrics: ProgressMetrics[];
    milestones: Array<{
      name: string;
      completedAt: Date;
      duration: number;
    }>;
  } {
    const cutoffTime = new Date(Date.now() - timeRange * 60 * 60 * 1000);

    const filteredSnapshots = this.snapshots.filter(
      snapshot => snapshot.timestamp >= cutoffTime
    );

    const filteredMetrics = this.metrics.filter(
      metric => metric.workflowId === workflowId && metric.timestamp >= cutoffTime
    );

    const milestones = filteredSnapshots
      .flatMap(snapshot => snapshot.milestones)
      .filter((milestone, index, self) => 
        self.findIndex(m => m.name === milestone.name) === index
      );

    return {
      snapshots: filteredSnapshots,
      metrics: filteredMetrics,
      milestones
    };
  }

  /**
   * Subscribe to real-time updates
   */
  subscribe(
    subscriberId: string,
    callback: (update: RealTimeUpdate) => void,
    filter?: {
      types?: string[];
      sources?: string[];
      priority?: string[];
    }
  ): void {
    this.subscribers.set(subscriberId, (update) => {
      // Apply filters if provided
      if (filter) {
        if (filter.types && !filter.types.includes(update.type)) return;
        if (filter.sources && !filter.sources.includes(update.source)) return;
        if (filter.priority && !filter.priority.includes(update.priority)) return;
      }

      callback(update);
    });

    console.log(`🔔 SUBSCRIPTION: ${subscriberId} subscribed to real-time updates`);
  }

  /**
   * Unsubscribe from real-time updates
   */
  unsubscribe(subscriberId: string): void {
    this.subscribers.delete(subscriberId);
    console.log(`🔕 UNSUBSCRIBED: ${subscriberId} removed from updates`);
  }

  /**
   * Broadcast update to all subscribers
   */
  private broadcastUpdate(update: RealTimeUpdate): void {
    this.realTimeUpdates.push(update);

    // Keep only last 1000 updates
    if (this.realTimeUpdates.length > 1000) {
      this.realTimeUpdates = this.realTimeUpdates.slice(-1000);
    }

    // Notify all subscribers
    this.subscribers.forEach(callback => {
      try {
        callback(update);
      } catch (error) {
        console.error('Error in subscriber callback:', error);
      }
    });
  }

  /**
   * Capture current workflow progress
   */
  private captureWorkflowProgress(): Record<string, any> {
    const enhancementProgress = taskDependencyMapping.getWorkflowProgress('enhancement_implementation');

    return {
      enhancement_implementation: enhancementProgress,
      summary: {
        totalWorkflows: 1,
        activeWorkflows: enhancementProgress.progressPercentage < 100 ? 1 : 0,
        completedWorkflows: enhancementProgress.progressPercentage === 100 ? 1 : 0
      }
    };
  }

  /**
   * Capture current agent status
   */
  private captureAgentStatus(): Record<string, any> {
    const systemStatus = taskDependencyMapping.getSystemStatus();

    const agentStatus: Record<string, any> = {};

    Object.entries(systemStatus.agentUtilization).forEach(([agentId, taskCount]) => {
      const agentTasks = taskDependencyMapping.getAgentTasks(agentId);
      const nextTask = taskDependencyMapping.getNextTask(agentId);

      agentStatus[agentId] = {
        activeTasks: taskCount,
        totalAssignedTasks: agentTasks.length,
        completedTasks: agentTasks.filter(t => t.status === 'completed').length,
        nextTask: nextTask ? {
          id: nextTask.id,
          name: nextTask.name,
          priority: nextTask.priority,
          estimatedDuration: nextTask.estimatedDuration
        } : null,
        status: taskCount > 0 ? 'active' : 'idle',
        lastActivity: new Date()
      };
    });

    return agentStatus;
  }

  /**
   * Capture system performance metrics
   */
  private captureSystemMetrics(): Record<string, any> {
    const systemStatus = taskDependencyMapping.getSystemStatus();
    // const checkpointStatus = checkpointSystem.getSystemStatus(); // Temporarily disabled for integration

    return {
      tasks: systemStatus.tasksByStatus,
      performance: {
        averageTaskDuration: systemStatus.averageTaskDuration,
        totalTasks: systemStatus.totalTasks,
        activeWorkflows: systemStatus.activeWorkflows
      },
      checkpoints: {
        total: 0, // checkpointStatus disabled for integration
        milestones: 0,
        isMonitoring: false,
        lastCheckpoint: null
      },
      memory: {
        metricsCount: this.metrics.length,
        snapshotsCount: this.snapshots.length,
        subscribersCount: this.subscribers.size
      }
    };
  }

  /**
   * Capture milestone information
   */
  private captureMilestones(): Array<{
    name: string;
    completedAt: Date;
    duration: number;
  }> {
    // const checkpoints = checkpointSystem.getCheckpointsByType('milestone'); // Disabled
    const checkpoints: any[] = []; // Temporary for integration

    return checkpoints.map(checkpoint => ({
      name: checkpoint.name,
      completedAt: checkpoint.timestamp,
      duration: checkpoint.metadata.estimatedDuration || 0
    }));
  }

  /**
   * Calculate performance metrics
   */
  private calculatePerformanceMetrics(): Record<string, any> {
    const recentMetrics = this.metrics.filter(
      metric => metric.timestamp >= new Date(Date.now() - 60 * 60 * 1000) // Last hour
    );

    const taskCompletionMetrics = recentMetrics.filter(m => m.metric === 'task_completed');
    const tasksPerHour = taskCompletionMetrics.length;

    const durationMetrics = recentMetrics.filter(m => m.metric === 'task_duration');
    const averageDuration = durationMetrics.length > 0
      ? durationMetrics.reduce((sum, m) => sum + m.value, 0) / durationMetrics.length
      : 0;

    return {
      tasksPerHour,
      averageTaskDuration: Math.round(averageDuration),
      systemEfficiency: this.calculateEfficiency(),
      uptime: this.calculateUptime(),
      errorRate: this.calculateErrorRate()
    };
  }

  /**
   * Calculate agent activity metrics
   */
  private calculateAgentActivity(): Record<string, any> {
    const systemStatus = taskDependencyMapping.getSystemStatus();

    const totalTasks = Object.values(systemStatus.agentUtilization).reduce((sum, count) => sum + count, 0);
    const activeAgents = Object.values(systemStatus.agentUtilization).filter(count => count > 0).length;

    return {
      totalActiveAgents: activeAgents,
      totalActiveTasks: totalTasks,
      agentEfficiency: Object.fromEntries(
        Object.entries(systemStatus.agentUtilization).map(([agent, tasks]) => [
          agent,
          tasks > 0 ? 'active' : 'idle'
        ])
      ),
      collaborationIndex: this.calculateCollaborationIndex()
    };
  }

  /**
   * Calculate progress trends
   */
  private calculateTrends(): Record<string, any> {
    if (this.snapshots.length < 2) {
      return {
        velocityTrend: 'stable',
        progressVelocity: 0,
        estimatedCompletion: null
      };
    }

    const recent = this.snapshots.slice(-10); // Last 10 snapshots
    const progressPoints = recent.map(snapshot => {
      const enhancementProgress = snapshot.workflowProgress.enhancement_implementation;
      return enhancementProgress ? enhancementProgress.progressPercentage : 0;
    });

    const velocity = this.calculateVelocity(progressPoints);
    const trend = velocity > 1 ? 'accelerating' : velocity < -1 ? 'decelerating' : 'stable';

    return {
      velocityTrend: trend,
      progressVelocity: Math.round(velocity * 100) / 100,
      estimatedCompletion: this.estimateCompletion(progressPoints, velocity),
      recentMilestones: recent.flatMap(s => s.milestones).slice(-5)
    };
  }

  /**
   * Calculate velocity between progress points
   */
  private calculateVelocity(progressPoints: number[]): number {
    if (progressPoints.length < 2) return 0;

    const differences = progressPoints.slice(1).map((point, index) => 
      point - progressPoints[index]
    );

    return differences.reduce((sum, diff) => sum + diff, 0) / differences.length;
  }

  /**
   * Estimate completion time based on velocity
   */
  private estimateCompletion(progressPoints: number[], velocity: number): Date | null {
    if (velocity <= 0) return null;

    const currentProgress = progressPoints[progressPoints.length - 1];
    const remainingProgress = 100 - currentProgress;

    if (remainingProgress <= 0) return new Date();

    const snapshotInterval = 5; // 5 minutes between snapshots
    const estimatedSnapshots = remainingProgress / velocity;
    const estimatedMinutes = estimatedSnapshots * snapshotInterval;

    return new Date(Date.now() + estimatedMinutes * 60 * 1000);
  }

  /**
   * Calculate system efficiency
   */
  private calculateEfficiency(): number {
    const systemStatus = taskDependencyMapping.getSystemStatus();
    const totalTasks = systemStatus.totalTasks;
    const completedTasks = systemStatus.tasksByStatus.completed;
    const failedTasks = systemStatus.tasksByStatus.failed;

    if (totalTasks === 0) return 100;

    const efficiency = ((completedTasks - failedTasks) / totalTasks) * 100;
    return Math.max(0, Math.min(100, Math.round(efficiency)));
  }

  /**
   * Calculate system uptime
   */
  private calculateUptime(): number {
    // This would track actual system uptime
    // For now, return tracking uptime
    const trackingStart = this.snapshots[0]?.timestamp || new Date();
    const uptimeMs = Date.now() - trackingStart.getTime();
    return Math.round(uptimeMs / (1000 * 60 * 60)); // Hours
  }

  /**
   * Calculate error rate
   */
  private calculateErrorRate(): number {
    const recentUpdates = this.realTimeUpdates.filter(
      update => update.timestamp >= new Date(Date.now() - 60 * 60 * 1000)
    );

    const errorUpdates = recentUpdates.filter(update => update.type === 'error');

    if (recentUpdates.length === 0) return 0;

    return Math.round((errorUpdates.length / recentUpdates.length) * 100);
  }

  /**
   * Calculate collaboration index
   */
  private calculateCollaborationIndex(): number {
    const systemStatus = taskDependencyMapping.getSystemStatus();
    const activeAgents = Object.values(systemStatus.agentUtilization).filter(count => count > 0).length;
    const maxAgents = Object.keys(systemStatus.agentUtilization).length;

    if (maxAgents === 0) return 0;

    return Math.round((activeAgents / maxAgents) * 100);
  }

  /**
   * Clean up old data to prevent memory bloat
   */
  private cleanupOldData(): void {
    const cutoffTime = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000); // 7 days

    // Clean old metrics
    this.metrics = this.metrics.filter(metric => metric.timestamp >= cutoffTime);

    // Clean old updates
    this.realTimeUpdates = this.realTimeUpdates.filter(update => update.timestamp >= cutoffTime);

    console.log('🧹 DATA CLEANUP: Removed old tracking data');
  }

  /**
   * Get system health summary
   */
  getHealthSummary(): {
    status: 'healthy' | 'warning' | 'critical';
    issues: string[];
    recommendations: string[];
    metrics: Record<string, any>;
  } {
    const performanceMetrics = this.calculatePerformanceMetrics();
    const agentActivity = this.calculateAgentActivity();

    const issues: string[] = [];
    const recommendations: string[] = [];
    let status: 'healthy' | 'warning' | 'critical' = 'healthy';

    // Check for issues
    if (performanceMetrics.errorRate > 10) {
      issues.push('High error rate detected');
      status = 'warning';
    }

    if (agentActivity.totalActiveAgents === 0) {
      issues.push('No agents currently active');
      recommendations.push('Check agent system connectivity');
      status = 'warning';
    }

    if (performanceMetrics.systemEfficiency < 50) {
      issues.push('Low system efficiency');
      recommendations.push('Review task allocation and dependencies');
      status = 'critical';
    }

    return {
      status,
      issues,
      recommendations,
      metrics: {
        ...performanceMetrics,
        ...agentActivity
      }
    };
  }
}

export const progressTracking = new ProgressTrackingService();

/**
 * CONSOLIDATED MEMORY SERVICE - OLGA'S PLAN IMPLEMENTATION
 * Single memory service with database persistence and 12-hour cache
 * Replaces all competing memory systems with unified approach
 */

import { storage } from '../storage';

interface AgentMemoryOptions {
  agentName: string;
  userId: string;
  task?: string;
  isAdminBypass?: boolean;
}

interface AgentContext {
  agentName: string;
  userId: string;
  currentTask: string;
  adminPrivileges: boolean;
  memories: any[];
  timestamp: Date;
}

/**
 * Single memory service that replaces all competing systems
 * Focuses on essential functionality only
 */
export class SimpleMemoryService {
  private static instance: SimpleMemoryService;
  private contextCache = new Map<string, AgentContext>();

  private constructor() {}

  public static getInstance(): SimpleMemoryService {
    if (!SimpleMemoryService.instance) {
      SimpleMemoryService.instance = new SimpleMemoryService();
    }
    return SimpleMemoryService.instance;
  }

  /**
   * OLGA'S FIX: Enhanced context preparation with database memory loading
   * Restores persisted memories and eliminates memory loss between sessions
   */
  async prepareAgentContext(options: AgentMemoryOptions): Promise<AgentContext> {
    const { agentName, userId, task = '', isAdminBypass = false } = options;
    const cacheKey = `${agentName}-${userId}`;

    // Check cache first (fast path)
    const cached = this.contextCache.get(cacheKey);
    if (cached && this.isCacheValid(cached)) {
      console.log(`🧠 MEMORY: Using cached context for ${agentName} (${cached.memories.length} memories)`);
      return cached;
    }

    // OLGA'S FIX: Load persisted memories from database
    let persistedMemories = [];
    try {
      const persistedData = await storage.getAgentMemory(agentName, userId);
      if (persistedData && persistedData.context && persistedData.context.memories) {
        persistedMemories = persistedData.context.memories;
        console.log(`💾 LOADED: ${persistedMemories.length} persisted memories for ${agentName}`);
      }
    } catch (error) {
      console.error(`⚠️ Failed to load persisted memories for ${agentName}:`, error);
    }

    // Build context with restored memories
    const context: AgentContext = {
      agentName,
      userId,
      currentTask: task,
      adminPrivileges: isAdminBypass,
      memories: persistedMemories, // OLGA'S FIX: Start with persisted memories
      timestamp: new Date()
    };

    // Cache for reuse (single cache, no conflicts)
    this.contextCache.set(cacheKey, context);
    console.log(`🧠 MEMORY: Prepared context for ${agentName}${isAdminBypass ? ' [ADMIN]' : ''} (${persistedMemories.length} restored)`);

    return context;
  }

  /**
   * OLGA'S FIX: Save agent memory with database persistence
   * Replaces in-memory only storage with reliable database backup
   */
  async saveAgentMemory(context: AgentContext, data: any): Promise<void> {
    const cacheKey = `${context.agentName}-${context.userId}`;

    // Update context with new data
    const memoryItem = {
      data,
      timestamp: new Date(),
      task: context.currentTask
    };

    // Ensure memories array exists before pushing
    if (!context.memories) {
      context.memories = [];
    }
    context.memories.push(memoryItem);

    // Update cache (keep for speed)
    this.contextCache.set(cacheKey, context);

    // OLGA'S FIX: Enhanced database persistence
    try {
      await storage.saveAgentMemory(context.agentName, context.userId, { context });
      console.log(`💾 SAVED: Memory persisted for ${context.agentName}`);
    } catch (error) {
      console.error(`⚠️ Failed to persist memory for ${context.agentName}:`, error);
    }
  }

  /**
   * ZARA'S TOKEN OPTIMIZATION: MINIMAL bypass for exact JSON tool calls only
   */
  shouldBypassClaude(message: string, agentId: string): boolean {
    // ULTRA STRICT: Only bypass exact JSON tool call format
    const isExactJSONTool = message.trim().startsWith('{') && message.trim().endsWith('}') && 
                           (message.includes('"command":') || message.includes('"query_description":') || message.includes('"sql_query":'));

    return isExactJSONTool;
  }

  /**
   * ZARA'S OPTIMIZATION: Get workspace context locally (no Claude API)
   */
  /**
   * FULL LOCAL MEMORY SYSTEM: Get complete conversation context locally
   * Returns formatted conversation history without Claude API calls
   */
  async getFullConversationContext(agentName: string, userId: string): Promise<Array<{role: string, content: string}>> {
    try {
      const context = await this.prepareAgentContext({ agentName, userId, isAdminBypass: true });

      // LOAD FULL CONVERSATION FROM STORAGE (not just memories)
      const storedData = await storage.getAgentMemory(agentName, userId);
      if (storedData && storedData.conversationHistory) {
        console.log(`🧠 LOCAL FULL CONTEXT: Loaded ${storedData.conversationHistory.length} messages for ${agentName}`);
        return storedData.conversationHistory;
      }

      // Fallback: Load from database if needed
      const { db } = await import('../db.js');
      const { claudeMessages } = await import('../../shared/schema.js');
      const { eq, desc } = await import('drizzle-orm');

      const conversationId = `admin_${agentName.toLowerCase()}_${userId}`;
      const messages = await db
        .select()
        .from(claudeMessages)
        .where(eq(claudeMessages.conversationId, conversationId))
        .orderBy(claudeMessages.createdAt)
        .limit(100);

      const formattedMessages = messages.map(msg => ({
        role: msg.role === 'agent' ? 'assistant' : msg.role,
        content: msg.content
      }));

      console.log(`🧠 LOCAL FALLBACK: Loaded ${formattedMessages.length} messages from database for ${agentName}`);
      return formattedMessages;

    } catch (error) {
      console.error(`Failed to get full context for ${agentName}:`, error);
      return [];
    }
  }

  async getWorkspaceContext(agentName: string, userId: string): Promise<string> {
    try {
      const context = await this.prepareAgentContext({ agentName, userId, isAdminBypass: true });

      if (context.memories.length > 0) {
        const recentMemories = context.memories.slice(-3)
          .map(mem => `- ${mem.data?.pattern || mem.data?.currentTask || 'Previous task'}`)
          .join('\n');
        return `Recent workspace context for ${agentName}:\n${recentMemories}`;
      }

      return `Agent ${agentName} workspace ready for new tasks`;
    } catch (error) {
      console.error(`Failed to get workspace context for ${agentName}:`, error);
      return `Agent ${agentName} workspace context unavailable`;
    }
  }

  /**
   * UNRESTRICTED: Keep ALL memories - no consolidation limits since local processing is free
   */
  async consolidateMemory(agentId: string, userId: string): Promise<void> {
    const context = await this.prepareAgentContext({
      agentName: agentId,
      userId
    });

    // FULL RETENTION: Keep ALL memories without time limits or duplicate removal
    // Only remove exact duplicates (same timestamp + same data)
    const uniqueMemories = context.memories.filter((memory, index, self) => 
      index === self.findIndex(m => 
        m.timestamp.getTime() === memory.timestamp.getTime() &&
        JSON.stringify(m.data) === JSON.stringify(memory.data)
      )
    );

    context.memories = uniqueMemories;

    // Save all memories without restrictions
    await storage.saveAgentMemory(agentId, userId, { context });
    console.log(`🧠 UNLIMITED MEMORY: All ${context.memories.length} memories preserved for ${agentId}`);
  }

  /**
   * ESSENTIAL: Clear memory when needed
   * Replaces complex cache invalidation from multiple systems
   */
  /**
   * OLGA'S FIX: Gentle memory refresh instead of aggressive clearing
   * Only clears when absolutely necessary to prevent context loss
   */
  refreshAgentMemory(agentName: string, userId: string, preserveContext: boolean = true): void {
    const cacheKey = `${agentName}-${userId}`;

    if (preserveContext) {
      // SOFT REFRESH: Keep the context but mark as refreshed
      const existing = this.contextCache.get(cacheKey);
      if (existing) {
        existing.timestamp = new Date();
        console.log(`🔄 MEMORY: Refreshed timestamp for ${agentName} (context preserved)`);
        return;
      }
    }

    // HARD CLEAR: Only when explicitly requested
    this.contextCache.delete(cacheKey);
    console.log(`⚠️ MEMORY: Hard cleared memory for ${agentName} (context lost)`);
  }

  /**
   * UNRESTRICTED: Extended cache duration for unlimited memory retention
   * Since local processing is free, keep context as long as needed
   */
  private isCacheValid(context: AgentContext): boolean {
    const now = new Date();
    const age = now.getTime() - context.timestamp.getTime();
    const maxAge = 7 * 24 * 60 * 60 * 1000; // 7 days cache - agents remember everything
    return age < maxAge;
  }

  /**
   * COMPATIBILITY: Methods to replace the old complex systems
   */

  // Replaces ContextPreservationSystem.prepareAgentWorkspace
  async prepareAgentWorkspace(agentName: string, userId: string, task: string, isAdminBypass: boolean = false) {
    return this.prepareAgentContext({ agentName, userId, task, isAdminBypass });
  }

  // Replaces AdvancedMemorySystem.getAgentMemoryProfile  
  async getAgentMemoryProfile(agentName: string, userId: string, adminBypass: boolean = false) {
    const context = await this.prepareAgentContext({ agentName, userId, isAdminBypass: adminBypass });
    // FIXED: Return actual context data instead of empty profile
    return {
      agentName,
      userId,
      memoryStrength: 1.0,
      learningPatterns: context.memories.slice(-5), // Include recent memories
      intelligenceLevel: adminBypass ? 10 : 7,
      adminBypass,
      context: context, // CRITICAL: Include actual context for use
      memoryCount: context.memories.length,
      lastOptimization: new Date() // Fix for ConversationManager compatibility
    };
  }

  // UNRESTRICTED: All messages get full context since local processing is free
  analyzeMessage(message: string) {
    // UNLIMITED ACCESS: Every interaction gets full context and memory
    return {
      isContinuation: true,
      isWorkTask: true, // Always treat as work task
      contextLevel: 'full' // Always full context
    };
  }

  /**
   * ZARA'S WORKFLOW STATE TRACKING: Fix admin agent context loss between coordination calls
   */
  private workflowStates = new Map<string, any>();

  async saveWorkflowState(workflowId: string, state: any): Promise<void> {
    this.workflowStates.set(workflowId, {
      ...state,
      lastUpdateTime: new Date()
    });
    console.log(`💾 WORKFLOW: Saved state for workflow ${workflowId}`);
  }

  async getWorkflowState(workflowId: string): Promise<any> {
    const state = this.workflowStates.get(workflowId);
    if (!state) {
      console.log(`❌ WORKFLOW: No state found for workflow ${workflowId}`);
      return null;
    }
    console.log(`📖 WORKFLOW: Retrieved state for workflow ${workflowId}`);
    return state;
  }

  clearWorkflowState(workflowId: string): void {
    this.workflowStates.delete(workflowId);
    console.log(`🗑️ WORKFLOW: Cleared state for workflow ${workflowId}`);
  }
}

