          {
            type: 'section',
            text: {
              type: 'mrkdwn',
              text: `*Request Type:* ${requestType}\n\n*Context:* ${context}\n\n*Action Required:* Immediate attention needed`
            }
          },
          {
            type: 'actions',
            elements: [
              {
                type: 'button',
                text: {
                  type: 'plain_text',
                  text: `Respond to ${agentName}`
                },
                url: `https://sselfie.ai/admin-consulting-agents?agent=${agentName.toLowerCase()}`,
                style: 'danger'
              }
