  private calculateStyleConfidence(styles: string[]): Record<string, number> {
    return styles.reduce((acc, style, index) => {
      acc[style] = Math.round(85 - (index * 5)); // Decreasing confidence
      return acc;
    }, {} as Record<string, number>);
  }

