            console.log(`🎯 STRATEGIC COMPLETION: User ${userId} training complete with brand strategy context available`);
          } else {
            console.log(`📸 STANDARD COMPLETION: User ${userId} completed training without brand strategy coaching`);
          }
        } catch (strategyError) {
          console.error(`⚠️ STRATEGIC CONCEPTS: Failed to process for user ${userId}:`, strategyError);
          // Don't fail training completion if strategic concepts fail
        }

        console.log(`🎉 Database updated! User ${userId} training completed`);
        return true;
      }

      return false;

    } catch (error) {
      console.error(`❌ Error checking model ${modelName}:`, error);
      return false;
    }
  }

  /**
   * Check all in-progress trainings - Enhanced version that works without training ID
   */
  static async checkAllInProgressTrainings(): Promise<void> {
    try {
      console.log('🔍 TRAINING COMPLETION MONITOR: Checking all in-progress trainings...');

      // Get all users with training status that isn't completed
      const inProgressModels = await storage.getAllInProgressTrainings();

      if (inProgressModels.length === 0) {
        console.log('✅ No in-progress trainings found');
        return;
      }

      console.log(`📊 Found ${inProgressModels.length} in-progress trainings to check`);

      for (const userModel of inProgressModels) {
        const timeSinceStart = Date.now() - new Date(userModel.createdAt || new Date()).getTime();
        const minutesSinceStart = timeSinceStart / (1000 * 60);

        console.log(`⏱️ User ${userModel.userId}: ${Math.round(minutesSinceStart)} minutes since training started`);

        // Only check models that have been training for at least 8 minutes (training typically takes 10+ minutes)
        if (minutesSinceStart >= 8) {
          let updated = false;

          // Method 1: Check by training ID if available
          if (userModel.replicateModelId && userModel.replicateModelId.startsWith('rdt_')) {
            console.log(`🔍 Checking by training ID: ${userModel.replicateModelId}`);
            updated = await this.checkAndUpdateTraining(userModel.replicateModelId, userModel.userId);
          }

          // Method 2: Check by model name pattern (fallback for models without stored training ID)
          if (!updated && userModel.modelName) {
            console.log(`🔍 Checking by model name: ${userModel.modelName}`);
            updated = await this.checkModelByName(userModel.userId, userModel.modelName);
          }

          // Wait 1 second between API calls to avoid rate limiting
          await new Promise(resolve => setTimeout(resolve, 1000));
        } else {
          console.log(`⏳ User ${userModel.userId}: Training too recent, waiting...`);
        }
      }

    } catch (error) {
      console.error('❌ Error in training completion monitor:', error);
    }
  }

  /**
   * Start automatic monitoring (every 2 minutes)
   */
  startMonitoring(): void {
    console.log('🚀 Starting Training Completion Monitor (checks every 2 minutes)');

    // Check immediately on start
    TrainingCompletionMonitor.checkAllInProgressTrainings();

    // Then check every 2 minutes
    this.intervalId = setInterval(() => {
      TrainingCompletionMonitor.checkAllInProgressTrainings();
    }, 2 * 60 * 1000); // 2 minutes
  }

  /**
   * Stop monitoring
   */
  stopMonitoring(): void {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
      console.log('⏹️ Training Completion Monitor stopped');
    }
  }
}

import { storage } from './storage';

// Plan configuration with usage limits and costs - LUXURY AI PERSONAL BRANDING PLATFORM
export const PLAN_LIMITS = {
  'admin': {
    totalGenerations: null,
    monthlyGenerations: 999999, // Unlimited for admin
    cost: 0,
    description: 'Unlimited admin access',
    resetMonthly: false
  },
  'sselfie-studio': {
    totalGenerations: null,
    monthlyGenerations: 100, // €47/month for 100 AI images
    cost: 47,
    description: '100 AI generations per month + Maya AI personal brand strategist',
    resetMonthly: true
  }
} as const;

// API costs tracking
export const API_COSTS = {
  'replicate_ai': 0.038, // Per generation (4 images)
  'claude_api': 0.015,   // Per conversation
  'openai_api': 0.020    // Per conversation
} as const;

export interface UsageCheck {
  canGenerate: boolean;
  remainingGenerations: number;
  totalUsed: number;
  totalAllowed: number;
  monthlyUsed?: number;
  monthlyAllowed?: number;
  resetDate?: Date;
  reason?: string;
}

export interface UsageUpdate {
  actionType: 'generation' | 'api_call' | 'sandra_chat' | 'training';
  resourceUsed: 'replicate_ai' | 'claude_api' | 'openai_api';
  cost: number;
  details?: any;
  generatedImageId?: number;
}

export class UsageService {

  // Initialize usage tracking for new user
  static async initializeUserUsage(userId: string, plan: string): Promise<UserUsage> {
    const planLimits = PLAN_LIMITS[plan as keyof typeof PLAN_LIMITS];
    if (!planLimits) {
      throw new Error(`Invalid plan: ${plan}`);
    }

    const now = new Date();
    const periodEnd = planLimits.resetMonthly 
      ? new Date(now.getFullYear(), now.getMonth() + 1, now.getDate())
      : null;

    return await storage.createUserUsage({
      userId,
      plan,
      monthlyGenerationsAllowed: planLimits.monthlyGenerations,
      monthlyGenerationsUsed: 0,
      totalCostIncurred: "0.0000",
      currentPeriodStart: now,
      currentPeriodEnd: periodEnd,
      isLimitReached: false,
      lastGenerationAt: null
    });
  }

  // Check if user can generate images
  static async checkUsageLimit(userId: string): Promise<UsageCheck> {
    // CRITICAL: Check if user is admin first
    const user = await storage.getUser(userId);
    const adminEmails = ['ssa@ssasocial.com', 'sandrajonna@gmail.com', 'sandra@sselfie.ai'];

    // Admin users get unlimited access
    if (user && (adminEmails.includes(user.email) || user.role === 'admin')) {
      console.log(`👑 Admin user detected: ${user.email} - granting unlimited access`);
      return {
        canGenerate: true,
        remainingGenerations: 999999,
        totalUsed: 0,
        totalAllowed: 999999,
        reason: 'Admin: Unlimited access'
      };
    }

    let usage = await storage.getUserUsage(userId);

    // Auto-initialize usage for new users with sselfie-studio plan
    if (!usage) {
      await this.initializeUserUsage(userId, 'sselfie-studio');
      usage = await storage.getUserUsage(userId);
      if (!usage) {
        throw new Error('Failed to initialize user usage');
      }
    }

    const planLimits = PLAN_LIMITS[usage.plan as keyof typeof PLAN_LIMITS];
    const now = new Date();

    // Check if monthly limits need to be reset
    if (planLimits.resetMonthly && usage.currentPeriodEnd && now > usage.currentPeriodEnd) {
      await this.resetMonthlyUsage(userId);
      // Refresh usage data after reset
      const refreshedUsage = await storage.getUserUsage(userId);
      if (refreshedUsage) {
        Object.assign(usage, refreshedUsage);
      }
    }

    // Legacy ai-pack plans are migrated to sselfie-studio
    if (usage.plan === 'ai-pack') {
      console.log(`Migrating legacy ai-pack user ${userId} to sselfie-studio plan`);
      await this.initializeUserUsage(userId, 'sselfie-studio');
      usage = await storage.getUserUsage(userId);
    }

    // For Studio plans (monthly limits)
    if (usage.monthlyGenerationsAllowed) {
      const monthlyRemaining = usage.monthlyGenerationsAllowed - (usage.monthlyGenerationsUsed || 0);
      return {
        canGenerate: monthlyRemaining > 0,
        remainingGenerations: monthlyRemaining,
        totalUsed: usage.totalGenerationsUsed,
        totalAllowed: usage.totalGenerationsAllowed || 999999,
        monthlyUsed: usage.monthlyGenerationsUsed || 0,
        monthlyAllowed: usage.monthlyGenerationsAllowed,
        resetDate: usage.currentPeriodEnd || undefined,
        reason: monthlyRemaining <= 0 ? 'Monthly limit reached. Resets next period.' : undefined
      };
    }

    return {
      canGenerate: false,
      remainingGenerations: 0,
      totalUsed: usage.totalGenerationsUsed,
      totalAllowed: 0,
      reason: 'Invalid plan configuration'
    };
  }

  // Record usage when user generates images
  static async recordUsage(userId: string, update: UsageUpdate): Promise<void> {
    const usage = await storage.getUserUsage(userId);
    if (!usage) {
      throw new Error('User usage not found');
    }

    // Record in usage history (skip if table doesn't exist)
    try {
      await storage.createUsageHistory({
        userId,
        actionType: update.actionType,
        resourceUsed: update.resourceUsed,
        cost: update.cost.toString(),
        details: update.details,
        generatedImageId: update.generatedImageId
      });
    } catch (error) {
      console.log('Usage history recording skipped (table may not exist):', error.message);
    }

    // Update usage counters
    const updates: any = {
      totalCostIncurred: (parseFloat(usage.totalCostIncurred) + update.cost).toFixed(4),
      lastGenerationAt: new Date()
    };

    // Only count 'generation' actions against limits, NOT 'training'
    if (update.actionType === 'generation') {
      updates.totalGenerationsUsed = usage.totalGenerationsUsed + 1;

      if (usage.monthlyGenerationsAllowed) {
        updates.monthlyGenerationsUsed = (usage.monthlyGenerationsUsed || 0) + 1;
      }

      // Check if limit is reached
      const planLimits = PLAN_LIMITS[usage.plan as keyof typeof PLAN_LIMITS];
      // All plans use monthly limits in new single-tier model
      if (planLimits.resetMonthly) {
        updates.isLimitReached = updates.monthlyGenerationsUsed >= (usage.monthlyGenerationsAllowed || 0);
      }
    }
    // Training actions are tracked in history but don't count against generation limits

    await storage.updateUserUsage(userId, updates);
  }

  // Reset monthly usage for Studio plans
  static async resetMonthlyUsage(userId: string): Promise<void> {
    const now = new Date();
    const nextPeriodEnd = new Date(now.getFullYear(), now.getMonth() + 1, now.getDate());

    await storage.updateUserUsage(userId, {
      monthlyGenerationsUsed: 0,
      currentPeriodStart: now,
      currentPeriodEnd: nextPeriodEnd,
      isLimitReached: false
    });
  }

  // Get usage statistics for dashboard
  static async getUserStats(userId: string): Promise<any> {
    const usage = await storage.getUserUsage(userId);
    if (!usage) return null;

    const planLimits = PLAN_LIMITS[usage.plan as keyof typeof PLAN_LIMITS];
    const usageCheck = await this.checkUsageLimit(userId);

    // Get recent usage history
    const recentHistory = await storage.getUserUsageHistory(userId, 30); // Last 30 days

    return {
      plan: usage.plan,
      planLimits,
      usage: usageCheck,
      totalCostIncurred: parseFloat(usage.totalCostIncurred),
      lastGenerationAt: usage.lastGenerationAt,
      recentActivity: recentHistory,
      createdAt: usage.createdAt
    };
  }

  // Admin function to get user costs (for Sandra's admin dashboard)
  static async getUserCostAnalysis(userId: string): Promise<any> {
    const usage = await storage.getUserUsage(userId);
    const history = await storage.getUserUsageHistory(userId);

    if (!usage) return null;

    const totalCost = parseFloat(usage.totalCostIncurred);
    const planRevenue = PLAN_LIMITS[usage.plan as keyof typeof PLAN_LIMITS].cost;
    const profitMargin = planRevenue - totalCost;
    const profitPercentage = ((profitMargin / planRevenue) * 100).toFixed(1);

    return {
      userId,
      plan: usage.plan,
      totalGenerations: usage.totalGenerationsUsed,
      totalCost,
      planRevenue,
      profitMargin,
      profitPercentage: `${profitPercentage}%`,
      costBreakdown: this.analyzeCostBreakdown(history),
      isHealthy: profitMargin > 0
    };
  }

  // Analyze cost breakdown by resource type
  private static analyzeCostBreakdown(history: any[]): any {
    const breakdown = {
      replicate_ai: 0,
      claude_api: 0,
      openai_api: 0
    };

    history.forEach(record => {
      if (breakdown.hasOwnProperty(record.resourceUsed)) {
        breakdown[record.resourceUsed as keyof typeof breakdown] += parseFloat(record.cost);
      }
    });

    return breakdown;
  }

  // Check if user needs to upgrade (for upselling)
  static async checkUpgradeRecommendation(userId: string): Promise<any> {
    const usage = await storage.getUserUsage(userId);
    if (!usage) return null;

    const usageCheck = await this.checkUsageLimit(userId);

    // Single-tier model: Users on sselfie-studio plan who need optimization advice
    if (usage.plan === 'sselfie-studio' && usage.monthlyGenerationsUsed && usage.monthlyGenerationsUsed >= 90) {
      return {
        shouldUpgrade: false,
        reason: 'High usage detected',
        message: 'You\'re getting great value from your plan! Consider upgrading your photo selection strategy with Maya for even better results.'
      };
    }

    return { shouldUpgrade: false };
  }
}

/**
 * API Documentation System
 * Generates and maintains comprehensive API documentation
 */

import { Logger } from './logger';
import { Request, Response, NextFunction } from 'express';

export interface APIEndpoint {
  path: string;
  method: string;
  description: string;
  parameters: Array<{
    name: string;
    type: string;
    required: boolean;
    description: string;
    example?: any;
  }>;
  requestBody?: {
    type: string;
    description: string;
    schema: any;
    example?: any;
  };
  responses: Array<{
    statusCode: number;
    description: string;
    schema: any;
    example?: any;
  }>;
  authentication?: {
    type: string;
    required: boolean;
    description: string;
  };
  rateLimit?: {
    requests: number;
    window: string;
    description: string;
  };
  tags: string[];
  deprecated: boolean;
  version: string;
  lastUpdated: string;
}

export interface APIDocumentation {
  title: string;
  version: string;
  description: string;
  baseUrl: string;
  contact: {
    name: string;
    email: string;
    url: string;
  };
  license: {
    name: string;
    url: string;
  };
  servers: Array<{
    url: string;
    description: string;
  }>;
  endpoints: APIEndpoint[];
  schemas: Record<string, any>;
  examples: Record<string, any>;
  changelog: Array<{
    version: string;
    date: string;
    changes: string[];
  }>;
  lastGenerated: string;
}

export class APIDocumentationSystem {
  private logger: Logger;
  private endpoints: Map<string, APIEndpoint>;
  private schemas: Map<string, any>;
  private examples: Map<string, any>;
  private isEnabled: boolean;

  constructor() {
    this.logger = new Logger('APIDocumentationSystem');
    this.endpoints = new Map();
    this.schemas = new Map();
    this.examples = new Map();
    this.isEnabled = true;
  }

  /**
   * Register an API endpoint
   */
  public registerEndpoint(endpoint: APIEndpoint): void {
    if (!this.isEnabled) {
      return;
    }

    const key = `${endpoint.method.toUpperCase()}:${endpoint.path}`;
    this.endpoints.set(key, endpoint);
    this.logger.debug('API endpoint registered', { key, endpoint: endpoint.path });
  }

  /**
   * Register a schema
   */
  public registerSchema(name: string, schema: any): void {
    if (!this.isEnabled) {
      return;
    }

    this.schemas.set(name, schema);
    this.logger.debug('Schema registered', { name });
  }

  /**
   * Register an example
   */
  public registerExample(name: string, example: any): void {
    if (!this.isEnabled) {
      return;
    }

    this.examples.set(name, example);
    this.logger.debug('Example registered', { name });
  }

  /**
   * Generate comprehensive API documentation
   */
  public generateDocumentation(): APIDocumentation {
    const timestamp = new Date().toISOString();

    return {
      title: 'SSELFIE Brand Studio API',
      version: process.env.npm_package_version || '1.0.0',
      description: 'Comprehensive API for SSELFIE Brand Studio - AI-powered brand photography and content creation platform',
      baseUrl: process.env.API_BASE_URL || 'https://api.sselfie.com',
      contact: {
        name: 'SSELFIE Support',
        email: 'support@sselfie.com',
        url: 'https://sselfie.com/support',
      },
      license: {
        name: 'MIT',
        url: 'https://opensource.org/licenses/MIT',
      },
      servers: [
        {
          url: 'https://api.sselfie.com',
          description: 'Production server',
        },
        {
          url: 'https://staging-api.sselfie.com',
          description: 'Staging server',
        },
        {
          url: 'http://localhost:5000',
          description: 'Development server',
        },
      ],
      endpoints: Array.from(this.endpoints.values()),
      schemas: Object.fromEntries(this.schemas),
      examples: Object.fromEntries(this.examples),
      changelog: this.getChangelog(),
      lastGenerated: timestamp,
    };
  }

  /**
   * Get endpoint documentation
   */
  public getEndpointDocumentation(method: string, path: string): APIEndpoint | null {
    const key = `${method.toUpperCase()}:${path}`;
    return this.endpoints.get(key) || null;
  }

  /**
   * Get all endpoints by tag
   */
  public getEndpointsByTag(tag: string): APIEndpoint[] {
    return Array.from(this.endpoints.values()).filter(endpoint => 
      endpoint.tags.includes(tag)
    );
  }

  /**
   * Get all endpoints by method
   */
  public getEndpointsByMethod(method: string): APIEndpoint[] {
    return Array.from(this.endpoints.values()).filter(endpoint => 
      endpoint.method.toUpperCase() === method.toUpperCase()
    );
  }

  /**
   * Get all endpoints by version
   */
  public getEndpointsByVersion(version: string): APIEndpoint[] {
    return Array.from(this.endpoints.values()).filter(endpoint => 
      endpoint.version === version
    );
  }

  /**
   * Get deprecated endpoints
   */
  public getDeprecatedEndpoints(): APIEndpoint[] {
    return Array.from(this.endpoints.values()).filter(endpoint => 
      endpoint.deprecated
    );
  }

  /**
   * Generate OpenAPI specification
   */
  public generateOpenAPISpec(): any {
    const doc = this.generateDocumentation();

    return {
      openapi: '3.0.0',
      info: {
        title: doc.title,
        version: doc.version,
        description: doc.description,
        contact: doc.contact,
        license: doc.license,
      },
      servers: doc.servers,
      paths: this.generatePaths(),
      components: {
        schemas: doc.schemas,
        examples: doc.examples,
        securitySchemes: {
          bearerAuth: {
            type: 'http',
            scheme: 'bearer',
            bearerFormat: 'JWT',
          },
          apiKey: {
            type: 'apiKey',
            in: 'header',
            name: 'X-API-Key',
          },
        },
      },
      tags: this.generateTags(),
      externalDocs: {
        description: 'Find out more about SSELFIE',
        url: 'https://sselfie.com',
      },
    };
  }

  /**
   * Generate paths for OpenAPI spec
   */
  private generatePaths(): any {
    const paths: any = {};

    for (const endpoint of this.endpoints.values()) {
      if (!paths[endpoint.path]) {
        paths[endpoint.path] = {};
      }

      const operation: any = {
        summary: endpoint.description,
        description: endpoint.description,
        operationId: `${endpoint.method.toLowerCase()}_${endpoint.path.replace(/[^a-zA-Z0-9]/g, '_')}`,
        tags: endpoint.tags,
        parameters: endpoint.parameters.map(param => ({
          name: param.name,
          in: this.getParameterLocation(param.name, endpoint.path),
          required: param.required,
          description: param.description,
          schema: { type: param.type },
          example: param.example,
        })),
        responses: {},
        deprecated: endpoint.deprecated,
      };

      if (endpoint.requestBody) {
        operation.requestBody = {
          description: endpoint.requestBody.description,
          required: true,
          content: {
            'application/json': {
              schema: endpoint.requestBody.schema,
              example: endpoint.requestBody.example,
            },
          },
        };
      }

      if (endpoint.authentication) {
        operation.security = [{
          [endpoint.authentication.type]: []
        }];
      }

      if (endpoint.rateLimit) {
        operation['x-rate-limit'] = endpoint.rateLimit;
      }

      for (const response of endpoint.responses) {
        operation.responses[response.statusCode.toString()] = {
          description: response.description,
          content: {
            'application/json': {
              schema: response.schema,
              example: response.example,
            },
          },
        };
      }

      paths[endpoint.path][endpoint.method.toLowerCase()] = operation;
    }

    return paths;
  }

  /**
   * Generate tags for OpenAPI spec
   */
  private generateTags(): any[] {
    const tagSet = new Set<string>();

    for (const endpoint of this.endpoints.values()) {
      for (const tag of endpoint.tags) {
        tagSet.add(tag);
      }
    }

    return Array.from(tagSet).map(tag => ({
      name: tag,
      description: this.getTagDescription(tag),
    }));
  }

  /**
   * Get tag description
   */
  private getTagDescription(tag: string): string {
    const descriptions: Record<string, string> = {
      'auth': 'Authentication and user management endpoints',
      'ai': 'AI-powered content generation endpoints',
      'images': 'Image processing and generation endpoints',
      'videos': 'Video creation and processing endpoints',
      'brands': 'Brand management and customization endpoints',
      'admin': 'Administrative and management endpoints',
      'health': 'Health check and monitoring endpoints',
      'utility': 'Utility and helper endpoints',
    };

    return descriptions[tag] || `Endpoints related to ${tag}`;
  }

  /**
   * Get parameter location
   */
  private getParameterLocation(name: string, path: string): string {
    if (path.includes(`{${name}}`)) {
      return 'path';
    }
    return 'query';
  }

  /**
   * Get changelog
   */
  private getChangelog(): Array<{
    version: string;
    date: string;
    changes: string[];
  }> {
    return [
      {
        version: '1.0.0',
        date: '2024-12-15',
