  /**
   * Start health check monitoring
   */
  public startMonitoring(intervalMs: number = 30000): void {
    if (this.checkInterval) {
      this.logger.warn('Health check monitoring already started');
      return;
    }

    this.logger.info('Starting health check monitoring...');
    this.checkInterval = setInterval(() => {
      this.performHealthCheck();
    }, intervalMs);

    // Initial check
    this.performHealthCheck();
  }

  /**
   * Stop health check monitoring
   */
  public stopMonitoring(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
      this.logger.info('Health check monitoring stopped');
    }
  }

  /**
   * Perform comprehensive health check
   */
  public async performHealthCheck(): Promise<HealthCheckResult> {
    const startTime = Date.now();
    this.lastCheck = new Date();

    try {
      // Run all health checks in parallel
      const [
        databaseCheck,
        cacheCheck,
        externalApisCheck,
        storageCheck,
        memoryCheck,
        cpuCheck,
        diskCheck,
        networkCheck,
        securityCheck,
        performanceCheck,
      ] = await Promise.all([
        this.checkDatabase(),
        this.checkCache(),
        this.checkExternalApis(),
        this.checkStorage(),
        this.checkMemory(),
        this.checkCpu(),
        this.checkDisk(),
        this.checkNetwork(),
        this.checkSecurity(),
        this.checkPerformance(),
      ]);

      // Get system metrics
      const metrics = this.getSystemMetrics();

      // Get alerts
      const alerts = this.getAlerts();

      // Determine overall status
      const overallStatus = this.determineOverallStatus([
        databaseCheck,
        cacheCheck,
        externalApisCheck,
        storageCheck,
        memoryCheck,
        cpuCheck,
        diskCheck,
        networkCheck,
        securityCheck,
        performanceCheck,
      ]);

      const result: HealthCheckResult = {
        status: overallStatus,
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        version: process.env.npm_package_version || '1.0.0',
        environment: process.env.NODE_ENV || 'development',
        checks: {
          database: databaseCheck,
          cache: cacheCheck,
          external_apis: externalApisCheck,
          storage: storageCheck,
          memory: memoryCheck,
          cpu: cpuCheck,
          disk: diskCheck,
          network: networkCheck,
          security: securityCheck,
          performance: performanceCheck,
        },
        metrics,
        alerts,
      };

      // Log health check result
      const duration = Date.now() - startTime;
      this.logger.info('Health check completed', {
        status: overallStatus,
        duration,
        checks: Object.keys(result.checks).length,
        alerts: alerts.length,
      });

      return result;
    } catch (error) {
      this.logger.error('Health check failed', { error });

      // Return unhealthy status if health check itself fails
      return {
        status: 'unhealthy',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        version: process.env.npm_package_version || '1.0.0',
        environment: process.env.NODE_ENV || 'development',
