}

export class PerformanceMonitor {
  private logger: Logger;
  private metrics: PerformanceMetrics[];
  private maxMetrics: number;
  private isEnabled: boolean;

  constructor(maxMetrics: number = 10000) {
    this.logger = new Logger('PerformanceMonitor');
    this.metrics = [];
    this.maxMetrics = maxMetrics;
    this.isEnabled = true;
  }

  /**
   * Middleware to track request performance
   */
  public trackRequest() {
    return (req: Request, res: Response, next: NextFunction) => {
      if (!this.isEnabled) {
        return next();
      }

      const startTime = Date.now();
      const startMemory = process.memoryUsage();
      const startCpu = process.cpuUsage();

      // Override res.end to capture response time
      const originalEnd = res.end;
      res.end = function(chunk?: any, encoding?: any) {
        const endTime = Date.now();
        const endMemory = process.memoryUsage();
        const endCpu = process.cpuUsage();

        const responseTime = endTime - startTime;
        const memoryUsage = endMemory.heapUsed - startMemory.heapUsed;
        const cpuUsage = (endCpu.user + endCpu.system) / 1000000; // Convert to milliseconds

        // Record metrics
        const metric: PerformanceMetrics = {
          timestamp: new Date().toISOString(),
          endpoint: req.path,
          method: req.method,
          responseTime,
          statusCode: res.statusCode,
          memoryUsage,
          cpuUsage,
          userAgent: req.get('User-Agent'),
          ip: req.ip,
          userId: (req as any).user?.id,
        };

        // Add to metrics (with size limit)
        if (this.metrics.length >= this.maxMetrics) {
          this.metrics.shift(); // Remove oldest metric
        }
        this.metrics.push(metric);

        // Log slow requests
        if (responseTime > 5000) {
          this.logger.warn('Slow request detected', {
            endpoint: req.path,
            method: req.method,
            responseTime,
            statusCode: res.statusCode,
          });
        }

        // Call original end method
        originalEnd.call(this, chunk, encoding);
      };

      next();
    };
  }

  /**
   * Get performance statistics
   */
  public getPerformanceStats(timeWindow?: number): PerformanceStats {
    const now = Date.now();
    const windowMs = timeWindow ? timeWindow * 60 * 1000 : 24 * 60 * 60 * 1000; // Default 24 hours
    const cutoffTime = now - windowMs;

    // Filter metrics within time window
    const recentMetrics = this.metrics.filter(
      metric => new Date(metric.timestamp).getTime() > cutoffTime
    );

    if (recentMetrics.length === 0) {
      return {
        totalRequests: 0,
        averageResponseTime: 0,
        p95ResponseTime: 0,
        p99ResponseTime: 0,
        errorRate: 0,
        throughput: 0,
        slowestEndpoints: [],
        errorEndpoints: [],
      };
    }

    // Calculate basic stats
    const totalRequests = recentMetrics.length;
    const responseTimes = recentMetrics.map(m => m.responseTime).sort((a, b) => a - b);
    const averageResponseTime = responseTimes.reduce((sum, time) => sum + time, 0) / totalRequests;
    const p95ResponseTime = responseTimes[Math.floor(totalRequests * 0.95)];
    const p99ResponseTime = responseTimes[Math.floor(totalRequests * 0.99)];

    // Calculate error rate
    const errorCount = recentMetrics.filter(m => m.statusCode >= 400).length;
    const errorRate = (errorCount / totalRequests) * 100;

    // Calculate throughput (requests per minute)
    const timeWindowMinutes = windowMs / (60 * 1000);
    const throughput = totalRequests / timeWindowMinutes;

    // Find slowest endpoints
    const endpointStats = new Map<string, { totalTime: number; count: number }>();
    recentMetrics.forEach(metric => {
      const key = `${metric.method} ${metric.endpoint}`;
      const existing = endpointStats.get(key) || { totalTime: 0, count: 0 };
      endpointStats.set(key, {
        totalTime: existing.totalTime + metric.responseTime,
        count: existing.count + 1,
      });
    });

    const slowestEndpoints = Array.from(endpointStats.entries())
      .map(([key, stats]) => {
        const [method, endpoint] = key.split(' ', 2);
        return {
          endpoint,
          method,
          averageTime: stats.totalTime / stats.count,
          count: stats.count,
        };
      })
      .sort((a, b) => b.averageTime - a.averageTime)
      .slice(0, 10);

    // Find error endpoints
    const errorStats = new Map<string, { errorCount: number; totalCount: number }>();
    recentMetrics.forEach(metric => {
      const key = `${metric.method} ${metric.endpoint}`;
      const existing = errorStats.get(key) || { errorCount: 0, totalCount: 0 };
      errorStats.set(key, {
        errorCount: existing.errorCount + (metric.statusCode >= 400 ? 1 : 0),
        totalCount: existing.totalCount + 1,
      });
    });

    const errorEndpoints = Array.from(errorStats.entries())
      .filter(([_, stats]) => stats.errorCount > 0)
      .map(([key, stats]) => {
        const [method, endpoint] = key.split(' ', 2);
        return {
          endpoint,
          method,
          errorCount: stats.errorCount,
          errorRate: (stats.errorCount / stats.totalCount) * 100,
        };
      })
      .sort((a, b) => b.errorRate - a.errorRate)
      .slice(0, 10);

    return {
      totalRequests,
      averageResponseTime: Math.round(averageResponseTime),
      p95ResponseTime,
      p99ResponseTime,
      errorRate: Math.round(errorRate * 100) / 100,
      throughput: Math.round(throughput * 100) / 100,
      slowestEndpoints,
      errorEndpoints,
    };
  }

  /**
   * Get metrics for specific endpoint
   */
  public getEndpointMetrics(endpoint: string, method?: string): PerformanceMetrics[] {
    return this.metrics.filter(metric => {
      if (method) {
        return metric.endpoint === endpoint && metric.method === method;
      }
      return metric.endpoint === endpoint;
    });
  }

  /**
   * Get metrics within time range
   */
  public getMetricsInRange(startTime: Date, endTime: Date): PerformanceMetrics[] {
    return this.metrics.filter(metric => {
      const metricTime = new Date(metric.timestamp);
      return metricTime >= startTime && metricTime <= endTime;
    });
  }

  /**
   * Get real-time performance summary
   */
  public getRealTimeSummary(): {
    requestsPerMinute: number;
    averageResponseTime: number;
    errorRate: number;
    activeUsers: number;
    memoryUsage: number;
    cpuUsage: number;
  } {
    const now = Date.now();
    const oneMinuteAgo = now - 60 * 1000;

    // Get metrics from last minute
    const recentMetrics = this.metrics.filter(
      metric => new Date(metric.timestamp).getTime() > oneMinuteAgo
    );

    const requestsPerMinute = recentMetrics.length;
    const averageResponseTime = recentMetrics.length > 0
      ? recentMetrics.reduce((sum, m) => sum + m.responseTime, 0) / recentMetrics.length
      : 0;
    const errorRate = recentMetrics.length > 0
      ? (recentMetrics.filter(m => m.statusCode >= 400).length / recentMetrics.length) * 100
      : 0;
    const activeUsers = new Set(recentMetrics.map(m => m.userId).filter(Boolean)).size;
    const memoryUsage = recentMetrics.length > 0
      ? recentMetrics.reduce((sum, m) => sum + m.memoryUsage, 0) / recentMetrics.length
      : 0;
    const cpuUsage = recentMetrics.length > 0
      ? recentMetrics.reduce((sum, m) => sum + m.cpuUsage, 0) / recentMetrics.length
      : 0;

    return {
      requestsPerMinute,
      averageResponseTime: Math.round(averageResponseTime),
      errorRate: Math.round(errorRate * 100) / 100,
      activeUsers,
      memoryUsage: Math.round(memoryUsage / 1024 / 1024), // Convert to MB
      cpuUsage: Math.round(cpuUsage * 100) / 100,
    };
  }

  /**
   * Clear old metrics
   */
  public clearOldMetrics(olderThanHours: number = 24): void {
    const cutoffTime = Date.now() - (olderThanHours * 60 * 60 * 1000);
    const initialLength = this.metrics.length;

    this.metrics = this.metrics.filter(
      metric => new Date(metric.timestamp).getTime() > cutoffTime
    );

    const removedCount = initialLength - this.metrics.length;
    if (removedCount > 0) {
      this.logger.info(`Cleared ${removedCount} old metrics`);
    }
  }

  /**
   * Enable/disable monitoring
   */
  public setEnabled(enabled: boolean): void {
    this.isEnabled = enabled;
    this.logger.info(`Performance monitoring ${enabled ? 'enabled' : 'disabled'}`);
  }

  /**
   * Get current metrics count
   */
  public getMetricsCount(): number {
    return this.metrics.length;
  }

  /**
   * Export metrics for external analysis
   */
  public exportMetrics(): PerformanceMetrics[] {
    return [...this.metrics];
  }

  /**
   * Get performance alerts
   */
  public getPerformanceAlerts(): Array<{
    type: string;
    message: string;
    severity: 'low' | 'medium' | 'high' | 'critical';
    timestamp: string;
  }> {
    const alerts: Array<{
      type: string;
      message: string;
      severity: 'low' | 'medium' | 'high' | 'critical';
      timestamp: string;
    }> = [];

    const stats = this.getPerformanceStats(1); // Last hour

    // High error rate alert
    if (stats.errorRate > 10) {
      alerts.push({
        type: 'high_error_rate',
        message: `High error rate detected: ${stats.errorRate}%`,
        severity: stats.errorRate > 25 ? 'critical' : 'high',
        timestamp: new Date().toISOString(),
      });
    }

    // Slow response time alert
    if (stats.averageResponseTime > 3000) {
      alerts.push({
        type: 'slow_response_time',
        message: `Slow average response time: ${stats.averageResponseTime}ms`,
        severity: stats.averageResponseTime > 10000 ? 'critical' : 'high',
        timestamp: new Date().toISOString(),
      });
    }

    // High throughput alert
    if (stats.throughput > 1000) {
      alerts.push({
        type: 'high_throughput',
        message: `High throughput detected: ${stats.throughput} requests/min`,
        severity: 'medium',
        timestamp: new Date().toISOString(),
      });
    }

    return alerts;
  }
}

// Export singleton instance
export const performanceMonitor = new PerformanceMonitor();

/**
 * Security Monitoring System
 * Monitors and alerts on security-related events and threats
 */

import { Logger } from './logger';
import { Request, Response } from 'express';

export interface SecurityEvent {
  timestamp: string;
  eventId: string;
  type: 'suspicious_activity' | 'brute_force' | 'injection_attempt' | 'unauthorized_access' | 'data_breach' | 'malicious_request' | 'rate_limit_exceeded';
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  source: {
    ip: string;
    userAgent?: string;
    userId?: string;
    sessionId?: string;
  };
  details: {
    endpoint?: string;
    method?: string;
    requestBody?: any;
    queryParams?: any;
    headers?: any;
    responseCode?: number;
    attackVector?: string;
    payload?: string;
  };
  riskScore: number; // 0-100
  blocked: boolean;
  actionTaken: string;
  environment: string;
  version: string;
}

export interface SecurityStats {
  totalEvents: number;
  eventsByType: Record<string, number>;
  eventsBySeverity: Record<string, number>;
  eventsBySource: Record<string, number>;
  blockedRequests: number;
  riskScoreDistribution: {
    low: number;    // 0-25
    medium: number; // 26-50
    high: number;   // 51-75
    critical: number; // 76-100
  };
  topAttackVectors: Array<{
    vector: string;
    count: number;
    lastSeen: string;
  }>;
  topSourceIPs: Array<{
    ip: string;
    count: number;
    riskScore: number;
    lastSeen: string;
  }>;
}

export class SecurityMonitor {
  private logger: Logger;
  private events: SecurityEvent[];
  private maxEvents: number;
  private isEnabled: boolean;
  private blockedIPs: Set<string>;
  private suspiciousIPs: Map<string, { count: number; lastSeen: Date; riskScore: number }>;
  private rateLimitTracker: Map<string, { count: number; resetTime: number }>;

  constructor(maxEvents: number = 10000) {
    this.logger = new Logger('SecurityMonitor');
    this.events = [];
    this.maxEvents = maxEvents;
    this.isEnabled = true;
    this.blockedIPs = new Set();
    this.suspiciousIPs = new Map();
    this.rateLimitTracker = new Map();
  }

  /**
   * Monitor HTTP request for security threats
   */
  public monitorRequest(req: Request, res: Response): void {
    if (!this.isEnabled) {
      return;
    }

    const ip = req.ip || 'unknown';
    const userAgent = req.get('User-Agent') || 'unknown';
    const userId = (req as any).user?.id;
    const sessionId = (req as any).sessionID;

    // Check if IP is blocked
    if (this.blockedIPs.has(ip)) {
      this.logSecurityEvent({
        type: 'unauthorized_access',
        severity: 'high',
        description: 'Blocked IP attempted access',
        source: { ip, userAgent, userId, sessionId },
        details: {
          endpoint: req.path,
          method: req.method,
          requestBody: req.body,
          queryParams: req.query,
          headers: req.headers,
          responseCode: 403,
          attackVector: 'blocked_ip',
        },
        riskScore: 90,
        blocked: true,
        actionTaken: 'Request blocked - IP in blocklist',
      });
      return;
    }

    // Check for suspicious patterns
    const threats = this.detectThreats(req);

    if (threats.length > 0) {
      const highestThreat = threats.reduce((prev, current) => 
        current.riskScore > prev.riskScore ? current : prev
      );

      this.logSecurityEvent({
        type: highestThreat.type,
        severity: highestThreat.severity,
        description: highestThreat.description,
        source: { ip, userAgent, userId, sessionId },
        details: {
          endpoint: req.path,
          method: req.method,
          requestBody: req.body,
          queryParams: req.query,
          headers: req.headers,
          responseCode: res.statusCode,
          attackVector: highestThreat.attackVector,
          payload: highestThreat.payload,
        },
        riskScore: highestThreat.riskScore,
        blocked: highestThreat.blocked,
        actionTaken: highestThreat.actionTaken,
      });

      // Update suspicious IP tracking
      this.updateSuspiciousIP(ip, highestThreat.riskScore);
    }

    // Check rate limiting
    this.checkRateLimit(ip, req.path);
  }

  /**
   * Detect security threats in request
   */
  private detectThreats(req: Request): Array<{
    type: SecurityEvent['type'];
    severity: SecurityEvent['severity'];
    description: string;
    riskScore: number;
    blocked: boolean;
    actionTaken: string;
    attackVector: string;
    payload?: string;
  }> {
    const threats: Array<{
      type: SecurityEvent['type'];
      severity: SecurityEvent['severity'];
      description: string;
      riskScore: number;
      blocked: boolean;
      actionTaken: string;
      attackVector: string;
      payload?: string;
    }> = [];

    const { path, method, body, query, headers } = req;
    const requestString = JSON.stringify({ path, method, body, query, headers }).toLowerCase();

    // SQL Injection detection
    const sqlPatterns = [
      /union\s+select/i,
      /drop\s+table/i,
      /insert\s+into/i,
      /delete\s+from/i,
      /update\s+set/i,
      /or\s+1\s*=\s*1/i,
      /and\s+1\s*=\s*1/i,
      /';\s*drop/i,
      /--\s*$/i,
      /\/\*.*\*\//i,
    ];

    for (const pattern of sqlPatterns) {
      if (pattern.test(requestString)) {
        threats.push({
          type: 'injection_attempt',
          severity: 'high',
          description: 'SQL injection attempt detected',
          riskScore: 85,
          blocked: true,
          actionTaken: 'Request blocked - SQL injection detected',
          attackVector: 'sql_injection',
          payload: this.extractPayload(requestString, pattern),
        });
      }
    }

    // XSS detection
    const xssPatterns = [
      /<script[^>]*>.*?<\/script>/i,
      /javascript:/i,
      /on\w+\s*=/i,
      /<iframe[^>]*>/i,
      /<object[^>]*>/i,
      /<embed[^>]*>/i,
      /<link[^>]*>/i,
      /<meta[^>]*>/i,
    ];

    for (const pattern of xssPatterns) {
      if (pattern.test(requestString)) {
        threats.push({
          type: 'injection_attempt',
          severity: 'high',
          description: 'XSS attempt detected',
          riskScore: 80,
          blocked: true,
          actionTaken: 'Request blocked - XSS detected',
          attackVector: 'xss',
          payload: this.extractPayload(requestString, pattern),
        });
      }
    }

    // Path traversal detection
    const pathTraversalPatterns = [
      /\.\.\//g,
      /\.\.\\/g,
      /%2e%2e%2f/gi,
      /%2e%2e%5c/gi,
    ];

    for (const pattern of pathTraversalPatterns) {
      if (pattern.test(requestString)) {
        threats.push({
          type: 'malicious_request',
          severity: 'medium',
          description: 'Path traversal attempt detected',
          riskScore: 70,
          blocked: true,
          actionTaken: 'Request blocked - Path traversal detected',
          attackVector: 'path_traversal',
          payload: this.extractPayload(requestString, pattern),
        });
      }
    }

    // Command injection detection
    const commandPatterns = [
      /;\s*rm\s+-rf/i,
      /;\s*cat\s+\/etc\/passwd/i,
      /;\s*ls\s+-la/i,
      /;\s*whoami/i,
      /;\s*id/i,
      /;\s*uname/i,
      /;\s*ps\s+aux/i,
      /;\s*netstat/i,
    ];

    for (const pattern of commandPatterns) {
      if (pattern.test(requestString)) {
        threats.push({
          type: 'injection_attempt',
          severity: 'critical',
          description: 'Command injection attempt detected',
          riskScore: 95,
          blocked: true,
          actionTaken: 'Request blocked - Command injection detected',
          attackVector: 'command_injection',
          payload: this.extractPayload(requestString, pattern),
        });
      }
    }

    // Suspicious user agent
    const suspiciousUserAgents = [
      /sqlmap/i,
      /nikto/i,
      /nmap/i,
      /masscan/i,
      /zap/i,
      /burp/i,
      /w3af/i,
      /havij/i,
      /acunetix/i,
      /nessus/i,
    ];

    for (const pattern of suspiciousUserAgents) {
      if (pattern.test(userAgent)) {
        threats.push({
          type: 'suspicious_activity',
          severity: 'medium',
          description: 'Suspicious user agent detected',
          riskScore: 60,
          blocked: false,
          actionTaken: 'Request flagged - Suspicious user agent',
          attackVector: 'suspicious_user_agent',
        });
      }
    }

    // Unusual request patterns
    if (this.isUnusualRequest(req)) {
      threats.push({
        type: 'suspicious_activity',
        severity: 'low',
        description: 'Unusual request pattern detected',
        riskScore: 40,
        blocked: false,
        actionTaken: 'Request flagged - Unusual pattern',
        attackVector: 'unusual_pattern',
      });
    }

    return threats;
  }

  /**
   * Check if request is unusual
   */
  private isUnusualRequest(req: Request): boolean {
    const { path, method, headers } = req;

    // Check for unusual headers
    const unusualHeaders = [
      'x-forwarded-for',
      'x-real-ip',
      'x-originating-ip',
      'x-remote-ip',
      'x-remote-addr',
    ];

    const hasUnusualHeaders = unusualHeaders.some(header => 
      headers[header] && headers[header] !== req.ip
    );

    // Check for unusual paths
    const unusualPaths = [
      /\.\./,
      /\/admin/,
      /\/wp-admin/,
      /\/phpmyadmin/,
      /\/adminer/,
      /\/\.env/,
      /\/config/,
      /\/backup/,
    ];

    const hasUnusualPath = unusualPaths.some(pattern => pattern.test(path));

    // Check for unusual methods
    const unusualMethods = ['TRACE', 'OPTIONS', 'CONNECT'];
    const hasUnusualMethod = unusualMethods.includes(method);

    return hasUnusualHeaders || hasUnusualPath || hasUnusualMethod;
  }

  /**
   * Extract payload from request string
   */
  private extractPayload(requestString: string, pattern: RegExp): string {
    const match = pattern.exec(requestString);
    return match ? match[0] : '';
  }

  /**
   * Check rate limiting
   */
  private checkRateLimit(ip: string, endpoint: string): void {
    const key = `${ip}:${endpoint}`;
    const now = Date.now();
    const windowMs = 60 * 1000; // 1 minute
    const maxRequests = 100; // Max requests per minute per endpoint

    const current = this.rateLimitTracker.get(key);

    if (!current) {
      this.rateLimitTracker.set(key, { count: 1, resetTime: now + windowMs });
      return;
    }

    // Reset if window expired
    if (now > current.resetTime) {
      this.rateLimitTracker.set(key, { count: 1, resetTime: now + windowMs });
      return;
    }

    // Increment count
    current.count++;

    // Check if limit exceeded
    if (current.count > maxRequests) {
      this.logSecurityEvent({
        type: 'rate_limit_exceeded',
        severity: 'medium',
        description: `Rate limit exceeded for ${endpoint}`,
        source: { ip },
        details: {
          endpoint,
          attackVector: 'rate_limit_exceeded',
        },
        riskScore: 50,
        blocked: true,
        actionTaken: 'Request blocked - Rate limit exceeded',
      });

      // Temporarily block IP
      this.blockedIPs.add(ip);
      setTimeout(() => {
        this.blockedIPs.delete(ip);
      }, 15 * 60 * 1000); // 15 minutes
    }
  }

  /**
   * Update suspicious IP tracking
   */
  private updateSuspiciousIP(ip: string, riskScore: number): void {
    const current = this.suspiciousIPs.get(ip);

    if (current) {
      current.count++;
      current.lastSeen = new Date();
      current.riskScore = Math.max(current.riskScore, riskScore);
    } else {
      this.suspiciousIPs.set(ip, {
        count: 1,
        lastSeen: new Date(),
        riskScore,
      });
    }

    // Block IP if risk score is too high
    if (riskScore > 80) {
      this.blockedIPs.add(ip);
      this.logger.warn('IP blocked due to high risk score', { ip, riskScore });
    }
  }

  /**
   * Log security event
   */
  private logSecurityEvent(eventData: Omit<SecurityEvent, 'timestamp' | 'eventId' | 'environment' | 'version'>): void {
    const event: SecurityEvent = {
      timestamp: new Date().toISOString(),
      eventId: this.generateEventId(),
      environment: process.env.NODE_ENV || 'development',
      version: process.env.npm_package_version || '1.0.0',
      ...eventData,
    };

    // Add to events array (with size limit)
    if (this.events.length >= this.maxEvents) {
      this.events.shift(); // Remove oldest event
    }
    this.events.push(event);

    // Log event
    this.logger.warn('Security event detected', {
      eventId: event.eventId,
      type: event.type,
      severity: event.severity,
      description: event.description,
      source: event.source,
      riskScore: event.riskScore,
      blocked: event.blocked,
    });

    // Send critical alerts
    if (event.severity === 'critical' || event.riskScore > 90) {
      this.sendSecurityAlert(event);
    }
  }

  /**
   * Generate unique event ID
   */
  private generateEventId(): string {
    return `sec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Send security alert
   */
  private async sendSecurityAlert(event: SecurityEvent): Promise<void> {
    try {
      // Send to Slack
      if (process.env.SLACK_WEBHOOK_URL) {
        await fetch(process.env.SLACK_WEBHOOK_URL, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            text: '🚨 Security Alert',
            attachments: [{
              color: 'danger',
              fields: [
                { title: 'Event ID', value: event.eventId, short: true },
                { title: 'Type', value: event.type, short: true },
                { title: 'Severity', value: event.severity, short: true },
                { title: 'Description', value: event.description, short: false },
                { title: 'Source IP', value: event.source.ip, short: true },
                { title: 'Risk Score', value: event.riskScore.toString(), short: true },
                { title: 'Blocked', value: event.blocked ? 'Yes' : 'No', short: true },
                { title: 'Action', value: event.actionTaken, short: false },
              ],
            }],
          }),
        });
      }

      // Send to email (if configured)
      if (process.env.SECURITY_EMAIL) {
        // This would integrate with your email service
        this.logger.info('Security alert email sent', { eventId: event.eventId });
      }
    } catch (error) {
      this.logger.error('Failed to send security alert', { error });
    }
  }

  /**
   * Get security statistics
   */
  public getSecurityStats(timeWindow?: number): SecurityStats {
    const now = Date.now();
    const windowMs = timeWindow ? timeWindow * 60 * 60 * 1000 : 24 * 60 * 60 * 1000; // Default 24 hours
    const cutoffTime = now - windowMs;

    // Filter events within time window
    const recentEvents = this.events.filter(
      event => new Date(event.timestamp).getTime() > cutoffTime
    );

    if (recentEvents.length === 0) {
      return {
        totalEvents: 0,
        eventsByType: {},
        eventsBySeverity: {},
        eventsBySource: {},
        blockedRequests: 0,
        riskScoreDistribution: { low: 0, medium: 0, high: 0, critical: 0 },
        topAttackVectors: [],
        topSourceIPs: [],
      };
    }

    // Calculate basic stats
    const totalEvents = recentEvents.length;
    const blockedRequests = recentEvents.filter(e => e.blocked).length;

    // Group by type
    const eventsByType: Record<string, number> = {};
    recentEvents.forEach(event => {
      eventsByType[event.type] = (eventsByType[event.type] || 0) + 1;
    });

    // Group by severity
    const eventsBySeverity: Record<string, number> = {};
    recentEvents.forEach(event => {
      eventsBySeverity[event.severity] = (eventsBySeverity[event.severity] || 0) + 1;
    });

    // Group by source IP
    const eventsBySource: Record<string, number> = {};
    recentEvents.forEach(event => {
      eventsBySource[event.source.ip] = (eventsBySource[event.source.ip] || 0) + 1;
    });

    // Risk score distribution
    const riskScoreDistribution = {
      low: recentEvents.filter(e => e.riskScore <= 25).length,
      medium: recentEvents.filter(e => e.riskScore > 25 && e.riskScore <= 50).length,
      high: recentEvents.filter(e => e.riskScore > 50 && e.riskScore <= 75).length,
      critical: recentEvents.filter(e => e.riskScore > 75).length,
    };

    // Top attack vectors
    const attackVectorCounts = new Map<string, { count: number; lastSeen: string }>();
    recentEvents.forEach(event => {
      if (event.details.attackVector) {
        const existing = attackVectorCounts.get(event.details.attackVector) || { count: 0, lastSeen: event.timestamp };
        attackVectorCounts.set(event.details.attackVector, {
          count: existing.count + 1,
          lastSeen: event.timestamp > existing.lastSeen ? event.timestamp : existing.lastSeen,
        });
      }
    });

    const topAttackVectors = Array.from(attackVectorCounts.entries())
      .map(([vector, data]) => ({
        vector,
        count: data.count,
        lastSeen: data.lastSeen,
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    // Top source IPs
    const sourceIPCounts = new Map<string, { count: number; riskScore: number; lastSeen: string }>();
    recentEvents.forEach(event => {
      const existing = sourceIPCounts.get(event.source.ip) || { count: 0, riskScore: 0, lastSeen: event.timestamp };
      sourceIPCounts.set(event.source.ip, {
        count: existing.count + 1,
        riskScore: Math.max(existing.riskScore, event.riskScore),
        lastSeen: event.timestamp > existing.lastSeen ? event.timestamp : existing.lastSeen,
      });
    });

    const topSourceIPs = Array.from(sourceIPCounts.entries())
      .map(([ip, data]) => ({
        ip,
        count: data.count,
        riskScore: data.riskScore,
        lastSeen: data.lastSeen,
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    return {
      totalEvents,
      eventsByType,
      eventsBySeverity,
      eventsBySource,
      blockedRequests,
      riskScoreDistribution,
      topAttackVectors,
      topSourceIPs,
    };
  }

  /**
   * Get blocked IPs
   */
  public getBlockedIPs(): string[] {
    return Array.from(this.blockedIPs);
  }

  /**
   * Get suspicious IPs
   */
  public getSuspiciousIPs(): Array<{
    ip: string;
    count: number;
    riskScore: number;
    lastSeen: Date;
  }> {
    return Array.from(this.suspiciousIPs.entries()).map(([ip, data]) => ({
      ip,
      ...data,
    }));
  }

  /**
   * Block IP
   */
  public blockIP(ip: string, reason: string): void {
    this.blockedIPs.add(ip);
    this.logger.warn('IP blocked manually', { ip, reason });
  }

  /**
   * Unblock IP
   */
  public unblockIP(ip: string): void {
    this.blockedIPs.delete(ip);
    this.logger.info('IP unblocked manually', { ip });
  }

  /**
   * Clear old events
   */
  public clearOldEvents(olderThanHours: number = 168): void { // Default 7 days
    const cutoffTime = Date.now() - (olderThanHours * 60 * 60 * 1000);
    const initialLength = this.events.length;

    this.events = this.events.filter(
      event => new Date(event.timestamp).getTime() > cutoffTime
    );

    const removedCount = initialLength - this.events.length;
    if (removedCount > 0) {
      this.logger.info(`Cleared ${removedCount} old security events`);
    }
  }

  /**
   * Enable/disable security monitoring
   */
  public setEnabled(enabled: boolean): void {
    this.isEnabled = enabled;
    this.logger.info(`Security monitoring ${enabled ? 'enabled' : 'disabled'}`);
  }

  /**
   * Get current events count
   */
  public getEventsCount(): number {
    return this.events.length;
  }

  /**
   * Export events for external analysis
   */
  public exportEvents(): SecurityEvent[] {
    return [...this.events];
  }
}

