  enableConsole: boolean;
  enableFile: boolean;
  enableRemote: boolean;
  filePath?: string;
  remoteEndpoint?: string;
  maxFileSize: number; // in MB
  maxFiles: number;
  enableRequestLogging: boolean;
  enableErrorLogging: boolean;
  enablePerformanceLogging: boolean;
}

export class StructuredLogger {
  private logger: Logger;
  private config: LogConfig;
  private requestCount: number;
  private isEnabled: boolean;

  constructor(config: Partial<LogConfig> = {}) {
    this.logger = new Logger('StructuredLogger');
    this.config = {
      level: 'info',
      enableConsole: true,
      enableFile: false,
      enableRemote: false,
      maxFileSize: 10,
      maxFiles: 5,
      enableRequestLogging: true,
      enableErrorLogging: true,
      enablePerformanceLogging: true,
      ...config,
    };
    this.requestCount = 0;
    this.isEnabled = true;
  }

  /**
   * Log a message with context
   */
  public log(
    level: LogContext['level'],
    message: string,
    context: Partial<LogContext> = {}
  ): void {
    if (!this.isEnabled || !this.shouldLog(level)) {
      return;
    }

    const logContext: LogContext = {
      timestamp: new Date().toISOString(),
      level,
      message,
      service: 'SSELFIE Studio',
      environment: process.env.NODE_ENV || 'development',
      version: process.env.npm_package_version || '1.0.0',
      ...context,
    };

    // Log to console
    if (this.config.enableConsole) {
      this.logToConsole(logContext);
    }

    // Log to file
    if (this.config.enableFile && this.config.filePath) {
      this.logToFile(logContext);
    }

    // Log to remote endpoint
    if (this.config.enableRemote && this.config.remoteEndpoint) {
      this.logToRemote(logContext);
    }
  }

  /**
   * Debug level logging
   */
  public debug(message: string, context?: Partial<LogContext>): void {
    this.log('debug', message, context);
  }

  /**
   * Info level logging
   */
  public info(message: string, context?: Partial<LogContext>): void {
    this.log('info', message, context);
  }

  /**
   * Warn level logging
   */
  public warn(message: string, context?: Partial<LogContext>): void {
    this.log('warn', message, context);
  }

  /**
   * Error level logging
   */
  public error(message: string, context?: Partial<LogContext>): void {
    this.log('error', message, context);
  }

  /**
   * Fatal level logging
   */
  public fatal(message: string, context?: Partial<LogContext>): void {
    this.log('fatal', message, context);
  }

  /**
   * Log HTTP request
   */
  public logRequest(req: Request, res: Response, responseTime?: number): void {
    if (!this.config.enableRequestLogging) {
      return;
    }

    const context: Partial<LogContext> = {
      requestId: this.generateRequestId(),
      endpoint: req.path,
      method: req.method,
      statusCode: res.statusCode,
      responseTime,
      userAgent: req.get('User-Agent'),
      ip: req.ip,
      userId: (req as any).user?.id,
      sessionId: (req as any).sessionID,
    };

    const level = res.statusCode >= 400 ? 'warn' : 'info';
    const message = `${req.method} ${req.path} ${res.statusCode}`;

    this.log(level, message, context);
  }

  /**
   * Log error with context
   */
  public logError(error: Error, context: Partial<LogContext> = {}): void {
    if (!this.config.enableErrorLogging) {
      return;
    }

    const errorContext: Partial<LogContext> = {
      ...context,
      error: {
        name: error.constructor.name,
        message: error.message,
        stack: error.stack,
      },
    };

    this.error('Error occurred', errorContext);
  }

  /**
   * Log performance metrics
   */
  public logPerformance(
    operation: string,
    duration: number,
    context: Partial<LogContext> = {}
  ): void {
    if (!this.config.enablePerformanceLogging) {
      return;
    }

    const performanceContext: Partial<LogContext> = {
      ...context,
      metadata: {
        ...context.metadata,
        operation,
        duration,
        performance: true,
      },
    };

    const level = duration > 5000 ? 'warn' : 'info';
    const message = `Performance: ${operation} took ${duration}ms`;

    this.log(level, message, performanceContext);
  }

  /**
   * Log database operation
   */
  public logDatabase(
    operation: string,
    table: string,
    duration: number,
    context: Partial<LogContext> = {}
  ): void {
    const dbContext: Partial<LogContext> = {
      ...context,
      metadata: {
        ...context.metadata,
        operation,
        table,
        duration,
        database: true,
      },
    };

    const level = duration > 1000 ? 'warn' : 'info';
    const message = `Database: ${operation} on ${table} took ${duration}ms`;

    this.log(level, message, dbContext);
  }

  /**
   * Log external API call
   */
  public logExternalApi(
    service: string,
    endpoint: string,
    method: string,
    statusCode: number,
    duration: number,
    context: Partial<LogContext> = {}
  ): void {
    const apiContext: Partial<LogContext> = {
      ...context,
      metadata: {
        ...context.metadata,
        service,
        endpoint,
        method,
        statusCode,
        duration,
        externalApi: true,
      },
    };

    const level = statusCode >= 400 || duration > 5000 ? 'warn' : 'info';
    const message = `External API: ${method} ${endpoint} ${statusCode} (${duration}ms)`;

    this.log(level, message, apiContext);
  }

  /**
   * Log authentication event
   */
  public logAuth(
    event: 'login' | 'logout' | 'register' | 'password_reset' | 'token_refresh',
    userId: string,
    success: boolean,
    context: Partial<LogContext> = {}
  ): void {
    const authContext: Partial<LogContext> = {
      ...context,
      userId,
      metadata: {
        ...context.metadata,
        event,
        success,
        authentication: true,
      },
    };

    const level = success ? 'info' : 'warn';
    const message = `Auth: ${event} ${success ? 'successful' : 'failed'} for user ${userId}`;

    this.log(level, message, authContext);
  }

  /**
   * Log business logic event
   */
  public logBusiness(
    event: string,
    entity: string,
    entityId: string,
    action: string,
    context: Partial<LogContext> = {}
  ): void {
    const businessContext: Partial<LogContext> = {
      ...context,
      metadata: {
        ...context.metadata,
        event,
        entity,
        entityId,
        action,
        business: true,
      },
    };

    this.info(`Business: ${event} - ${action} on ${entity} ${entityId}`, businessContext);
  }

  /**
   * Check if should log based on level
   */
  private shouldLog(level: LogContext['level']): boolean {
    const levels = ['debug', 'info', 'warn', 'error', 'fatal'];
    const currentLevelIndex = levels.indexOf(this.config.level);
    const messageLevelIndex = levels.indexOf(level);
    return messageLevelIndex >= currentLevelIndex;
  }

  /**
   * Log to console
   */
  private logToConsole(context: LogContext): void {
    const { level, message, timestamp, ...rest } = context;

    const logMessage = {
      timestamp,
      level: level.toUpperCase(),
      message,
      ...rest,
    };

    switch (level) {
      case 'debug':
        console.debug(JSON.stringify(logMessage, null, 2));
        break;
      case 'info':
        console.info(JSON.stringify(logMessage, null, 2));
        break;
      case 'warn':
        console.warn(JSON.stringify(logMessage, null, 2));
        break;
      case 'error':
      case 'fatal':
        console.error(JSON.stringify(logMessage, null, 2));
        break;
    }
  }

  /**
   * Log to file
   */
  private logToFile(context: LogContext): void {
    // This would implement file logging
    // For now, just log to console
    this.logger.debug('File logging not implemented', { context });
  }

  /**
   * Log to remote endpoint
   */
  private async logToRemote(context: LogContext): Promise<void> {
    try {
      if (this.config.remoteEndpoint) {
        await fetch(this.config.remoteEndpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(context),
        });
      }
    } catch (error) {
      this.logger.error('Failed to send log to remote endpoint', { error });
    }
  }

  /**
   * Generate unique request ID
   */
  private generateRequestId(): string {
    return `req_${Date.now()}_${++this.requestCount}`;
  }

  /**
   * Update configuration
   */
  public updateConfig(newConfig: Partial<LogConfig>): void {
    this.config = { ...this.config, ...newConfig };
    this.logger.info('Logging configuration updated', { config: this.config });
  }

  /**
   * Enable/disable logging
   */
  public setEnabled(enabled: boolean): void {
    this.isEnabled = enabled;
    this.logger.info(`Structured logging ${enabled ? 'enabled' : 'disabled'}`);
  }

  /**
   * Get current configuration
   */
  public getConfig(): LogConfig {
    return { ...this.config };
  }

  /**
   * Create child logger with additional context
   */
  public child(additionalContext: Partial<LogContext>): StructuredLogger {
    const childLogger = new StructuredLogger(this.config);
    childLogger.log = (level, message, context) => {
      this.log(level, message, { ...additionalContext, ...context });
    };
    return childLogger;
  }
}

// Export singleton instance
export const structuredLogger = new StructuredLogger({
  level: process.env.LOG_LEVEL as any || 'info',
  enableConsole: true,
  enableFile: process.env.NODE_ENV === 'production',
