        id: (Date.now() + 1).toString(),
        content: response,
        sender: 'victoria',
        timestamp: new Date(),
        context
      };

      setMessages(prev => [...prev, victoriaMessage]);
      setIsTyping(false);
    }, 1500);
  };

  return {
    messages,
    sendMessage,
    isTyping,
    clearMessages: () => setMessages([])
  };
}

